// DE KOPREGEL ALS DROP-ZONE — de brug tussen een strook en het sleepgebaar.
//
// HET PROBLEEM. Een drop-zone is de KOPREGEL van een kaart of rij (`<summary>`,
// `.op-summary`): dat is de balk die oplicht en waarop je loslaat. Maar de enige
// plek waar de bewerklaag in die kopregel iets mag tekenen is haar `<Haak>` —
// de leescomponenten mogen geen byte van deze laag importeren, en zij kennen de
// zone-registry dus niet. De strook zit ÍN die kopregel; van daaruit is hij één
// `closest()` omhoog te vinden.
//
// WAAROM DAT MAG. `meldDropZone` heeft alleen een element, een soort en een term
// nodig; welk element dat is, is een keuze van de montage (edit.js zegt daar
// niets over — de drie SOORT-namen zijn het contract, niet de DOM). De bevroren
// viewer koos dezelfde balken (doc.js `dropDoelNode`).
//
// WAAROM GEEN QUERY BIJ ELKE SLEEP. De registry is push, geen pull: elke zone
// meldt zich bij het TEKENEN aan en bij het opruimen af. Dat is de reden die in
// `sleepgebaar.ts` staat, en `dropDoel()` regelt het afmelden via `onCleanup` —
// dus deze functie hoort binnen de rendergang van de component aangeroepen te
// worden, wat een `ref`-callback per definitie is.
import { onMount } from 'solid-js';
import { dropDoel } from '../slepen/sleepgebaar.js';
import type { Term } from '../../../model-grens.js';

/** Meld de kopregel waarin `el` staat aan als drop-zone van deze soort.
 *
 *  `sel` is de kopregel die erbij hoort: `'summary'` voor een kaartkop,
 *  `'.op-summary'` voor een regelrij. Vindt hij er geen (de strook staat los, in
 *  een test of in het harnas), dan gebeurt er niets — een montage die niet in een
 *  kopregel landt hoort geen zone te verzinnen. */
export function zoneOpKop(
  el: HTMLElement | null, sel: string, soort: string, term: Term | null,
): void {
  if (!el || !term) return;
  // NA HET MONTEREN, en dat is geen voorzorg maar noodzaak. Een `ref`-callback
  // vuurt in Solid terwijl het element wordt GEMAAKT — vóór het in de boom hangt
  // — en `closest()` levert dan altijd `null`: de kopregel eromheen bestaat op dat
  // moment nog niet als voorouder. Zonder deze uitstel meldde zich dus geen
  // enkele zone aan, en de sleep lichtte nergens op. `onMount` draait ná de
  // insertie en binnen dezelfde eigenaar, dus de `onCleanup` in `dropDoel` blijft
  // aan de component hangen.
  onMount(() => {
    const kop = el.closest(sel) as HTMLElement | null;
    if (kop) dropDoel(kop, soort, term);
  });
}
