// HET GEDEELD-MERKTEKEN: deze knoop leeft in meer dan één kaart.
//
// BESLUIT MICHIEL (6 sep 2026). De Alt-kopie van het sleepgebaar hiernaast is
// `linkAttached`: één knoop, twee kaarten — geen kopie. Dat is precies wat de
// lezer wilde, maar het maakt élke latere bewerking van die knoop een bewerking
// in beide kaarten. Zonder merkteken is dat onzichtbaar tot iemand het merkt.
//
// GEEN ✎-WAARSCHUWING. De overwogen vorm was een waarschuwing bij het bewerken
// ("let op, dit werkt in 2 kaarten door"). Die is afgevallen: zij vraagt bij
// élke bewerking opnieuw om aandacht voor iets dat de lezer zelf heeft gemaakt,
// en zij komt te laat — pas als hij al aan het bewerken is. Het merkteken staat
// er altijd, kost één regelhoogte niets, en zegt het vóóraf.
//
// TELLEN IN KAARTEN, niet in ouders. Een voorwaarde die twee keer onder
// dezelfde regel hangt is geen gedeelde knoop in de zin die de lezer bedoelt;
// twee KAARTEN wel — dat is de eenheid waarin het document is ingedeeld en de
// eenheid waarin "hier bewerken raakt daar" iets betekent.
import { Show, createMemo, onCleanup } from 'solid-js';
import type { JSX } from 'solid-js';
import type { Term } from '../../../model-grens.js';
import { model } from '../../../stores/corpus.js';
import { termVan } from '../integratie/anker.js';
import { tekst } from '../../../stores/weergave.js';
import { eigenVoorwaarden } from '../../kaart/invulling.jsx';
import type { DekkingsRegel } from '../../kaart/invulling.jsx';
import './slepen.css';

/** DE OPLICHT-KLASSE VAN HET BESTAANDE MECHANISME (invulling.tsx r.470,
 *  invulling.css). Bewust hergebruikt en niet nagebouwd: het paneel licht al
 *  jaren op deze manier op, de lezer kent het beeld, en een tweede oplichtstijl
 *  ernaast zou twee betekenissen geven aan hetzelfde gebaar. `gedeeld.test.tsx`
 *  pint de naam tegen invulling.css vast. */
export const GEDEELD_HL = 'is-ref-hl';

/** Eén kaart waarin de knoop leeft. */
export interface GedeeldeKaart { iri: string; titel: string }

interface KnoopKort { term?: Term | null }
/** Een VOORWAARDE, en haar leden. Een logische voorwaarde (`odrl:and/or/xone`)
 *  draagt haar leden als volwaardige kind-objecten mét eigen term (parse.js
 *  r.842), en de kaart tekent die als eigen rijen — dus tellen ze mee. */
interface VoorwaardeKort extends KnoopKort { children?: VoorwaardeKort[] }
interface RegelKort extends KnoopKort {
  constraints?: VoorwaardeKort[];
  refinements?: VoorwaardeKort[];
  /** De doelbinding: zij staat NIET in `refinements` maar in een eigen veld
   *  (parse.js r.1921) en zou anders als enige voorwaarderij buiten de telling
   *  vallen — juist de rij die het beslispunt draagt. */
  purposeConstraint?: VoorwaardeKort | null;
  duties?: RegelKort[];
  /** `odrl:consequence`: wat er hoort te gebeuren als deze plicht niet wordt
   *  nagekomen. Zelf een Duty, met dezelfde lezer gelezen (parse.js r.2216) en
   *  in de kaart een eigen rij ("Gevolg bij niet-naleving"). */
  consequences?: RegelKort[];
}
interface PolicyKort extends KnoopKort {
  iri?: string;
  title?: string | null;
  permissions?: RegelKort[];
  prohibitions?: RegelKort[];
  obligations?: RegelKort[];
}
interface ModelKort {
  sets?: PolicyKort[]; offers?: PolicyKort[]; agreements?: PolicyKort[];
}

/** DE WORKER-HANDLE IS DE GEWONE VORM, ook hier (re-check I-2, 8 sep 2026).
 *
 *  Deze functie las `.value` van een modelterm. Dat werkt in jsdom — daar wordt
 *  het model in dezelfde draad gebouwd en zijn de termen echte N3-termen — en
 *  niet in de browser: het model komt via structured clone uit de worker, en
 *  `termType`/`value` zijn prototype-getters die dat niet overleven. Wat
 *  overblijft is `{ id }`, en dan gaf `kaartenVanKnoop` ALTIJD een lege lijst:
 *  het merkteken verscheen nooit, en niets viel om. Precies de valstrik die de
 *  ghost-lane al eens vond en die `termVan` bestaat om te sluiten.
 *
 *  `termVan` is de huisdecoder voor dit formaat (anker.ts): hij kent de kale
 *  handle, de echte term, een IRI-string en de `{term}`/`{iri}`-omhulsels. */
const sleutelVan = (term: Term | string | null | undefined): string =>
  termVan(term)?.value || '';

/** DE VOORWAARDEN DIE BIJ DE REGEL ZELF HOREN — dezelfde opsomming die de kaart
 *  en het invulling-paneel gebruiken (`eigenVoorwaarden`, invulling.tsx r.156:
 *  doelbinding, eigen voorwaarden, refinements). BEWUST GELEEND en niet
 *  nagebouwd: de vorige versie van deze wandeling somde de drie velden zelf op,
 *  vergat de doelbinding, en dat gat was in de UI onzichtbaar. Wie er ooit een
 *  vierde bron van voorwaarden bij zet, doet dat daar en krijgt hem hier gratis.
 *  De cast is de gebruikelijke grens: die module typeert wat ZIJ nodig heeft
 *  (dekkingsvelden), deze wandeling kijkt alleen naar `term` en `children`. */
const voorwaardenVan = (regel: RegelKort): VoorwaardeKort[] =>
  eigenVoorwaarden(regel as unknown as DekkingsRegel) as unknown as VoorwaardeKort[];

/** Zit `sleutel` in deze voorwaarde of in een van haar leden? */
function inVoorwaarde(c: VoorwaardeKort, sleutel: string, gezien: Set<unknown>): boolean {
  if (sleutelVan(c.term) === sleutel) return true;
  if (gezien.has(c)) return false;
  gezien.add(c);
  for (const kind of c.children || []) if (inVoorwaarde(kind, sleutel, gezien)) return true;
  return false;
}

/** Zit `sleutel` ergens in deze regel of eronder? De afdaling is die van de
 *  KAART — elke knoop die als eigen rij getekend wordt telt mee, want een
 *  bewerking daarop werkt door in élke kaart die hem bereikt:
 *    regel → haar voorwaarden (doelbinding, constraints, refinements)
 *          → de leden van een logische voorwaarde
 *          → haar plichten, en de CONSEQUENCES van die plichten (weer regels).
 *
 *  `gezien` houdt OBJECTEN bij en geen sleutels: een blank node zonder `.value`
 *  zou anders buiten de cykelbewaking vallen (review N-2), en objectidentiteit
 *  heeft dat gat niet. `regel.obligations` staat er bewust NIET bij: dat veld
 *  bestaat alleen op een policy, niet op een regel. */
function inRegel(regel: RegelKort, sleutel: string, gezien: Set<unknown>): boolean {
  if (sleutelVan(regel.term) === sleutel) return true;
  if (gezien.has(regel)) return false;
  gezien.add(regel);
  for (const c of voorwaardenVan(regel)) if (inVoorwaarde(c, sleutel, gezien)) return true;
  for (const d of regel.duties || []) if (inRegel(d, sleutel, gezien)) return true;
  for (const d of regel.consequences || []) if (inRegel(d, sleutel, gezien)) return true;
  return false;
}

function inKaart(pol: PolicyKort, sleutel: string): boolean {
  if (sleutelVan(pol.term) === sleutel) return true;
  const gezien = new Set<unknown>();
  for (const groep of [pol.permissions, pol.prohibitions, pol.obligations]) {
    for (const r of groep || []) if (inRegel(r, sleutel, gezien)) return true;
  }
  return false;
}

/** IN WELKE KAARTEN LEEFT DEZE KNOOP? Puur: geen DOM, geen store — het model en
 *  een term in, een lijst kaarten uit. Zo is de telling los te toetsen en kan
 *  elke rij hem aanroepen zonder een tweede wandeling over het model te
 *  verzinnen. */
export function kaartenVanKnoop(m: unknown, term: Term | string | null): GedeeldeKaart[] {
  const sleutel = sleutelVan(term);
  if (!m || !sleutel) return [];
  const mm = m as ModelKort;
  const uit: GedeeldeKaart[] = [];
  const gezien = new Set<string>();
  for (const pol of [...(mm.sets || []), ...(mm.offers || []), ...(mm.agreements || [])]) {
    const iri = pol.iri || sleutelVan(pol.term);
    if (!iri || gezien.has(iri)) continue;
    if (!inKaart(pol, sleutel)) continue;
    gezien.add(iri);
    uit.push({ iri, titel: pol.title || iri });
  }
  return uit;
}

// --- Het oplichten -----------------------------------------------------------
// VIA HET BESTAANDE MECHANISME: de kaarten zijn adresseerbaar op hun IRI
// (`data-ref`, kaart.tsx r.245) en krijgen de klasse van het invulling-paneel.
// Bewust GEEN import uit invulling.tsx: die module is leeschunk-eigendom en
// haar `markeer()` doet er meer omheen (ankers, randhint, scope) dan hier hoort.
// Wat gedeeld is, is het CONTRACT — de klasse en het attribuut — en dat is
// precies wat een test kan vastpinnen.
//
// ALLEEN DE KAART, en dat is de `<details>` (review M-4). Dezelfde IRI staat
// óók op andere elementen — `kop.tsx` zet hem op een `<dd>`, `leden.tsx` op een
// `<tr>` — en die zouden meelichten bij een kale attribuutselector. Het
// merkteken belooft "de andere KAARTEN lichten op"; een oplichtende
// waarde-cel ergens in de pagina is dan ruis die de belofte tegenspreekt.

/** De kaart met deze IRI. `details` is het element dat `kaart.tsx` tekent; de
 *  test pint dat vast tegen die bron, zodat een wissel van elementsoort hier
 *  luid omvalt in plaats van de oplichting stil weg te laten. */
const KAART_SELECTOR = (veiligeIri: string): string => `details[data-ref="${veiligeIri}"]`;

let opgelicht: HTMLElement[] = [];

function doof(): void {
  for (const n of opgelicht) n.classList?.remove(GEDEELD_HL);
  opgelicht = [];
}

function licht(iris: string[]): void {
  doof();
  if (typeof document === 'undefined') return;
  for (const iri of iris) {
    // Alleen " en \ hoeven te ontsnappen; de dubbele punten en schuine strepen
    // van een IRI zijn binnen een aangehaalde attribuutwaarde gewoon tekst
    // (zelfde afweging als zoekRef in stores/weergave.ts).
    const veilig = iri.replace(/["\\]/g, '\\$&');
    for (const n of document.querySelectorAll<HTMLElement>(KAART_SELECTOR(veilig))) {
      n.classList.add(GEDEELD_HL);
      opgelicht.push(n);
    }
  }
}

/** Het merkteken zelf.
 *
 *  `kaart`: de IRI van de kaart waarin dit merkteken STAAT — die licht niet mee
 *  op (je kijkt er al naar). Weglaten mag: dan lichten alle kaarten op, wat de
 *  vorm is voor een plek buiten de kaarten (de verkenner, een paneel).
 *
 *  GEEN TABSTOP. Het merkteken is geen bediening: alles wat het te zeggen heeft
 *  staat in zijn eigen tekst ("in 3 kaarten") en in zijn titel, en die leest een
 *  hulpmiddel gewoon mee. Er een vierde focusbaar element van maken op elke
 *  gedeelde rij zou de toetsenbordgang van het document verzwaren voor een
 *  oplichting die alleen met de ogen iets toevoegt. */
export function GedeeldMarker(props: {
  term: Term | string | null;
  kaart?: string | null;
}): JSX.Element {
  const kaarten = createMemo(() => kaartenVanKnoop(model(), props.term));
  const anderen = () => kaarten().map((k) => k.iri).filter((iri) => iri !== props.kaart);
  onCleanup(doof);
  return (
    <Show when={kaarten().length > 1}>
      <span
        class="gedeeld-merk"
        title={tekst('edit.gedeeldUitleg', { n: kaarten().length })}
        on:mouseenter={() => licht(anderen())}
        on:mouseleave={doof}
      >
        {tekst('edit.gedeeldTelling', { n: kaarten().length })}
      </span>
    </Show>
  );
}
