// DE GHOST-CHIP-PLACEHOLDERS: elke "+ …"-actie is een SCHIM van het element dat
// hij aanmaakt, op de plek waar dat element komt.
//
// Gedragsbron: `ghostRij` in viewer-bevroren/assets/bewerk-ui.js en de silhouetten
// (`ghostBadge`, `ghostChips`, `ghostKaart`) plus `ghostMetDoos` in
// viewer-bevroren/assets/doc.js (fase C taak 9d).
//
// DRIE REGELS die deze module afdwingt:
//  1. DE GHOST STAAT WAAR HET NIEUWE ELEMENT KOMT — onderaan de lijst waaraan
//     hij toevoegt. Waar de node hangt is de verantwoordelijkheid van de
//     aanroeper, maar het is waarom er geen menu meer is: een menu-item staat
//     bij het icoon dat je aanklikt, een ghost bij het gat dat hij vult.
//  2. DE GHOST ZIET ERUIT ALS ZIJN SOORTGENOTEN. De aanroeper geeft een `node`
//     mee — het SILHOUET, opgebouwd uit precies dezelfde klassen als de echte
//     rij erboven. bewerk.css maakt hem gestippeld en gedempt; hij kan dus per
//     definitie niet uit de pas raken met het echte element.
//  3. DE TYPE-KEUZE ZIT ÍN DE GHOST, niet in een submenu: meerdere `opties`
//     staan als segmenten naast elkaar in dezelfde ghost.
//
// Elke optie is een ECHTE <button> (geen span met role=button, zoals de
// strook-iconen): een placeholder is een gewone knop in de leesvolgorde, en er
// is hier geen roving-structuur te bewaren.
//
// PUUR: geen store-writes, geen mutatiepad. De aanroeper geeft de stand en de
// callback; `actieStand` uit strook.tsx maakt die stand uit zijn eigen toetsen.
//
// VERTAALNOOT: `on:click` en niet `onClick`, om dezelfde reden als in
// strook.tsx — Solid delegeert click naar het document, en een ghost staat in
// een <details>-body of op een klikbare rij die anders omklapt.
import { For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { REGEL_SLEUTEL } from '../gedeeld/chip.jsx';
import type { RegelSoort } from '../gedeeld/chip.jsx';
import { tekst } from '../../stores/weergave.js';
import { SlotIcoon } from './strook.jsx';
import './bewerk.css';

/** De klasse die golf B op de KAART-/RIJ-root zet om de hover/focus-dichtheid
 *  aan te zetten: de ghosts binnen die root staan gedimd-verborgen tot de muis
 *  boven de root komt of de focus erbinnen valt (dt3-spec §1, gelabelde
 *  verbetering — de bevroren viewer toont ze permanent). Zonder deze klasse
 *  gedraagt een ghost zich als in de bevroren viewer; de dichtheid is een
 *  eigenschap van de OMGEVING, niet van de ghost. Het "verbergen" is een
 *  visuele dempte (opacity): de knop blijft focusbaar en voorleesbaar, en de
 *  rij houdt zijn hoogte — zie de reden bij het blok in bewerk.css.
 *
 *  DE WAARDE WOONT IN `ui/gedeeld/bewerkhaak.tsx` (review I-1). Zij wordt gezet
 *  door de LEEScomponenten — `kaart.tsx` op de kaartwortel, `regels.tsx` op de
 *  regelrij — en die mogen niets uit deze map importeren. Hier staat hij als
 *  her-export, zodat het contract leesbaar blijft op de plek waar de ghosts
 *  wonen en golf A's eigen tests niets hoeven te weten van die verhuizing. */
export { GHOST_ONTHUL_KLASSE } from '../gedeeld/bewerkhaak.jsx';

/** Eén segment van een ghost. De drie standen zijn die van de actiestrook:
 *  aan, gelockt (gedimd + slotje, klik biedt de route naar de bewerkbron) en
 *  niet-van-toepassing (gedimd, aria-disabled, geen klik). Verschil met een
 *  strook-icoon: een optie VERDWIJNT niet als er niets om te schakelen valt,
 *  hij gaat uit met de reden erbij — zoals het menu-item deed dat hij vervangt. */
export type GhostOptie = {
  /** Tekstvorm voor een ghost die geen silhouet nodig heeft. */
  label?: string;
  /** Het silhouet: de chips/badge/pil van het element dat ontstaat. */
  node?: JSX.Element;
  cls?: string;
  titel?: string;
  aan: boolean;
  actie?: (e?: Event) => void;
};

function GhostKnop(props: { optie: GhostOptie }): JSX.Element {
  const heeftActie = () => typeof props.optie.actie === 'function';
  const stil = () => !props.optie.aan && !heeftActie();
  // `ghost-tekst` merkt de silhouetloze ghost: alleen dán draagt de KNOP zelf
  // de gestippelde rand. Draagt hij een silhouet, dan zit de streep al op de
  // badge/chip/pil daarbinnen.
  const klasse = () => ['ghost-optie', props.optie.node ? '' : 'ghost-tekst',
    props.optie.cls || '',
    props.optie.aan ? '' : (heeftActie() ? 'gelockt' : 'actie-uit')].filter(Boolean).join(' ');
  const uitleg = () => props.optie.titel || props.optie.label;
  return (
    <button
      type="button"
      class={klasse()}
      title={uitleg()}
      aria-label={uitleg()}
      aria-disabled={stil() ? 'true' : undefined}
      on:click={(e: MouseEvent) => {
        if (stil() || !props.optie.actie) return;
        e.preventDefault();
        e.stopPropagation();
        props.optie.actie(e);
      }}
    >
      {props.optie.node ?? props.optie.label ?? ''}
      <Show when={!props.optie.aan && heeftActie()}><SlotIcoon /></Show>
    </button>
  );
}

/** De ghost-rij: één of meer segmenten naast elkaar, op de plek waar het nieuwe
 *  element komt. */
export function GhostRij(props: { cls?: string; opties: GhostOptie[] }): JSX.Element {
  return (
    <div class={['ghost-rij', props.cls || ''].filter(Boolean).join(' ')}>
      <For each={props.opties.filter(Boolean)}>{(o) => <GhostKnop optie={o} />}</For>
    </div>
  );
}

/** De ghost in zijn eigen blok-omhulsel.
 *
 *  DE DOOS IS WEG (eigenaarsbesluit 9 sep 2026: "make editable doesn't need a
 *  confirmation button"). Hier hing de ontgrendel-doos onder de ghost: een
 *  gelockte ghost bood aan hiervan de bewerkbron te maken, en die mini-dialoog
 *  moest ergens landen. Sinds die klik meteen ontgrendelt (zie
 *  `integratie/stand.tsx`) valt er niets meer te landen.
 *
 *  DE WRAP BLIJFT, en dat is geen restant. Hij is de BLOK-context van de ghost:
 *  `.ghost-wrap { display: block }` houdt een ghost-rij op een eigen regel,
 *  ongeacht wat er in de flow om hem heen staat (een `<dd>`, een `<summary>`,
 *  een `.op-list`). De naam houdt zijn pariteitsbetekenis: `ghostMetDoos` in
 *  viewer-bevroren/assets/bewerk-ui.js is de vorm waar deze uit komt, en
 *  `pariteit-integratie.test.tsx` pint dat de kaart-ghosts diezelfde wortel
 *  gebruiken. */
export function GhostMetDoos(props: {
  cls?: string; opties: GhostOptie[];
}): JSX.Element {
  return (
    <div class="ghost-wrap">
      <GhostRij cls={props.cls} opties={props.opties} />
    </div>
  );
}

/** HET SILHOUET VAN EEN REGEL-/PLICHTRIJ: de badge die de echte rij ook draagt
 *  (.method + soort, dus in de kleur van dat rijtype), met een "+" ervoor. Zo
 *  leest de ghost als "hier komt een toestemming/verplichting" en is de
 *  type-keuze de badge zelf — geen submenu. Het woord komt uit dezelfde
 *  i18n-sleutel als de echte badge (chip.tsx), zodat schim en origineel niet
 *  uit elkaar kunnen lopen. */
export function GhostBadge(props: { soort: RegelSoort; woord?: string }): JSX.Element {
  return (
    <span class={`method ${props.soort} ghost-badge`}>
      {`+ ${props.woord ?? tekst(REGEL_SLEUTEL[props.soort])}`}
    </span>
  );
}

/** HET SILHOUET VAN EEN VOORWAARDERIJ: dezelfde .c-chips met drie
 *  .c-slot-chips als een echte voorwaarde, maar met de slotnamen als
 *  schim-tekst. De `.c-ruimte`-spaties staan hier LETTERLIJK en niet als
 *  `<ChipRuimte>` uit `ui/kaart/voorwaarde-inhoud.tsx`: één import vanuit deze
 *  BEWERKchunk naar die LEESmodule maakt haar tot gedeelde chunk, en dan valt de
 *  leesinstap uiteen in twee scripts in plaats van één (gemeten: +1 chunk,
 *  +2,4 kB css apart). Twee tekens dubbel is goedkoper dan een chunkgrens. De "+" staat ERVOOR als eigen teken — de andere ghosts dragen
 *  hem in hun tekst, en een rij chips heeft daar geen plek voor. `aria-hidden`,
 *  want het aria-label van de knop zegt al voluit wat er ontstaat. */
export function GhostChips(): JSX.Element {
  return (
    <span class="ghost-chips-kop">
      <span class="ghost-plus" aria-hidden="true">+</span>
      <span class="c-chips">
        <span class="c-slot left ghost-slot">{tekst('edit.slotLinks')}</span>
        <span class="c-ruimte"> </span>
        <span class="c-slot op ghost-slot">{tekst('edit.slotOperator')}</span>
        <span class="c-ruimte"> </span>
        <span class="c-slot right ghost-slot">{tekst('edit.slotWaarde')}</span>
      </span>
    </span>
  );
}

/** HET SILHOUET VAN EEN KAART: de soort-pil plus een titelschim, zoals een
 *  kaartkop ze naast elkaar zet.
 *
 *  `pilCls`/`pilTekst` en niet een `Kaartsoort`: de aanroeper weet welke pil de
 *  kaart draagt die hij aanmaakt (chip.tsx houdt die tabel), en de ghost hoeft
 *  daar geen tweede, eigen kopie van te hebben — een tweede tabel is precies
 *  hoe schim en origineel uit elkaar gaan lopen. */
export function GhostKaart(props: {
  pilCls: string; pilTekst: string; titel: string;
}): JSX.Element {
  return (
    <span class="ghost-kaart-kop">
      <span class={`kind-pill ${props.pilCls} ghost-pil`}>{props.pilTekst}</span>
      <span class="offer-title ghost-titel">{props.titel}</span>
    </span>
  );
}
