// DE DRIE STANDEN, MET DE ONTGRENDEL-ROUTE ERAAN.
//
// `actieStand` (strook.tsx) kent de drie uitkomsten maar niet de bronnenlaag:
// hij vraagt de aanroeper of er een route is. Deze module is die aanroeper. Zij
// zet de vraag "is er iets te ontgrendelen?" één keer om in een antwoord van de
// kern.
//
// Gedragsbron: `actieStand` + `ontgrendelDoos`/`toonOntgrendel` in
// viewer-bevroren/assets/doc.js (fase C taken 7/9b), maar met de één-bewerkbron-
// semantiek van het spec-addendum van 6 sep: "gelockt" betekent één ding — dit
// leeft niet in DE bewerkbron — en het antwoord is één handeling.
//
// EIGENAARSBESLUIT 9 SEP 2026: "make editable doesn't need a confirmation
// button". Tot die datum stond hier `maakOntgrendel()`: een houder met een
// DOOS per kaart/rij, waarin een klik op een gelockt icoon een mini-dialoog
// opende ("Bewerken kan zodra {bron} de bewerkbron is" + "Maak dit de
// bewerkbron" / "Annuleren"). Die tussenstap is vervallen, om dezelfde reden als
// de verwijderbevestiging van 8 sep: alles eraan is omkeerbaar. Een lokale kopie
// laat het originele bestand ongemoeid, het slotje in het bronnenpaneel zet de
// keuze net zo makkelijk terug, en de vorige bewerkbron houdt zijn kopie. Een
// ja/nee-stap koopt daar niets voor wat één klik achteraf niet oplost.
//
// WAT DE DIALOOG ZEI, IS NIET WEG — het is verhuisd naar de TOOLTIP van
// hetzelfde icoon (`ontgrendelUitleg` in `actieStand`). Dat is dezelfde
// informatie op hetzelfde moment: vóór de klik, waar de bevroren viewer haar ook
// wilde hebben. En wat er ná de klik gebeurt, meldt de bronnenlaag zelf op de
// statusregel (`src.lokaalGemaakt`, zie `stores/bronbeheer.ts`) — niet-blokkerend
// en aria-live, precies zoals het eigenaarsbesluit vraagt.
//
// WAT BLIJFT: de WEIGERING. Levert `kern.ontgrendeldoel(...)` `null` op (geen
// OPFS, een pseudobron uit een endpoint-CONSTRUCT, of een knoop die al in de
// bewerkbron staat), dan gaat het icoon uit met zijn reden. Alleen de ja/nee-stap
// verdween; een nee blijft een nee.
import { actieStand, ontgrendelUitleg } from '../strook.jsx';
import type { IcoonStand } from '../strook.jsx';
import type { Quad, Term } from '../../../model-grens.js';
import type { Kern } from './kern.js';

/** De stand van één icoon of ghost-segment, met de ontgrendel-route erin.
 *
 *  `term`/`blokkade` zijn wat de kern nodig heeft om de bron áchter het slot aan
 *  te wijzen: de knoop zelf, of — bij een ✕ — precies de quads die eraan gaan.
 *  Wie `term` en `blokkade` allebei weglaat, vraagt geen route: dat is de rem
 *  die de bevroren viewer met `term: nvt ? null : term` zette, voor rijen die
 *  ook ná het ontgrendelen structureel onbewerkbaar blijven. */
export function bewerkStand(kern: Kern, opts: {
  mag: boolean;
  titel?: string;
  actie?: (e?: Event) => void;
  term?: Term | null;
  blokkade?: Quad[] | null;
  nvt?: string;
  /** Vraagt deze aanroeper om de ontgrendel-route? Sinds 9 sep 2026 is dit een
   *  kale vlag en geen callback meer: er valt niets meer te openen, dus er is
   *  ook niets meer om door te geven. Weglaten = geen route, net als voorheen. */
  ontgrendelbaar?: boolean;
}): IcoonStand {
  if (opts.mag) return actieStand({ mag: true, titel: opts.titel, actie: opts.actie });
  const vraagt = !!(opts.term || (opts.blokkade && opts.blokkade.length));
  const doel = vraagt && opts.ontgrendelbaar
    ? kern.ontgrendeldoel(opts.term ?? null, opts.blokkade ?? null) : null;
  return actieStand({
    mag: false,
    titel: opts.titel,
    nvt: opts.nvt,
    ontgrendelbaar: !!doel,
    // ÉÉN KLIK, en de fout landt niet stil: `maak()` meldt zelf op de
    // statusregel wat er gebeurde (of wat er misging — `src.opfsFout`,
    // `src.kopieLeeg`), dus hier is een lege catch juist en geen wegkijken.
    opOntgrendel: doel ? () => { void doel.maak().catch(() => {}); } : undefined,
    ontgrendelUitleg: doel ? ontgrendelUitleg(doel) : undefined,
  });
}
