// DE SLEEP-VISUALS: het zwevende spookje, de drop-doel-klassen en de
// action-refinement-zone.
//
// Gedragsbron: `sleepGhost`/`plaatsGhost` en het drop-doel-blok van
// viewer-bevroren/assets/doc.js (fase C taak 8), plus de bijbehorende regels in doc.css.
//
// WAT HIER NIET WOONT: het gebaar zelf. Pointer-capture en pointerId-bewaking,
// `geldigeDropDoelen`, de Alt-kopie-semantiek en de laagorde van de
// Escape-annulering horen bij golf B (lane-slepen), met de mutatiekern erachter.
// Deze module levert de VORMEN die dat gebaar zichtbaar maken, en de
// klassenamen waarop het gebaar en de stijl elkaar vinden — als constanten, niet
// als losse strings verspreid over de integratielaag.
//
// DE ⠿-GREEP ZELF is sinds fase C taak 9b het eerste icoon van de actiestrook
// (strook.tsx). Wat een greep tot greep maakt — een cursor en een aanraking die
// niet scrollt — staat in bewerk.css op `.drag-handle`, en die klasse zet de
// strook alleen op een greep die ECHT kan slepen. Zo lopen de vier iconen van
// één strook niet uit elkaar in maat, kleur en dempte.
import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { tekst } from '../../stores/weergave.js';
import './bewerk.css';

/** De greep-klasse; de actiestrook zet hem op de ⠿ zodra die aan staat. */
export const SLEEP_GREEP = 'drag-handle';
/** Alle geldige plekken lichten op zodra een sleep begint … */
export const DROP_DOEL = 'drop-doel';
/** … en de plek waar de muis NU boven hangt krijgt er een vol accent bovenop,
 *  zodat loslaten voorspelbaar is. */
export const DROP_DOEL_ACTIEF = 'drop-doel-actief';
/** Op <body> tijdens een VOORWAARDE-sleep: alleen dan bestaat de actie-zone als
 *  zichtbaar doel. Buiten dat gebaar zou zij op elke regelrij een los "↳ Actie"
 *  achterlaten, en bij een regel- of plicht-sleep is zij geen geldig doel. */
export const SLEEPT_VOORWAARDE = 'sleept-voorwaarde';

/** Het zwevende spookje onder de muis tijdens een sleep.
 *
 *  `x`/`y` zijn de muispositie; het spookje staat er 12 pixels naast, precies
 *  als in de bevroren viewer — op de stip zelf zou het het drop-doel bedekken
 *  dat de lezer aanwijst. Vangen doet het niets (`pointer-events: none` in
 *  bewerk.css): anders wijst `elementFromPoint` tijdens de beweging naar het
 *  spookje in plaats van naar het doel eronder. */
export function SleepSpook(props: {
  naam?: string;
  hint?: string;
  x: number;
  y: number;
}): JSX.Element {
  return (
    <div
      class="sleep-spook"
      style={{ left: `${(Number(props.x) || 0) + 12}px`, top: `${(Number(props.y) || 0) + 12}px` }}
    >
      {/* Bewust NIET de greep-instructie als terugval: "je sleept: Sleep om te
          verplaatsen" leest als onzin. */}
      <span>{props.naam || tekst('edit.sleepNaamloos')}</span>
      <Show when={props.hint !== ''}>
        <span class="sleep-hint">{props.hint ?? tekst('edit.dropKopie')}</span>
      </Show>
    </div>
  );
}

/** De action-refinement-zone: zij bestaat uitsluitend om als drop-doel te
 *  kunnen oplichten, niet om als knop bediend te worden — vandaar een <span>
 *  zonder role en zonder tabstop. Haar zichtbaarheid hangt aan
 *  `SLEEPT_VOORWAARDE` op <body>. */
export function ActieDropZone(props: {
  extraCls?: string;
  /** De zone meldt zich bij het sleepgebaar aan als drop-doel; dat gebeurt bij
   *  de aanroeper, die de term van de regel kent. Vandaar een ref en geen eigen
   *  registratie: deze module is golf A en kent het gebaar niet. */
  ref?: (el: HTMLElement) => void;
} = {}): JSX.Element {
  return (
    <span
      ref={(el: HTMLElement) => props.ref?.(el)}
      class={['actie-drop-zone', props.extraCls || ''].filter(Boolean).join(' ')}
      title={tekst('edit.actieDropZone')}
    >{`↳ ${tekst('field.action')}`}</span>
  );
}
