// DE BEWERKAFFORDANCES VAN EEN KAART: de strook op de kop, de ghost-rij
// onderaan haar regellijst, en — alleen op een aanbod — de ghost-KAART voor de
// tweede trap.
//
// Gedragsbron: `kaartStrook`, `kaartRegelGhost` en `overeenkomstGhost` in
// viewer-bevroren/assets/doc.js (fase C taken 7/9b/9d/9f). GEEN NIEUW MUTATIEPAD: elke
// ghost roept exact de `voerUit`-route aan die zijn menu-item aanriep.
//
// WAT HIER ANDERS IS DAN IN DE BEVROREN VIEWER:
//   - de ✎ komt van BUITEN (`ctx.titelBewerk`). Het inline titelveld is van
//     lane-velden; laat die lane hem weg, dan draagt de strook drie iconen in
//     plaats van vier — precies wat `ActieStrook` doet met een sleutel die de
//     aanroeper weglaat. Een ✎ dat er staat maar niets opent zou erger zijn: de
//     strook belooft dat elk zichtbaar icoon zijn reden draagt, en "er is nog
//     geen veld voor gebouwd" is geen reden die de lezer aangaat.
//   - de ghosts zijn gedimd tot de muis of de focus binnen HUN KAART komt
//     (dt3-spec §1, de gelabelde verbetering — de bevroren viewer toont ze
//     permanent). De onthul-klasse staat op de kaartwortel in `kaart.tsx`, niet
//     hier: CSS kan niet omhoog kijken, en een omhulsel om de ghost zelf laat
//     hem zichzelf onthullen (review I-1).
import { createMemo, createSignal, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { tekst, zetMelding } from '../../../stores/weergave.js';
import { graafVersie } from '../../../stores/corpus.js';
import { ActieStrook } from '../strook.jsx';
import type { IcoonStand } from '../strook.jsx';
import { GhostBadge, GhostKaart, GhostMetDoos } from '../ghost.jsx';
import type { GhostOptie } from '../ghost.jsx';
import { IriCombobox } from '../veld.jsx';
import type { IriOptie } from '../veld.jsx';
import { Knop } from '../knop.jsx';
import {
  alsIriOpties, HergebruikRij, hergebruikSegment, REGEL_MELDING,
} from './hergebruik.jsx';
import { DROPDOEL } from '../slepen/sleepgebaar.js';
import { zoneOpKop } from './zones.js';
import { ODRL, termVan } from './anker.js';
import { bewerkStand } from './stand.jsx';
import type { Kern } from './kern.js';
import { focusAdres, vraagBewerkFocus } from '../../gedeeld/bewerkhaak.jsx';
import { toonToast } from '../toast.jsx';
import type { GroepHaakCtx, KaartHaakCtx } from '../../gedeeld/bewerkhaak.jsx';

/** De kaartsoort-pil die een NIEUWE overeenkomst draagt (chip.tsx houdt de
 *  tabel; hier alleen de klasse die het silhouet moet volgen). */
const AGR_PIL = 'agreement';

// Het koppelpredicaat van een verplichting op KAARTNIVEAU (odrl:obligation);
// onder een REGEL is het odrl:duty. Zie `RegelPlichtGhost` in rij-bewerk.tsx.
const OBLIGATION = `${ODRL}obligation`;

/** Een structuurmutatie die een NIEUWE knoop oplevert: uitvoeren, en zodra de
 *  weergave bij is naar die knoop springen. Zonder die sprong verdwijnt een
 *  nieuwe overeenkomst onderin een lijst van duizend kaarten.
 *
 *  LET OP het verschil met de ghosts die WÉL in de lijst eronder landen (+
 *  toestemming, + verbod, + verplichting): die springen bewust NIET. De rij
 *  verschijnt op de plek waar de ghost stond, en een sprong zou het beeld
 *  verzetten waar de lezer al kijkt — dat is de scroll-stabiliteitsles van
 *  fase C. De +overeenkomst is de gerichte uitzondering. */
function voerUitEnToon(kern: Kern, fn: (f: unknown) => unknown): void {
  let nieuw: unknown = null;
  void kern.voerUit((f) => { nieuw = fn(f); }, { groep: true })
    .then((ok) => {
      const ref = termVan(nieuw)?.value;
      if (!ok) return;
      if (ref) kern.spring(ref);
      // …en daarná de cursor in de titel van de nieuwe kaart (eis 2). Ná de
      // sprong: die brengt de kaart in beeld, en het veld hoeft dan alleen nog
      // zijn eigen `block: 'nearest'` te doen — dat is geen tweede sprong.
      vraagFocusOp(nieuw);
    })
    .catch(() => {});
}

/** DE CURSOR NAAR HET NIEUWE ELEMENT (eigenaarsbesluit 8 sep 2026, eis 2).
 *
 *  Alleen het ADRES gaat over de grens: het element bestaat op dit moment nog
 *  niet als component — de modelherbouw maakt hem pas — dus er valt niets aan te
 *  wijzen. Het titelveld dat zich op dat adres herkent, opent zichzelf. Zie het
 *  focusverzoek in `ui/gedeeld/bewerkhaak.tsx`.
 *
 *  Dit is GEEN sprong: het nieuwe element verschijnt op de plek van de ghost die
 *  je aanklikte, dus het staat al in beeld. Het veld focust met `preventScroll`
 *  en corrigeert hooguit met `block: 'nearest'` — de Δ0-poort van fase C
 *  (`ghost-scroll.mjs`) blijft daarmee ongewijzigd groen. */
export function vraagFocusOp(nieuw: unknown): void {
  const t = termVan(nieuw) as { id?: string; value?: string } | null;
  const adres = focusAdres(t ?? nieuw);
  if (adres) vraagBewerkFocus(adres);
}

// --- De strook op de kaartkop ------------------------------------------------

/** WAT RAAKT HET VERWIJDEREN VAN DEZE KAART? Alles wat `removePolicy` wegneemt:
 *  de sluiting, de inkomende verwijzingen én de benoemde regels en plichten die
 *  met het beleid mee verdwijnen. `policyWisQuads` somt precies die lijst op,
 *  dus de UI-toets en de mutatie kunnen niet uit elkaar lopen. */
function kaartWisQuads(kern: Kern, t0: unknown) {
  const g = kern.graaf();
  return (g && t0) ? kern.edit.policyWisQuads(g, t0) : [];
}

export function KaartkopStrook(props: { kern: Kern; ctx: KaartHaakCtx }): JSX.Element {
  const term = createMemo(() => termVan(props.ctx.pol));
  // Een STUB-versie of een blank-node-policy zonder term is een weergave-
  // constructie: geen mutatiepad, dus alle iconen uit — maar wel ZICHTBAAR,
  // met de reden. Niets wordt verborgen.
  const afgeleid = (): IcoonStand => ({ aan: false, titel: tekst('edit.kaartAfgeleid') });
  const wisQuads = createMemo(() => kaartWisQuads(props.kern, term()));
  return (
    <Show
      when={term()}
      fallback={(
        <ActieStrook
          sleep={{ aan: false, titel: tekst('edit.sleepKaartNvt') }}
          // HET ✎ VERSCHIJNT PRECIES WANNEER DE SEAM GEVULD IS (review I-2), hier
          // net zo goed als op de echte kop. Deze tak zette hem onvoorwaardelijk
          // neer met `naamAfgeleid` als reden, en dan draagt een STUB-kaart vier
          // iconen waar de echte kaart er drie heeft — de scheefheid liep de
          // verkeerde kant op. Is de seam er wél, dan wint de reden van deze tak:
          // aan een afgeleide naam valt niets te bewerken.
          bewerk={props.ctx.titelBewerk
            ? { aan: false, titel: tekst('edit.naamAfgeleid') } : undefined}
          dupliceer={afgeleid()}
          verwijder={afgeleid()}
        />
      )}
    >{(t0) => (
      <ActieStrook
        label={tekst('edit.strookLabel')}
        // DE KAARTKOP IS EEN DROP-DOEL — niet voor zichzelf maar voor de regels en
        // plichten die je hierheen sleept. Dat is de andere kant van de ⠿
        // hieronder: de kaart kan nergens heen, maar er kan wél iets naartoe.
        ref={(el) => zoneOpKop(el, 'summary', DROPDOEL.KAART, t0())}
        // ⠿ ALTIJD UIT: een kaart staat op zichzelf, er is geen ouder om hem
        // heen te slepen. Niet verbergen — dan zou de kaartkop een icoon minder
        // tonen dan de rij eronder, en dat is precies de ongelijkheid die het
        // strookprincipe wil vermijden.
        sleep={{ aan: false, titel: tekst('edit.sleepKaartNvt') }}
        bewerk={props.ctx.titelBewerk as IcoonStand | undefined}
        // DUPLICEREN kopieert de SLUITING naar een nieuwe IRI; een
        // blank-node-policy heeft geen IRI om van af te leiden — dan staat het
        // icoon er uit, met de reden, in plaats van te ontbreken.
        dupliceer={props.ctx.pol.anon || !props.ctx.pol.iri
          ? { aan: false, titel: tekst('edit.dupliceerGeenIri') }
          : bewerkStand(props.kern, {
            mag: props.kern.bewerkbaar(t0()),
            titel: tekst('edit.dupliceerUitleg'),
            actie: () => voerUitEnToon(props.kern,
              (f) => props.kern.edit.duplicatePolicy(f, props.ctx.pol.iri)),
            term: t0(),
            ontgrendelbaar: true,
          })}
        // VERWIJDEREN RAAKT MEER DAN DE KAART ZELF. De toets is daarom precies
        // de lijst die de mutatie gaat wissen; valt er één quad buiten de
        // bewerkbron, dan gaat het ✕ op slot en wijst het naar díe bron.
        verwijder={bewerkStand(props.kern, {
          mag: wisQuads().length > 0 && props.kern.quadsInBewerkbron(wisQuads()),
          titel: tekst('edit.beleidVerwijderen'),
          // GEEN BEVESTIGING MEER (eigenaarsbesluit 8 sep 2026). Zie de kop van
          // `ui/bewerk/toast.tsx`: met undo/redo kost een vraag vooraf bij elke
          // verwijdering een handeling om een vergissing te voorkomen die één
          // klik achteraf oplost. Er wordt gemeld wát er weg is, met de weg
          // terug ernaast.
          actie: () => {
            void props.kern.voerUit((f) => props.kern.edit.removePolicy(f, t0()),
              { groep: true })
              .then((ok) => { if (ok) toonToast('edit.beleidVerwijderd'); })
              .catch(() => {});
          },
          term: t0(),
          blokkade: wisQuads(),
          ontgrendelbaar: true,
        })}
      />
    )}</Show>
  );
}

// --- Een BESTAANDE benoemde regel hergebruiken -------------------------------
//
// EIGENAARSAANVULLING 9 SEP 2026, LETTERLIJK: "En ook voor rules; hoe je
// bestaande named rules kan hergebruiken i.p.v. opnieuw aanmaken".
//
// DE VORM IS EEN TWEEDE SEGMENT IN DEZELFDE GHOST, en dat is een RULING
// (lane-knoophergebruik; de brief laat de keuze: "een keuze in of naast de
// bestaande chip"). "+ toestemming" mint, "↻ hergebruik" ernaast koppelt — twee
// antwoorden op dezelfde vraag, op dezelfde plek, in dezelfde rij. De
// alternatieven waren een tweede dialoogstelsel (dat de brief uitsluit) of een
// keuze BINNEN de mint-chip (die dan twee dingen doet, en dat is precies de
// menu-vorm waar `ghost.tsx` regel 3 vanaf wilde: "de type-keuze zit ÍN de
// ghost, niet in een submenu").
//
// KOST BIJ ONGELIJK: één segment breder per sectiechip. Dat is de goedkoopste
// van de drie, en het segment gaat UIT met zijn reden zodra er niets te
// hergebruiken valt — dus op een leeg document ziet de lezer meteen waarom.
//
// DE KEUZELIJST ZELF is de gewone `IriCombobox`: dezelfde widget, dezelfde
// Escape, dezelfde filter-en-cap. Wat er anders aan is, staat in de opties: het
// bijschrift draagt naast de curie de HERKOMST ("uit Aanbod BRP"), want twee
// regels heten in dit domein makkelijk allebei "Raadplegen".

/** De drie soorten waarvoor een sectiechip bestaat, met hun koppelpredicaat op
 *  KAARTNIVEAU. Onder een regel heet de plicht `odrl:duty`; die route is die van
 *  `RegelPlichtGhost` en niet van deze. */
const KOPPEL_PRED: Record<string, string> = {
  toestemming: `${ODRL}permission`,
  verbod: `${ODRL}prohibition`,
  duty: OBLIGATION,
};

/** DE KANDIDATEN, gecachet op (graaf, graafversie) — dezelfde afweging als
 *  `veldOpties` in `ui/bewerk/kaartveld.tsx`: `regelOpties` scant de hele graaf,
 *  en een kaart met drie secties zou hem anders drie keer per render aanroepen.
 *  Alleen de RUWE lijst wordt bewaard; het bijschrift wordt per aanroep
 *  samengesteld, zodat een taalwissel hem meeneemt. */
let regelCache: { g: unknown; v: number; per: Record<string, {
  iri: string; curie: string | null; label: string; herkomst: string[];
}[]> } | null = null;

/** DE BESCHIKBARE KANDIDATEN VOOR DEZE PLEK: de benoemde regels van deze soort,
 *  min de regels die hier al aan hangen. Dat filter loopt over `koppelToets` en
 *  niet over een eigen toets ernaast — één bron van waarheid, zodat de lijst niet
 *  iets kan aanbieden dat de koppeling meteen weigert. */
function hergebruikOpties(kern: Kern, term: unknown, soort: string): IriOptie[] {
  const g = kern.graaf();
  const v = graafVersie();
  if (!g || !term) return [];
  if (!regelCache || regelCache.g !== g || regelCache.v !== v) {
    regelCache = { g, v, per: kern.edit.regelOpties(g) };
  }
  const pred = KOPPEL_PRED[soort];
  return alsIriOpties((regelCache.per[soort] || [])
    .filter((r) => kern.edit.koppelToets(g, term, pred, r.iri).ok));
}

/** DE KEUZERIJ VAN DE REGELKANT: de gedeelde `HergebruikRij` met de koppeling
 *  erachter. De VORM staat in `hergebruik.tsx` (dezelfde chip, dezelfde
 *  combobox, dezelfde Escape als de voorwaardekant); wat hier staat is wat een
 *  keuze BETEKENT.
 *
 *  NA DE KOPPELING: de toast meldt de deling, het verzoek zet de cursor in de
 *  gekoppelde rij (dezelfde `vraagFocusOp` als bij een verse regel) en de rij
 *  sluit zichzelf. GEEN SPRONG — de rij landt op de plek van deze keuzerij en
 *  staat dus al in beeld. */
function RegelHergebruikRij(props: {
  kern: Kern; term: unknown; soort: string; opSluiten: () => void;
}): JSX.Element {
  const opties = createMemo(() => hergebruikOpties(props.kern, props.term, props.soort));
  const kies = (iri: string): void => {
    const pred = KOPPEL_PRED[props.soort];
    // EERST HET OORDEEL, OP DE LEESGRAAF — zelfde reden als bij `hernoemToets`
    // in `kaartveld.tsx`: een afgewezen keuze mag geen lege mutatiegroep en dus
    // geen dode ↶ opleveren.
    const oordeel = props.kern.edit.koppelToets(props.kern.graaf(), props.term, pred, iri);
    if (!oordeel.ok) {
      zetMelding(REGEL_MELDING[oordeel.reden || ''] || 'edit.ongeldigeIri', { invoer: iri });
      return;
    }
    let nieuw: unknown = null;
    void props.kern.voerUit((f) => {
      nieuw = props.kern.edit.koppelRegel(f, props.term, pred, iri).term;
    }, { groep: true })
      .then((ok) => {
        if (!ok) return;
        toonToast('edit.regelGekoppeld');
        props.opSluiten();
        vraagFocusOp(nieuw);
      })
      .catch(() => {});
  };
  return (
    <HergebruikRij
      opties={opties()}
      kiesSleutel="edit.hergebruikKies"
      kies={kies}
      opSluiten={props.opSluiten}
    />
  );
}

// --- De ghost-rij onderaan de regellijst -------------------------------------

/** DE DRIE SEGMENTEN, in de volgorde van taak 9f: toestemming, verbod,
 *  verplichting. De eerste twee zijn elkaars spiegelbeeld (zelfde vorm, andere
 *  polariteit), de verplichting is een ander soort ding.
 *
 *  SINDS 9 SEP STAAN ZE NIET MEER SAMEN. Eigenaarsbesluit, letterlijk: "de add
 *  chips (+ toestemming + verbod + verplichting) staan allemaal onderaan. Bij die
 *  volgorde zie je de chips dus niet inline verschijnen. Zet meer een regel brede
 *  add-chip per sectie dan". De leeskant (`ui/kaart/regels.tsx`) roept deze
 *  component daarom één keer per SECTIE aan, met `ctx.soorten` = de soort van die
 *  sectie en `ctx.plaatsing = 'sectie'`; wat overblijft — de soorten waarvan deze
 *  kaart nog geen enkele regel heeft — komt in één aanroep met
 *  `plaatsing = 'verzamel'` onderaan.
 *
 *  DE COMPONENT ZELF WEET NIETS VAN SECTIES: hij filtert zijn segmenten en kiest
 *  zijn breedteklasse, meer niet. De PLEK is een leesvraag (waar staat welke
 *  soort in de lijst) en hoort dus aan de leeskant; hier zou zij een tweede,
 *  afwijkende kopie van diezelfde indeling worden. */
export function KaartRegelGhost(props: { kern: Kern; ctx: KaartHaakCtx }): JSX.Element {
  const term = createMemo(() => termVan(props.ctx.pol));
  // WELKE SOORT STAAT NU MET ZIJN KEUZELIJST OPEN? Eén tegelijk, en lokaal aan
  // dit ghost-blok: het verzamelblok onderaan en de sectiechips zijn losse
  // aanroepen van deze component, dus een keuzerij in de ene raakt de andere
  // niet.
  const [hergebruikOpen, zetHergebruikOpen] = createSignal<string | null>(null);
  const optie = (
    soort: 'toestemming' | 'verbod' | 'duty', woordSleutel: string,
    titelSleutel: string, cls: string, mut: (f: unknown, t0: unknown) => unknown,
  ): GhostOptie => {
    const t0 = term();
    const stand = bewerkStand(props.kern, {
      mag: props.kern.bewerkbaar(t0),
      titel: tekst(titelSleutel),
      // GEEN SPRONG (zie `voerUitEnToon`), WÉL DE CURSOR: de nieuwe rij landt
      // op de plek van deze ghost en staat dus al in beeld; wat er nog moet
      // gebeuren is dat je erin kunt typen (eis 2).
      actie: () => {
        let nieuw: unknown = null;
        void props.kern.voerUit((f) => { nieuw = mut(f, t0); }, { groep: true })
          .then((ok) => { if (ok) vraagFocusOp(nieuw); })
          .catch(() => {});
      },
      term: t0,
      ontgrendelbaar: true,
    });
    return {
      node: <GhostBadge soort={soort} woord={tekst(woordSleutel)} />,
      cls,
      titel: stand.titel,
      aan: stand.aan,
      actie: stand.actie,
    };
  };
  // WELKE SEGMENTEN: die van `ctx.soorten`, in de vaste volgorde van taak 9f.
  // De volgorde komt uit DEZE lijst en niet uit `ctx.soorten`, zodat een
  // verzamelblok met twee soorten er hetzelfde uitziet ongeacht in welke
  // volgorde de aanroeper ze noemt.
  const toont = (s: 'toestemming' | 'verbod' | 'duty'): boolean =>
    !props.ctx.soorten || props.ctx.soorten.includes(s);
  /** "↻ hergebruik" naast de mint-chip van dezelfde soort. Geen silhouet: er
   *  ontstaat geen nieuw element, er wordt er één BIJGEHAALD — een gestippelde
   *  schim van een toestemming zou dat tegenspreken. Staat er niets van deze
   *  soort klaar, dan gaat het segment UIT met zijn reden (en die zin wijst naar
   *  de andere helft van deze lane: een blanke regel is niet aanwijsbaar, geef
   *  hem eerst een naam). */
  const hergebruikOptie = (soort: 'toestemming' | 'verbod' | 'duty',
    cls: string): GhostOptie => {
    const t0 = term();
    return hergebruikSegment({
      kern: props.kern,
      term: t0,
      cls,
      aantal: hergebruikOpties(props.kern, t0, soort).length,
      uitleg: 'edit.hergebruikUitleg',
      geen: 'edit.hergebruikGeen',
      schakel: () => zetHergebruikOpen(hergebruikOpen() === soort ? null : soort),
    });
  };
  // De sectiechip is REGEL-BREED (het besluit: "een regel brede add-chip per
  // sectie"), het verzamelblok blijft de compacte rij die het was.
  const rijCls = () => (props.ctx.plaatsing === 'sectie'
    ? 'ghost-op-rij ghost-sectie-rij' : 'ghost-op-rij');
  return (
    <Show when={term()}>
      {/* GEEN EIGEN OMHULSEL MEER (review I-1): de onthul-klasse staat op de
          KAARTWORTEL, die `kaart.tsx` tekent — hier zou zij "de ghost onthult
          zichzelf" betekenen — en `GhostMetDoos` levert de `.ghost-wrap` zelf
          al. Wat er stond was dus een lege div om een lege div. */}
      <GhostMetDoos
        cls={rijCls()}
        opties={[
          // ZONDER DOEL-PLAATSHOUDER EN ZONDER ACTIE (eigenaarsverfijning 8 sep
          // 2026, 1c: "je kan ook onder grouping rules aanmaken zonder die
          // grouping waarde …. dat zou de default moeten zijn"; en de
          // testronde-bevinding van 9 sep: "Hij kiest zelf raadplegen als actie
          // bij nieuwe toestemming").
          //
          // Er hoeft hier niets meer UIT gezet te worden: `addRule` vult sinds
          // 9 sep alleen nog wat de aanroeper meegeeft. De doel-mint met het
          // label "(vul doel in)" en de `odrl:read`-prefill zijn daar weg, met
          // dezelfde reden als de tijdvoorwaarde van besluit 1b een laag hoger —
          // een dimensievakje dat de lezer nergens aanwees, en een actie die
          // niemand koos.
          //
          // De nieuwe regel valt daarmee als gewone rij naast de vakjes
          // (`buildLevel` in parse.js: een regel zonder eenduidige waarde op de
          // dimensie krijgt geen groepskop). Wil je hem er wél onder, dan zit de
          // snelkoppeling ÍN die verse regel — zie `VoorwaardeGhost` in
          // `rij-bewerk.tsx`.
          //
          // DE GHOST BINNEN EEN VAKJE (`GroepRegelGhost`) houdt zijn prefill
          // wél: daar heeft de PLEK een waarde, en die is niet verzonnen.
          toont('toestemming') && optie('toestemming', 'edit.toestemming',
            'edit.toestemmingToevoegen', 'kaart-toestemming-plus',
            (f, t0) => props.kern.edit.addPermission(f, t0)),
          toont('toestemming') && hergebruikOptie('toestemming', 'kaart-toestemming-hergebruik'),
          toont('verbod') && optie('verbod', 'edit.verbod', 'edit.verbodToevoegen',
            'kaart-verbod-plus',
            (f, t0) => props.kern.edit.addProhibition(f, t0)),
          toont('verbod') && hergebruikOptie('verbod', 'kaart-verbod-hergebruik'),
          toont('duty') && optie('duty', 'edit.verplichting', 'edit.plichtToevoegen',
            'kaart-plicht-plus',
            (f, t0) => props.kern.edit.addDuty(f, t0, OBLIGATION)),
          toont('duty') && hergebruikOptie('duty', 'kaart-plicht-hergebruik'),
          // `GhostRij` filtert de `false`-plekken zelf weg (`opties.filter(Boolean)`);
          // een segment dat niet bij deze sectie hoort verdwijnt dus, en gaat niet
          // gedimd-uit staan. Dat is het onderscheid met een NIET-VAN-TOEPASSING:
          // hier is de actie niet weg, hij staat een paar rijen verderop.
        ].filter(Boolean) as GhostOptie[]}
      />
      {/* DE KEUZERIJ, onder de ghost en dus op de plek waar de gekoppelde rij
          landt. Buiten `GhostMetDoos`, want dat is de ghost-rij zelf en een
          combobox is geen ghost-segment. */}
      <Show when={hergebruikOpen()}>{(soort) => (
        <RegelHergebruikRij
          kern={props.kern}
          term={term()}
          soort={soort()}
          opSluiten={() => zetHergebruikOpen(null)}
        />
      )}</Show>
    </Show>
  );
}

// --- De ghost-rij onderaan een GROEPEERNIVEAU --------------------------------

/** De dimensie die we kunnen VOORVULLEN. Eén, en dat is geen voorlopigheid maar
 *  wat het profiel draagt: de doelbinding is in ODRL-AP-NL een purpose-refinement
 *  op de actie-knoop van een regel (`setPurpose`, en `addPermission`/
 *  `addProhibition` nemen hem als `purposeIri` mee). Elke andere gedeclareerde
 *  dimensie is een refinement waarvan de mutatielaag geen schrijfroute heeft; daar
 *  gaat het segment UIT met zijn reden, en niet weg. */
const PURPOSE = `${ODRL}purpose`;

/** DE GHOST ONDERAAN EEN GROEPEERNIVEAU (eigenaarsbesluit 8 sep 2026, eis 5).
 *
 *  ÉÉN SEGMENT, en dat is de hele afweging. De kaart-ghost draagt er drie omdat
 *  alle drie de soorten in de regellijst van een kaart landen. Een groepeerniveau
 *  is per soort opgebouwd (`blokken()` in `regels.tsx` groepeert de toestemmingen
 *  en de verboden apart), dus van de drie zou er hier maar één in dít vakje
 *  terechtkomen — de andere twee zouden een rij maken die ergens anders
 *  verschijnt. Dat breekt de eerste regel van `ghost.tsx` ("de ghost staat waar
 *  het nieuwe element komt"), en met die regel de scroll-stabiliteit die eraan
 *  hangt. De drie samen staan onveranderd onderaan de kaart.
 *
 *  VERPLICHTINGEN zitten hier niet bij, en dat is geen keuze: `groepeer()` wordt
 *  alleen op toestemmingen en verboden losgelaten (de plichten hebben hun eigen
 *  laag, `plichten.tsx`). Er is dus geen duty-niveau om een ghost onder te zetten.
 *
 *  DE PREFILL IS EEN GEWONE WAARDE, geen vast gegeven — dezelfde lijn als eis 3:
 *  hij komt uit dezelfde `addPermission(..., { purposeIri })` die het drietraps
 *  ook gebruikt, en het Doel-veld van de nieuwe rij is daarna gewoon een veld. Hij
 *  telt als ÉÉN undo-stap samen met de toevoeging: `{ groep: true }` staat om de
 *  hele mutatie heen, en de voorvulling gebeurt binnen `addRule` zelf. */
export function GroepRegelGhost(props: { kern: Kern; ctx: GroepHaakCtx }): JSX.Element {
  const term = createMemo(() => termVan(props.ctx.pol));
  const soort = () => (props.ctx.soort === 'verbod' ? 'verbod' : 'toestemming');
  const voorTeVullen = () => props.ctx.dimIri === PURPOSE && !!props.ctx.waardeIri;
  const optie = (): GhostOptie => {
    const t0 = term();
    const waarde = props.ctx.waardeLabel || props.ctx.waardeIri || '';
    // NIET VOOR TE VULLEN: het segment blijft staan, uit, met de reden. Dat is de
    // strookregel ("niets wordt verborgen") en zij geldt hier des te sterker —
    // een ghost die op het ene niveau wél en op het andere niet verschijnt, laat
    // de lezer zoeken naar wat er anders is.
    if (!voorTeVullen()) {
      return {
        node: <GhostBadge soort={soort()} woord={tekst(`edit.${soort()}`)} />,
        cls: `groep-${soort()}-plus`,
        titel: tekst('edit.dimensieGeenVoorvulling'),
        aan: false,
      };
    }
    const stand = bewerkStand(props.kern, {
      mag: props.kern.bewerkbaar(t0),
      titel: tekst('edit.inDimensieToevoegen', { waarde }),
      actie: () => {
        const opts = { purposeIri: props.ctx.waardeIri as string };
        let nieuw: unknown = null;
        void props.kern.voerUit((f) => {
          nieuw = soort() === 'verbod'
            ? props.kern.edit.addProhibition(f, t0, opts)
            : props.kern.edit.addPermission(f, t0, opts);
        }, { groep: true })
          .then((ok) => { if (ok) vraagFocusOp(nieuw); })
          .catch(() => {});
      },
      term: t0,
      ontgrendelbaar: true,
    });
    return {
      node: <GhostBadge soort={soort()} woord={tekst(`edit.${soort()}`)} />,
      cls: `groep-${soort()}-plus`,
      titel: stand.titel,
      aan: stand.aan,
      actie: stand.actie,
    };
  };
  return (
    <Show when={term()}>
      <GhostMetDoos cls="ghost-op-rij" opties={[optie()]} />
    </Show>
  );
}

// --- "+ nieuw beleid": de ghost-kaart bovenaan de aanbodsectie ---------------

/** FASE C TAAK 7 (`nieuwBeleidPlaceholder`, doc.js r.3585). Eén klik zet een
 *  leeg DRIETRAPS in de bewerkbron: een aanbod, een overeenkomst daarop en een
 *  eerste toestemming. Hij is de enige ghost die niet aan een bestaande knoop
 *  hangt, en daarmee de enige route uit een LEEG document — zonder hem is een
 *  verse werkbron een doodlopende weg.
 *
 *  BOVENAAN de sectie en niet onderaan, anders dan de andere ghosts: hij maakt
 *  geen rij ín een lijst maar een nieuwe KAART, en `voerUitEnToon` springt er
 *  meteen heen. Waar hij staat is dus niet waar het resultaat landt, en dan is
 *  de plek van de bevroren viewer de juiste (dezelfde afweging als bij
 *  `OvereenkomstGhost`, met dezelfde uitkomst).
 *
 *  Deze plek had in de hele dt3-migratie geen eigenaar (review I-6): de i18n
 *  stond er in beide talen en werd door geen enkel bestand in `src/` gebruikt. */
export function NieuwBeleidGhost(props: { kern: Kern; ctx: KaartHaakCtx | object }): JSX.Element {
  void props.ctx;
  const optie = (): GhostOptie => {
    // GEEN TERM. De toets is niet "mag ik deze knoop bewerken" maar "is er een
    // bewerkbron"; `bewerkStand` zonder `term`/`blokkade` vraagt daarom geen
    // ontgrendelroute — er is geen bron aan te wijzen die dit zou deblokkeren.
    const stand = bewerkStand(props.kern, {
      mag: props.kern.heeftBewerkbron(),
      titel: tekst('edit.nieuwBeleidUitleg'),
      actie: () => voerUitEnToon(props.kern, (f) => props.kern.edit.createSkeleton(f).offerIri),
      ontgrendelbaar: true,
    });
    return {
      node: (
        <GhostKaart
          pilCls="offer"
          pilTekst={tekst('kind.offer')}
          titel={`+ ${tekst('edit.nieuwBeleid')}`}
        />
      ),
      cls: 'nieuw-beleid-knop',
      titel: stand.titel,
      aan: stand.aan,
      actie: stand.actie,
    };
  };
  return (
    <div class="nieuw-beleid">
      <GhostMetDoos cls="ghost-kaart-rij" opties={[optie()]} />
    </div>
  );
}

// --- De ghost-kaart onder een aanbod -----------------------------------------

/** "+ overeenkomst op dit aanbod". Anders dan de andere ghosts staat het
 *  RESULTAAT hier niet in de lijst eronder — een nieuwe overeenkomst landt in de
 *  sectie Overeenkomsten, en `voerUitEnToon` springt er meteen heen. De ghost
 *  hoort desondanks op de AANBOD-kaart: dat is waar de tweede trap van het
 *  drietraps begint en de enige plek waar "op dít aanbod" betekenis heeft. */
export function OvereenkomstGhost(props: { kern: Kern; ctx: KaartHaakCtx }): JSX.Element {
  const term = createMemo(() => termVan(props.ctx.pol));
  // `addAgreement` leidt de IRI van de nieuwe overeenkomst af van die van het
  // aanbod; een anoniem aanbod heeft er geen en krijgt deze ghost dus niet.
  const kan = () => !!term() && !props.ctx.pol.anon && !!props.ctx.pol.iri;
  return (
    <Show when={kan()}>
      {(() => {
        const t0 = term();
        const stand = bewerkStand(props.kern, {
          mag: props.kern.bewerkbaar(t0),
          titel: tekst('edit.overeenkomstToevoegen'),
          actie: () => voerUitEnToon(props.kern,
            (f) => props.kern.edit.addAgreement(f, props.ctx.pol.iri)),
          term: t0,
          ontgrendelbaar: true,
        });
        return (
          <GhostMetDoos
            cls="ghost-kaart-rij"
            opties={[{
              node: (
                <GhostKaart
                  pilCls={AGR_PIL}
                  pilTekst={tekst('kind.agreement')}
                  titel={`+ ${tekst('edit.overeenkomst')}`}
                />
              ),
              cls: 'kaart-agr-plus',
              titel: stand.titel,
              aan: stand.aan,
              actie: stand.actie,
            }]}
          />
        );
      })()}
    </Show>
  );
}
