// DE BEWERKAFFORDANCES VAN EEN RIJ: regel-/plichtrijen en voorwaarderijen.
//
// Gedragsbron: `regelStrook`, `regelPlichtGhost`, `voorwaardeStrook` en
// `voorwaardeToevoegen` in viewer-bevroren/assets/doc.js (fase C taken 6/7/8/9b/9d).
//
// DRIE REGELS uit dat blok gelden hier woord voor woord:
//  1. WEG IS WEG, LOS IS LOS. Het ✕ heet "verwijderen" als de knoop nergens
//     anders meer gebruikt wordt (`removeAttached` ruimt hem dan op) en
//     "losmaken" als hij dat wél wordt. De bevestigingsvraag zegt hetzelfde. Zo
//     staat er nooit "verwijder" op een knop die een gedeelde bouwsteen alleen
//     maar uit één beleid haalt.
//  2. EEN PLACEHOLDER OP EEN ONBEWERKBARE RIJ VERDWIJNT NIET, HIJ GAAT OP SLOT.
//  3. NIETS WORDT VERBORGEN: een icoon dat hier niet kan, blijft staan met zijn
//     reden in de tooltip.
//
// DE ⠿ IS GEMONTEERD (fixronde 8 sep 2026). Golf B leverde het sleepGEBAAR
// (`../slepen/sleepgebaar.ts`) en deze STROKEN, maar niemand verbond ze: hier
// stond `mag: false` met "het mechanisme komt van lane-slepen". Dat had twee
// gevolgen die het review als C-2 noteerde — de reden die de greep droeg ("de
// koppeling staat in een bron die alleen gelezen wordt") was op een volledig
// bewerkbare rij ONWAAR, en de ontgrendelroute ernaast leidde nergens heen: wie
// hem volgde wisselde zijn bewerkbron om en kreeg daarna nog steeds geen greep.
// `sleepGreep()` levert precies de `IcoonStand` die hier met de hand werd
// nagemaakt, mét de vier ware redenen; die is nu de bron.
import { createEffect, createMemo, createSignal, on, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { tekst, zetMelding } from '../../../stores/weergave.js';
import { graafVersie } from '../../../stores/corpus.js';
import { ActieStrook } from '../strook.jsx';
import type { IcoonStand } from '../strook.jsx';
import { ActieDropZone } from '../sleep.jsx';
import { GhostBadge, GhostChips, GhostMetDoos } from '../ghost.jsx';
import type { GhostOptie } from '../ghost.jsx';
import { DROPDOEL, SLEEPITEM, sleepGreep } from '../slepen/sleepgebaar.js';
import type { SleepItem } from '../slepen/sleepgebaar.js';
import { GedeeldMarker } from '../slepen/gedeeld.jsx';
import { zoneOpKop } from './zones.js';
import {
  blijftInGebruik, knoopAnker, KNOOP_PREDS, losmaakQuads, ODRL, termVan, voorwaardeAnker,
} from './anker.js';
import type { Anker } from './anker.js';
import { bewerkStand } from './stand.jsx';
import {
  alsIriOpties, HergebruikRij, hergebruikSegment, VOORWAARDE_MELDING,
} from './hergebruik.jsx';
import type { IriOptie } from '../veld.jsx';
import { SlotEditor } from './sloteditor.jsx';
import { doelbindingTerm, rijSoort, slotWaarden, slotsBewerkbaar } from './slots.js';
import { curie } from '../../../model/parse.js';
import { bewerkFocus, focusAdres, wisFocusVoor } from '../../gedeeld/bewerkhaak.jsx';
import { vraagFocusOp } from './kaart-bewerk.jsx';
import { toonToast } from '../toast.jsx';
import type { Kern } from './kern.js';
import type {
  CollectieHaakCtx, RegelHaakCtx, VoorwaardeHaakCtx,
} from '../../gedeeld/bewerkhaak.jsx';

const DUTY = `${ODRL}duty`;
/** De leftOperand van de doelbinding: de enige dimensie die het model in een
 *  EIGEN veld draagt (`rule.purpose`) in plaats van in `rule.refinements`. */
const PURPOSE_LEFT = `${ODRL}purpose`;

/** De velden van een voorwaarde-rij die de BEWERKlaag leest. Een eigen, smalle
 *  vorm en geen import van `ui/kaart/voorwaarde-inhoud.jsx`: de haak levert hem
 *  als `unknown` aan (de leeskant mag niets van deze map weten), en wat hier
 *  nodig is zijn vier velden. */
type VoorwaardeVorm = {
  doelbinding?: boolean;
  technicalMeasure?: boolean;
  logical?: string | null;
  children?: unknown[];
  slots?: { right?: { texts?: string[] } | null } | null;
  label?: string | null;
};

/** De ⠿ van een rij die niets te slepen heeft (geen item): uit, met dezelfde
 *  reden als de rest van de strook. */
const geenGreep = (reden: string): IcoonStand => ({ aan: false, titel: reden });

/** De iconen van een rij die GEEN eigen knoop in de graaf heeft: een
 *  groepeerniveau, een doelbinding, een andere weergave-constructie. Zichtbaar
 *  uit, met één reden.
 *
 *  DEZELFDE ICONEN ALS DE ECHTE RIJ, niet altijd alle vier (review I-2). Zij zette
 *  er onvoorwaardelijk vier neer, terwijl de rij eronder er drie heeft (regelrij)
 *  of twee (voorwaarderij) — een doelbindingsrij kreeg zo een ⧉ dat de rij eronder
 *  niet eens kent, en een ✎ dat nergens naar wijst. De ruling "de plek blijft
 *  bezet zodat de rijen niet ongelijk worden" motiveert zichzelf met gelijkheid;
 *  dan moet de afgeleide vorm de ECHTE vorm volgen en niet een eigen vorm zijn.
 *
 *  Het ✎ verschijnt precies wanneer de aanroeper er een meegeeft — op de echte
 *  rij én hier. De VOORWAARDErij bouwt hem sinds de sloteditor-ronde zelf (zie
 *  `VoorwaardeStrook`); de KAART- en REGELrij houden hun `titelBewerk`-seam, die
 *  vandaag door niemand gevuld wordt omdat het inline titelveld (`Veld` in
 *  `ui/kaart/regels.tsx`) zijn eigen ✎ draagt. Zie het lane-report. */
function AfgeleideStrook(props: {
  reden: string; bewerk?: IcoonStand; dupliceer?: boolean;
}): JSX.Element {
  const uit = (): IcoonStand => ({ aan: false, titel: props.reden });
  return (
    <ActieStrook
      sleep={uit()}
      bewerk={props.bewerk}
      dupliceer={props.dupliceer ? uit() : undefined}
      verwijder={uit()}
    />
  );
}

// --- De strook op een regel- of plichtrij ------------------------------------

export function RegelStrook(props: { kern: Kern; ctx: RegelHaakCtx }): JSX.Element {
  const term = createMemo(() => (props.ctx.afgeleid ? null : termVan(props.ctx.regel)));
  const anker = createMemo<Anker | null>(() => knoopAnker(
    props.kern.graaf(), term(), KNOOP_PREDS, props.ctx.ouder,
  ));
  const inGebruik = () => blijftInGebruik(props.kern.graaf(), anker(), term());
  const losQuads = createMemo(() => losmaakQuads(
    props.kern.graaf(), anker(), term(),
    (s, t) => props.kern.edit.closureQuads(s, t),
  ));
  const magLos = () => losQuads().length > 0 && props.kern.quadsInBewerkbron(losQuads());
  // WAT ER GESLEEPT WORDT, en waaraan het vandaag hangt. Precies het anker dat
  // ook het ✕ en het ⧉ gebruiken — een sleep verhuist die ene koppel-triple.
  // Zonder anker is er niets aan te wijzen en levert `sleepGreep` zelf de reden.
  const sleepItem = createMemo<SleepItem | null>(() => {
    const t0 = term(); const a = anker();
    if (!t0) return null;
    return {
      soort: SLEEPITEM.KNOOP,
      term: t0,
      ouder: a ? a.parent : null,
      pred: a ? a.pred : undefined,
      label: (props.ctx.regel as { title?: string | null }).title || undefined,
    };
  });
  return (
    <Show
      when={term()}
      fallback={(
        <AfgeleideStrook
          reden={tekst('edit.rijAfgeleid')}
          bewerk={props.ctx.titelBewerk as IcoonStand | undefined}
          dupliceer
        />
      )}
    >
      {(t0) => (
        <ActieStrook
          label={tekst('edit.strookLabel')}
          // DE REGELBALK IS ZELF EEN DROP-DOEL (een plicht mag eronder hangen), en
          // de actie-zone erin een tweede, genest doel. Beide melden zich vanaf
          // deze strook aan; zie `zones.ts` voor waarom dat vanaf hier gebeurt.
          ref={(el) => zoneOpKop(el, '.op-summary', DROPDOEL.REGEL, t0())}
          voor={(
            <>
              <GedeeldMarker term={t0()} kaart={props.ctx.scope ?? null} />
              <ActieDropZone
                ref={(el) => zoneOpKop(el, '.actie-drop-zone', DROPDOEL.ACTIE, t0())}
              />
            </>
          )}
          // DE SLEEP-GREEP, gemonteerd op het gebaar van golf B. `sleepGreep`
          // beslist zelf tussen aan en uit-met-reden; de vier redenen (geen
          // koppeling / niet in de bewerkbron / geen enkel doel / kan) zijn
          // daarmee op één plek berekend in plaats van hier nagemaakt.
          sleep={sleepItem()
            ? sleepGreep(sleepItem()!)
            : geenGreep(tekst('edit.sleepGeenKoppeling'))}
          bewerk={props.ctx.titelBewerk as IcoonStand | undefined}
          // DUPLICEREN hangt een kopie aan DEZELFDE ouder via dezelfde
          // koppeling; zonder aanwijsbare koppeling is er geen plek om de kopie
          // te hangen, en staat het icoon uit met de reden.
          dupliceer={anker()
            ? bewerkStand(props.kern, {
              mag: props.kern.bewerkbaar(t0()),
              titel: tekst('edit.dupliceerUitleg'),
              actie: () => {
                const a = anker()!;
                void props.kern.voerUit(
                  (f) => props.kern.edit.duplicateAttached(f, a.parent, a.pred, t0()),
                  { groep: true },
                );
              },
              term: t0(),
              ontgrendelbaar: true,
            })
            : { aan: false, titel: tekst('edit.dupliceerGeenKoppeling') }}
          verwijder={bewerkStand(props.kern, {
            mag: magLos(),
            titel: tekst(inGebruik() ? 'edit.knoopLosmaken' : 'edit.knoopVerwijderen'),
            // GEEN BEVESTIGING MEER (eigenaarsbesluit 8 sep 2026) — zie de kop
            // van `ui/bewerk/toast.tsx`. Het ONDERSCHEID blijft wél: "weg is weg,
            // los is los" was de reden dat er twee vragen stonden, en het is
            // evenzeer de reden dat er twee meldingen staan. Wat er gebeurde,
            // hoort de lezer te weten — vóóraf of achteraf.
            actie: () => {
              const a = anker();
              if (!a) return;
              const los = inGebruik();
              void props.kern.voerUit(
                (f) => props.kern.edit.removeAttached(f, a.parent, a.pred, t0()),
                { groep: true },
              )
                .then((ok) => {
                  if (ok) toonToast(los ? 'edit.knoopLosgemaakt' : 'edit.knoopVerwijderd');
                })
                .catch(() => {});
            },
            term: t0(),
            blokkade: losQuads(),
            nvt: tekst('edit.wegGeenKoppeling'),
            ontgrendelbaar: true,
          })}
        />
      )}
    </Show>
  );
}

// --- De ghost-rij onderaan de plichtenlijst van een regel --------------------

/** Eén segment: op deze plek valt er niets te kiezen — een plicht onder een
 *  regel is `odrl:duty`, punt. */
export function RegelPlichtGhost(props: { kern: Kern; ctx: RegelHaakCtx }): JSX.Element {
  const term = createMemo(() => (props.ctx.afgeleid ? null : termVan(props.ctx.regel)));
  const optie = (): GhostOptie => {
    const t0 = term();
    const stand = bewerkStand(props.kern, {
      mag: props.kern.bewerkbaar(t0),
      titel: tekst('edit.plichtOpRegel'),
      // Zelfde afspraak als bij de kaart-ghosts: geen sprong (de rij verschijnt
      // waar deze ghost staat), wél de cursor in haar naam (eis 2).
      actie: () => {
        let nieuw: unknown = null;
        void props.kern.voerUit((f) => { nieuw = props.kern.edit.addDuty(f, t0, DUTY); },
          { groep: true })
          .then((ok) => { if (ok) vraagFocusOp(nieuw); })
          .catch(() => {});
      },
      term: t0,
      ontgrendelbaar: true,
    });
    return {
      node: <GhostBadge soort="duty" woord={tekst('edit.verplichting')} />,
      cls: 'regel-plicht-plus',
      titel: stand.titel,
      aan: stand.aan,
      actie: stand.actie,
    };
  };
  return (
    <Show when={term()}>
      {/* De onthul-klasse staat op de REGELRIJ (regels.tsx), niet hier — zie
          review I-1 en de reden in `ui/gedeeld/bewerkhaak.tsx`. De `.ghost-wrap`
          komt van `GhostMetDoos` zelf. */}
      <GhostMetDoos cls="ghost-op-rij" opties={[optie()]} />
    </Show>
  );
}

// --- De voorwaarderij --------------------------------------------------------

/** DE STROOK VAN EEN VOORWAARDERIJ. Drie iconen, geen ⧉ — dupliceren van een
 *  voorwaarde was er in de bevroren viewer ook niet, en een tweede kopie van
 *  dezelfde grootheid/operator/waarde is geen bewerking die iets oplost.
 *
 *  HET ✎ IS SINDS DEZE RONDE ECHT (eindreview C-1, fase C taak 6). Hij stond
 *  hier als seam `ctx.slotBewerk`, te vullen door "lane-formulieren"; die seam
 *  was per constructie ONVULBAAR. Zijn waarde is een `IcoonStand` uit de
 *  BEWERKchunk, maar de ctx wordt gebouwd in `ui/kaart/voorwaarden.tsx` — een
 *  LEESchunk-module die geen byte van de bewerklaag mag importeren (spec §1).
 *  De enige plek waar het ✎ kán ontstaan is dus dit bestand, dat de strook toch
 *  al bouwt en de kern al heeft. Zie het lane-report voor wat er met de tweede
 *  open seam (`ctx.titelBewerk`) gebeurt.
 *
 *  DE EDITOR HANGT AAN DE RIJ, NIET IN DE STROOK. Deze component levert daarom
 *  twee broers: de strook (inline, rechts op de kopregel) en de `.c-editor-doos`
 *  van volle breedte eronder. Dat is precies de vorm van de bevroren viewer
 *  ("chips + strook op de kopregel, formulier eronder", doc.js r.2762-2768) —
 *  daar werd de bak bij het openen aan de `li` gehangen; hier staat hij er
 *  altijd, leeg, en `.c-editor-doos:empty` houdt hem buiten beeld. */
export function VoorwaardeStrook(props: { kern: Kern; ctx: VoorwaardeHaakCtx }): JSX.Element {
  const c = () => props.ctx.c as VoorwaardeVorm | null;
  const regelTerm = createMemo(() => termVan(props.ctx.regel));
  // DE DOELBINDING HEEFT WÉL EEN KNOOP (eigenaarsbesluit 8 sep 2026: het aparte
  // "Doel"-veld vervalt). Zij was hier "afgeleid" omdat het model haar term
  // alleen meegeeft als de refinement een IRI draagt — en in ODRL-AP-NL is zij
  // vrijwel altijd blank. `doelbindingTerm` zoekt hem op vanaf de regel, langs
  // dezelfde weg die `setPurpose` loopt. Daarmee is de doelbinding een gewone
  // voorwaarde-rij: één editor op één knoop, geen twee die elkaar tegenspreken.
  const term = createMemo(() => (c()?.doelbinding
    ? doelbindingTerm(props.kern.graaf(), regelTerm())
    : termVan(props.ctx.c)));
  const anker = createMemo(() => voorwaardeAnker(props.kern.graaf(), term(), regelTerm()));
  const losQuads = createMemo(() => losmaakQuads(
    props.kern.graaf(), anker(), term(),
    (s, t) => props.kern.edit.closureQuads(s, t),
  ));
  const magLos = () => losQuads().length > 0 && props.kern.quadsInBewerkbron(losQuads());
  /** BLIJFT DEZE VOORWAARDE ELDERS BESTAAN als het ✕ haar hier weghaalt? Zelfde
   *  toets en dezelfde functie als op de regelrij — één bron van waarheid, zodat
   *  de twee rijen niet van elkaar kunnen gaan verschillen. */
  const voorwaardeInGebruik = () => blijftInGebruik(props.kern.graaf(), anker(), term());
  const reden = () => tekst('edit.rijAfgeleid');
  // DE KORTE PREDICAATNAAM is het contract van `geldigeDropDoelen`
  // ('constraint' | 'refinement'), en `ouder` is bewust de REGEL en niet de
  // actie-knoop: `verplaatsConstraint` zoekt die blank node zelf op.
  const sleepItem = createMemo<SleepItem | null>(() => {
    const t0 = term(); const a = anker(); const r = regelTerm();
    if (!t0) return null;
    return {
      soort: SLEEPITEM.VOORWAARDE,
      term: t0,
      ouder: r,
      pred: a && a.pred.endsWith('refinement') ? 'refinement' : 'constraint',
      label: (props.ctx.c as { label?: string | null } | null)?.label || undefined,
    };
  });
  // WELKE RIJ IS DIT, en verdient zij een slot-formulier? Vier takken, precies
  // die van `constraintItem` — zie `rijSoort` in slots.ts.
  const soort = createMemo(() => rijSoort(c()));
  // DE REDEN OP EEN GEDIMD ✎, per soort — precies de drie zinnen die de bevroren
  // viewer eraan hangt (`voorwaardeStrook`, doc.js r.2775-2778):
  //  - `slots`: de rij HEEFT slots, maar zij staan in een bron die alleen gelezen
  //    wordt en er is niets aan te bieden (`edit.slotsNvt`);
  //  - `anker`/`groep`/`terugval`: de rij krijgt structureel geen formulier, ook
  //    niet ná het ontgrendelen.
  const nvtReden = () => {
    if (soort() === 'slots') return tekst('edit.slotsNvt');
    if (soort() === 'anker') return tekst('edit.ankerRijNvt');
    return tekst('edit.groepRijNvt');
  };
  const magSlots = () => soort() === 'slots'
    && slotsBewerkbaar(props.kern.graaf(), term(), props.kern);
  const [editorOpen, zetEditorOpen] = createSignal(false);
  const [focusVeld, zetFocusVeld] = createSignal<'links' | 'waarde' | null>(null);
  // HET FOCUSVERZOEK NA EEN TOEVOEGING (opruimpunt 13, en het besluit van 8 sep
  // 2026: "je springt direct naar het nieuwe item in edit mode"). De ghost die
  // de voorwaarde maakte zette het ADRES van de verse knoop; deze rij herkent
  // zich daarin, opent haar formulier en wist het verzoek. Zelfde mechaniek als
  // `neemFocusAan` in `ui/bewerk/kaartveld.tsx` — een adres en geen verwijzing,
  // want op het moment van het verzoek bestaat deze component nog niet.
  // WIE WIST HET VERZOEK, EN WANNEER (bijgesteld 9 sep 2026, gemeten op de
  // collectie-afbakening). Hier stond `wisBewerkFocus()` meteen bij de aanname.
  // Dat werkt zolang de rij ná de mutatie precies één keer wordt opgebouwd — op
  // een REGEL is dat zo. Onder een COLLECTIE niet: die rij hangt in de leesnode
  // van een partijveld, en die wordt na een mutatie meermaals hertekend (gemeten:
  // vier instanties). Het verzoek werd dan aangenomen door een instantie die
  // daarna werd weggegooid, en de instantie die bleef staan vond een leeg
  // verzoek — het formulier ging niet open.
  //
  // Nu wist het OPENEN het verzoek: `SlotEditor` meldt vanuit zijn `onMount` dat
  // hij er echt staat. Elke instantie op dat adres opent zichzelf; degene die het
  // overleeft ruimt op.
  //
  // EN DAT IS SINDS OPRUIMPUNT 22 LETTERLIJK DEZELFDE POLICY als bij een
  // kaartveld, niet alleen dezelfde gedachte: hier stond een eigen `nam()`-
  // signaal dat het aangenomen adres onthield om er bij het openen op te kunnen
  // toetsen. Dat is precies wat `wisFocusVoor` doet, en één regel in
  // `ui/gedeeld/bewerkhaak.tsx` kan niet uit de pas lopen met zichzelf.
  createEffect(on(bewerkFocus, (adres) => {
    if (!adres || !term() || focusAdres(term()) !== adres) return;
    if (!magSlots()) return;
    // GEEN GROOTHEID = daar begint het invullen; staat zij er al (de
    // groeperingsvoorwaarde-shortcut), dan is de WAARDE het openstaande veld.
    zetFocusVeld(slotWaarden(props.kern.graaf(), term(), curie as never).left
      ? 'waarde' : 'links');
    zetEditorOpen(true);
  }));
  const bewerkStandVanRij = (): IcoonStand => bewerkStand(props.kern, {
    mag: magSlots(),
    titel: tekst('edit.voorwaardeBewerken'),
    actie: () => {
      // Tweede klik sluit hem weer; het formulier wordt bij elke opening vers
      // gebouwd, zodat het de actuele slotwaarden uit de graaf toont.
      zetFocusVeld(null);
      zetEditorOpen((v) => !v);
    },
    // GEEN ONTGRENDEL-ROUTE OP EEN RIJ ZONDER SLOTS. Een ankerrij, een
    // en/of-groep en een niet-uitgepakte voorwaarde blijven ook ná het
    // ontgrendelen structureel onbewerkbaar: er is geen slot-formulier voor te
    // bouwen. Een slotje beloven dat niets oplevert is erger dan een gedimd
    // icoon met de reden erin. Zelfde rem als in de bevroren viewer
    // (`term: nvt ? null : term`).
    term: soort() === 'slots' ? term() : null,
    nvt: nvtReden(),
    ontgrendelbaar: true,
  });
  return (
    <Show
      when={term()}
      fallback={<AfgeleideStrook reden={reden()} />}
    >
      {(t0) => (
        <>
        <ActieStrook
          label={tekst('edit.strookLabel')}
          // HET GEDEELD-MERK OOK OP EEN VOORWAARDERIJ (deze lane). Het stond
          // alleen op de REGELrij, en dat was de helft van een belofte: sinds
          // deze ronde is een voorwaarde net zo goed te delen als een regel, en
          // dan hoort de rij te zeggen "in 2 kaarten". `kaartenVanKnoop` daalt
          // al door de voorwaarden af (`inRegel` → `voorwaardenVan`), dus er is
          // niets bij te rekenen — alleen te tonen. Het merk toont zichzelf pas
          // vanaf twee kaarten, dus op een niet-gedeelde rij verandert er niets.
          voor={<GedeeldMarker term={t0()} kaart={props.ctx.scope ?? null} />}
          sleep={sleepItem() && anker()
            ? sleepGreep(sleepItem()!)
            : geenGreep(tekst('edit.sleepGeenKoppeling'))}
          bewerk={bewerkStandVanRij()}
          verwijder={bewerkStand(props.kern, {
            mag: magLos(),
            // LOSMAKEN OF VERWIJDEREN — het onderscheid dat de REGELrij al maakt
            // (`inGebruik` in `RegelStrook` hierboven), nu ook hier. BEVINDING
            // VAN DEZE LANE, en een halve: `removeAttached` maakte het verschil
            // allang (blijft de knoop elders in gebruik, dan wist zij alléén de
            // koppel-triple), maar de rij ZEI het niet — tooltip en toast heetten
            // onvoorwaardelijk "verwijderen". Zolang een voorwaarde in de praktijk
            // nooit gedeeld was viel dat niet op; sinds deze ronde is delen een
            // knop, en dan is "Voorwaarde verwijderen" op een gedeelde rij een
            // belofte die het gedrag niet doet. Geen gedragswijziging dus, een
            // woordwijziging — met dezelfde twee sleutels als bij een regel,
            // zodat de twee rijen niet elk hun eigen zin krijgen.
            titel: tekst(voorwaardeInGebruik() ? 'edit.knoopLosmaken'
              : 'edit.voorwaardeVerwijderen'),
            actie: () => {
              const a = anker();
              if (!a) return;
              const los = voorwaardeInGebruik();
              void props.kern.voerUit(
                (f) => props.kern.edit.removeAttached(f, a.parent, a.pred, t0()),
                { groep: true },
              )
                .then((ok) => {
                  if (ok) toonToast(los ? 'edit.knoopLosgemaakt' : 'edit.voorwaardeVerwijderd');
                })
                .catch(() => {});
            },
            term: t0(),
            blokkade: losQuads(),
            nvt: tekst('edit.wegGeenKoppeling'),
            ontgrendelbaar: true,
          })}
        />
        {/* DE BAK VAN HET FORMULIER: volle breedte, onder de chips. Zie de kop
            van deze functie voor waarom hij een BROER van de strook is. */}
        <span class="c-editor-doos">
          <Show when={editorOpen()}>
            <SlotEditor
              kern={props.kern}
              term={t0()}
              c={c()}
              focus={focusVeld()}
              opGeopend={() => wisFocusVoor(focusAdres(t0()))}
              opSluiten={() => { zetEditorOpen(false); zetFocusVeld(null); }}
            />
          </Show>
        </span>
        </>
      )}
    </Show>
  );
}

// --- Een BESTAANDE benoemde VOORWAARDE hergebruiken --------------------------

/** DE KANDIDATEN, gecachet op (graaf, graafversie) — dezelfde afweging en
 *  dezelfde vorm als `regelCache` in `kaart-bewerk.tsx`: `voorwaardeOpties`
 *  scant de hele graaf, en een kaart met elf regels zou hem anders elf keer per
 *  render aanroepen. Alleen de RUWE lijst wordt bewaard; het bijschrift maakt
 *  `alsIriOpties` per aanroep, zodat een taalwissel hem meeneemt. */
let voorwaardeCache: { g: unknown; v: number; lijst: {
  iri: string; curie: string | null; label: string; herkomst: string[];
}[] } | null = null;

/** DE BESCHIKBARE KANDIDATEN VOOR DÉZE PLEK: de benoemde voorwaarden uit alle
 *  bronnen, min wat hier al hangt. Dat filter loopt over `koppelVoorwaardeToets`
 *  en niet over een eigen toets ernaast — één bron van waarheid, zodat de lijst
 *  niets kan aanbieden dat de koppeling meteen weigert. */
function voorwaardeKandidaten(kern: Kern, houder: unknown, pred: string): IriOptie[] {
  const g = kern.graaf();
  const v = graafVersie();
  if (!g || !houder) return [];
  if (!voorwaardeCache || voorwaardeCache.g !== g || voorwaardeCache.v !== v) {
    voorwaardeCache = { g, v, lijst: kern.edit.voorwaardeOpties(g) };
  }
  return alsIriOpties(voorwaardeCache.lijst
    .filter((c) => kern.edit.koppelVoorwaardeToets(g, houder, pred, c.iri).ok));
}

/** DE KEUZERIJ VAN DE VOORWAARDEKANT. De VORM komt uit `hergebruik.tsx` (zie
 *  daar waarom); wat hier staat is wat een keuze BETEKENT: één triple via
 *  `koppelVoorwaarde`, in één `voerUit(..., { groep: true })` en dus één ↶.
 *
 *  EERST HET OORDEEL, OP DE LEESGRAAF — zelfde reden als bij `hernoemToets` in
 *  `kaartveld.tsx`: een afgewezen keuze mag geen lege mutatiegroep en dus geen
 *  dode ↶ opleveren. */
function VoorwaardeHergebruikRij(props: {
  kern: Kern; houder: unknown; pred: string; opties: IriOptie[]; opSluiten: () => void;
}): JSX.Element {
  const kies = (iri: string): void => {
    const oordeel = props.kern.edit.koppelVoorwaardeToets(
      props.kern.graaf(), props.houder, props.pred, iri,
    );
    if (!oordeel.ok) {
      zetMelding(VOORWAARDE_MELDING[oordeel.reden || ''] || 'edit.ongeldigeIri', { invoer: iri });
      return;
    }
    let nieuw: unknown = null;
    void props.kern.voerUit((f) => {
      nieuw = props.kern.edit.koppelVoorwaarde(f, props.houder, props.pred, iri).term;
    }, { groep: true })
      .then((ok) => {
        if (!ok) return;
        toonToast('edit.voorwaardeGekoppeld');
        props.opSluiten();
        // DE CURSOR NAAR DE GEKOPPELDE RIJ, net als bij een verse voorwaarde.
        // `VoorwaardeStrook` herkent het adres en opent haar sloteditor — op een
        // GEDEELDE voorwaarde is dat precies wat je wilt zien: waar hij nu ook
        // hangt, dit is wat erin staat.
        vraagFocusOp(nieuw);
      })
      .catch(() => {});
  };
  return (
    <HergebruikRij
      opties={props.opties}
      kiesSleutel="edit.hergebruikVoorwaardeKies"
      kies={kies}
      opSluiten={props.opSluiten}
      cls="hergebruik-voorwaarde-rij"
    />
  );
}

/** DE GHOST-VOORWAARDERIJ onderaan de voorwaardenlijst van een regel. Het
 *  silhouet is de rij die hij aanmaakt: dezelfde drie `.c-slot`-chips,
 *  gestippeld en met de slotnamen als schim.
 *
 *  DE NIEUWE VOORWAARDE IS LEEG (eigenaarsbesluit 8 sep 2026). De bevroren
 *  viewer vulde haar met odrl:dateTime/lteq/vandaag "zodat het formulier iets
 *  heeft om te tonen"; dat leverde een tijdgrens op die niemand vroeg. Wat de
 *  plaats van die prefill inneemt is de TOEVOEGFOCUS: de ghost vraagt de cursor
 *  op de verse knoop, `VoorwaardeStrook` herkent het adres en opent haar
 *  sloteditor met de cursor in de grootheid. De rij is dus geen raadsel maar een
 *  formulier — en er staat niets in de data wat de gebruiker niet zelf zei. */
export function VoorwaardeGhost(props: { kern: Kern; ctx: RegelHaakCtx }): JSX.Element {
  const term = createMemo(() => (props.ctx.afgeleid ? null : termVan(props.ctx.regel)));
  // STAAT DE KEUZELIJST OPEN? Lokaal aan déze ghost: elke regel heeft er één, en
  // een open lijst bij de ene regel mag de andere niet raken.
  const [hergebruikOpen, zetHergebruikOpen] = createSignal(false);
  const kandidaten = createMemo(
    () => voorwaardeKandidaten(props.kern, term(), `${ODRL}constraint`),
  );
  const optie = (): GhostOptie => {
    const t0 = term();
    const stand = bewerkStand(props.kern, {
      mag: props.kern.bewerkbaar(t0),
      titel: tekst('edit.voorwaardeToevoegen'),
      actie: () => {
        let nieuw: unknown = null;
        void props.kern.voerUit((f) => { nieuw = props.kern.edit.addConstraint(f, t0); },
          { groep: true })
          .then((ok) => { if (ok) vraagFocusOp(nieuw); })
          .catch(() => {});
      },
      term: t0,
      ontgrendelbaar: true,
    });
    return {
      node: <GhostChips />,
      cls: 'voorwaarde-plus-knop',
      titel: stand.titel,
      aan: stand.aan,
      actie: stand.actie,
    };
  };
  // --- DE SNELKOPPELING NAAR DE GROEPERINGSVOORWAARDE ------------------------
  //
  // Eigenaarscorrectie 8 sep 2026: "als je op topniveau een rule aanmaakt
  // *zonder voorwaardes dus* dan kan je *in de net aangemaakte rule* een
  // shortcut opnemen om de groeperingsvoorwaarde aan te maken zodat het daarna
  // wel onder het doel komt te staan."
  //
  // Hij staat dus ÍN de regel en niet naast de ghost die haar maakte — en niet
  // alleen in een "verse" regel: de toets is of deze regel de dimensie MIST
  // waarop de weergave op dit moment groepeert. Dat is dezelfde stand, zonder
  // dat er ergens een "net aangemaakt"-vlag bewaard hoeft te worden, en het
  // helpt ook de regel die al bestond en buiten de vakjes valt.
  //
  // DE BUITENSTE ontbrekende dimensie, één segment. `actieveDimensies()` staat
  // in nestvolgorde; de buitenste bepaalt in welk vakje de regel valt, en drie
  // segmenten naast elkaar zouden van de ghost een menu maken.
  //
  // GEEN WAARDE, alleen de GROOTHEID. Welke waarde erin hoort weet niemand hier
  // (dat is nou juist wat de lezer gaat kiezen), en een gefingeerde waarde is
  // precies wat besluit 1b wegneemt. De voorwaarde ontstaat leeg, de sloteditor
  // opent er meteen op met de cursor in de WAARDE (de grootheid staat er al) en
  // zodra hij ingevuld is, valt de regel in het vakje.
  const dim = createMemo(() => {
    const t0 = term();
    if (!t0) return null;
    const r = props.ctx.regel as {
      purpose?: unknown; refinements?: { leftIri?: string | null }[];
    } | null;
    if (!r) return null;
    for (const d of (props.ctx.dims || [])) {
      const heeft = d.iri === PURPOSE_LEFT
        ? !!r.purpose
        : (r.refinements || []).some((c) => c.leftIri === d.iri);
      if (!heeft) return d;
    }
    return null;
  });
  const dimOptie = (): GhostOptie => {
    const t0 = term();
    const d = dim()!;
    const naam = d.label || d.curie || d.iri;
    const stand = bewerkStand(props.kern, {
      mag: props.kern.bewerkbaar(t0),
      titel: tekst('edit.groepeerVoorwaardeToevoegen', { dim: naam }),
      actie: () => {
        let nieuw: unknown = null;
        void props.kern.voerUit((f) => {
          // ALS REFINEMENT OP DE ACTIE-KNOOP, want dat is waar het model zijn
          // dimensies leest (`ruleDimensions` in parse.js: `rule.refinements`
          // komt uit `readAction`). Rechtstreeks onder de regel zou hij als
          // gewone voorwaarde renderen en nooit een vakje maken.
          nieuw = props.kern.edit.addConstraint(f, t0, `${ODRL}refinement`,
            { left: d.iri, operator: `${ODRL}eq`, opActie: true });
        }, { groep: true })
          .then((ok) => { if (ok) vraagFocusOp(nieuw); })
          .catch(() => {});
      },
      term: t0,
      ontgrendelbaar: true,
    });
    return {
      label: `+ ${naam}`,
      cls: 'voorwaarde-dim-plus',
      titel: stand.titel,
      aan: stand.aan,
      actie: stand.actie,
    };
  };
  // --- HET ↻-SEGMENT: EEN BESTAANDE BENOEMDE VOORWAARDE KOPPELEN -------------
  //
  // EIGENAARSFEEDBACK 11 SEP 2026, LETTERLIJK: "Ik zie nog niet hoe ik nodes kan
  // hergebruiken. Voorwaarden toevoegen is nog steeds alleen invoeren van de
  // left/rightOperand etc. bijv."
  //
  // Dit is letterlijk hetzelfde segment als op de sectiechip van een kaart —
  // dezelfde `hergebruikSegment`, dezelfde `HergebruikRij` eronder, dezelfde
  // Escape en dezelfde cap. Eén leerbaar gebaar op twee niveaus, en dat is de
  // reden dat de vorm in `hergebruik.tsx` woont en niet twee keer hier.
  //
  // HET PREDICAAT IS `odrl:constraint` EN NIET `odrl:refinement`: deze ghost
  // staat onder de VOORWAARDENlijst van een regel, en dat is de plek van een
  // voorwaarde aan het GEBRUIK. De refinement-route heeft haar eigen ghosts (de
  // dimensie-snelkoppeling hierboven, die een verse knoop met een bekende
  // grootheid mint, en de collectie-afbakening hieronder) — zie
  // `koppelVoorwaardeToets`: de PLEK bepaalt het predicaat.
  const hergebruikOptie = (): GhostOptie => hergebruikSegment({
    kern: props.kern,
    term: term(),
    cls: 'voorwaarde-hergebruik',
    aantal: kandidaten().length,
    uitleg: 'edit.hergebruikVoorwaardeUitleg',
    geen: 'edit.hergebruikVoorwaardeGeen',
    schakel: () => zetHergebruikOpen((v) => !v),
  });
  const segmenten = (): GhostOptie[] => (dim()
    ? [optie(), dimOptie(), hergebruikOptie()]
    : [optie(), hergebruikOptie()]);
  return (
    <Show when={term()}>
      <li class="voorwaarde-plus">
        <GhostMetDoos cls="ghost-voorwaarde" opties={segmenten()} />
        {/* DE KEUZERIJ, onder de ghost en dus op de plek waar de gekoppelde rij
            landt — dezelfde afspraak als bij de sectiechip. */}
        <Show when={hergebruikOpen()}>
          <VoorwaardeHergebruikRij
            kern={props.kern}
            houder={term()}
            pred={`${ODRL}constraint`}
            opties={kandidaten()}
            opSluiten={() => zetHergebruikOpen(false)}
          />
        </Show>
      </li>
    </Show>
  );
}

/** DE GHOST ONDERAAN DE AFBAKENING VAN EEN COLLECTIE.
 *
 *  EIGENAARSBEVINDING 9 SEP 2026: "Als hij er wel een heeft is een
 *  PartyCollection met refinements ook niet aan te maken." De collectiekaart
 *  toont haar afbakening al en elke rij daarin is sinds de vorige ronde
 *  bewerkbaar (dezelfde `voorwaardeStrook` als een gewone voorwaarde) — maar de
 *  EERSTE rij kon er niet ontstaan. Dit is die plek.
 *
 *  GEEN NIEUW MUTATIEPAD, en geen tweede silhouet: het is dezelfde
 *  `addConstraint` en dezelfde `GhostChips` als de voorwaarde-ghost van een
 *  regel. Twee dingen verschillen, allebei omdat een collectie geen regel is:
 *
 *   1. HET PREDICAAT is `odrl:refinement` en niet `odrl:constraint`. Een
 *      refinement bakent de VERZAMELING af (wie hoort erbij); een constraint
 *      stelt een voorwaarde aan het GEBRUIK. `collectionIntension` (parse.js)
 *      leest alleen het eerste, dus een constraint zou hier onzichtbaar landen.
 *   2. `opActie` blijft UIT. De refinements van een regel hangen aan haar
 *      (blanke) actie-knoop, want daar leest `readAction` ze; een collectie
 *      heeft geen actie en draagt ze rechtstreeks.
 *
 *  De TOEVOEGFOCUS loopt precies als daar: het adres van de verse knoop gaat het
 *  signaal in, `VoorwaardeStrook` herkent zich erin en opent haar sloteditor met
 *  de cursor in de grootheid. Zij vindt haar anker via de "maar één
 *  kandidaat"-tak van `voorwaardeAnker` — de koppeling naar de collectie is de
 *  enige die er is. */
export function CollectieAfbakeningGhost(props: {
  kern: Kern; ctx: CollectieHaakCtx;
}): JSX.Element {
  const term = createMemo(() => termVan(props.ctx.term));
  const [hergebruikOpen, zetHergebruikOpen] = createSignal(false);
  // HIER IS HET PREDICAAT `odrl:refinement` — zie de kop van deze functie punt
  // 1. Dat is de hele reden dat `koppelVoorwaarde` het predicaat van de
  // AANROEPER krijgt en niet uit de knoop afleidt: dezelfde benoemde voorwaarde
  // bakent hier een verzameling af en stelt daar een voorwaarde aan het gebruik.
  const kandidaten = createMemo(
    () => voorwaardeKandidaten(props.kern, term(), `${ODRL}refinement`),
  );
  const optie = (): GhostOptie => {
    const t0 = term();
    const stand = bewerkStand(props.kern, {
      mag: props.kern.bewerkbaar(t0),
      titel: tekst('edit.afbakeningToevoegen'),
      actie: () => {
        let nieuw: unknown = null;
        void props.kern.voerUit(
          (f) => { nieuw = props.kern.edit.addConstraint(f, t0, `${ODRL}refinement`); },
          { groep: true },
        )
          .then((ok) => { if (ok) vraagFocusOp(nieuw); })
          .catch(() => {});
      },
      term: t0,
      ontgrendelbaar: true,
    });
    return {
      node: <GhostChips />,
      cls: 'voorwaarde-plus-knop',
      titel: stand.titel,
      aan: stand.aan,
      actie: stand.actie,
    };
  };
  const hergebruikOptie = (): GhostOptie => hergebruikSegment({
    kern: props.kern,
    term: term(),
    cls: 'voorwaarde-hergebruik',
    aantal: kandidaten().length,
    uitleg: 'edit.hergebruikVoorwaardeUitleg',
    geen: 'edit.hergebruikVoorwaardeGeen',
    schakel: () => zetHergebruikOpen((v) => !v),
  });
  return (
    <Show when={term()}>
      <li class="voorwaarde-plus">
        <GhostMetDoos cls="ghost-voorwaarde" opties={[optie(), hergebruikOptie()]} />
        <Show when={hergebruikOpen()}>
          <VoorwaardeHergebruikRij
            kern={props.kern}
            houder={term()}
            pred={`${ODRL}refinement`}
            opties={kandidaten()}
            opSluiten={() => zetHergebruikOpen(false)}
          />
        </Show>
      </li>
    </Show>
  );
}
