// HET ↻-HERGEBRUIK-IDIOOM, op één plek.
//
// EIGENAARSFEEDBACK 11 SEP 2026, LETTERLIJK: "Ik zie nog niet hoe ik nodes kan
// hergebruiken. Voorwaarden toevoegen is nog steeds alleen invoeren van de
// left/rightOperand etc. bijv."
//
// Twee dingen zaten achter die zin, en deze module is het antwoord op allebei:
//
//  1. VOOR VOORWAARDEN BESTOND DE ROUTE NIET. De ghost onder een regel had één
//     segment ("+ voorwaarde", drie lege slots), en meer niet — gemeten op het
//     jenv-corpus vóór deze ronde: elk van de elf voorwaarde-ghosts droeg
//     precies één segment, allemaal "Een voorwaarde aan deze regel toevoegen".
//     Wie een bestaande doelbinding wilde hergebruiken had geen andere uitweg
//     dan haar drie slots overtypen — en dan is het een KOPIE, geen deling.
//  2. VOOR REGELS BESTOND ZIJ WÉL, EN WAS ZIJ NIET TE VINDEN. Zelfde meting:
//     het "↻ hergebruik"-segment stond als 114×30 px grijze stippelchip ONDER
//     een 888×39 px mint-chip in de kleur van zijn regelsoort. Zelfde
//     rustdempte (0.55), een zevende van de breedte, en zonder kleurmerk dat
//     hem aan de sectie erboven bindt. Dat is de "verdwaald naast de
//     sectie-chip"-hypothese van de brief, met getallen erbij.
//
// WAT HIER WOONT is de VORM van het gebaar — het segment en de keuzerij — en
// niet de betekenis. Wélke kandidaten er zijn en wat een keuze schrijft,
// beslist de aanroeper: `kaart-bewerk.tsx` koppelt regels via `koppelRegel`,
// `rij-bewerk.tsx` voorwaarden via `koppelVoorwaarde`. Zo is het voor de lezer
// ÉÉN leerbaar gebaar (dezelfde chip, dezelfde plek, dezelfde keuzerij,
// dezelfde Escape) zonder dat de twee mutatieroutes iets van elkaar weten.
//
// GEEN TWEEDE DIALOOGSTELSEL (brief): de keuzerij is de gewone `IriCombobox`
// die de velden ook gebruiken, met dezelfde Escape, dezelfde filter en dezelfde
// cap. Wat er anders aan is staat in de OPTIES: het bijschrift draagt naast de
// curie de HERKOMST ("uit Overeenkomst Vlierdam"), want twee voorwaarden heten
// in dit domein makkelijk allebei "Doelbinding: nazorg".
import type { JSX } from 'solid-js';
import { tekst } from '../../../stores/weergave.js';
import { IriCombobox } from '../veld.jsx';
import type { IriOptie } from '../veld.jsx';
import { Knop } from '../knop.jsx';
import type { GhostOptie } from '../ghost.jsx';
import { bewerkStand } from './stand.jsx';
import type { Kern } from './kern.js';
import type { Term } from '../../../model-grens.js';

/** Het woord op de chip, met zijn teken ervoor. ÉÉN plek, zodat de regel- en de
 *  voorwaardekant niet uit elkaar kunnen lopen — dat is wat "één leerbaar
 *  gebaar" in de praktijk betekent. */
export const HERGEBRUIK_LABEL = (): string => `↻ ${tekst('edit.hergebruik')}`;

/** DE MELDINGEN BIJ EEN WEIGERING. De vier redenen heten in beide
 *  toets-families hetzelfde (`ongeldig` / `onbekend` / `verkeerdeSoort` /
 *  `alGekoppeld`), maar de ZINNEN verschillen: "die regel staat niet in de
 *  geladen bronnen" onder een voorwaardelijst is een melding over het verkeerde
 *  ding. De aanroeper geeft dus zijn eigen tabel mee; deze twee staan hier
 *  omdat ze bij het idioom horen en nergens anders gebruikt worden. */
export const REGEL_MELDING: Record<string, string> = {
  onbekend: 'edit.hergebruikOnbekend',
  verkeerdeSoort: 'edit.hergebruikSoort',
  alGekoppeld: 'edit.hergebruikAl',
};

export const VOORWAARDE_MELDING: Record<string, string> = {
  onbekend: 'edit.hergebruikVoorwaardeOnbekend',
  verkeerdeSoort: 'edit.hergebruikVoorwaardeSoort',
  alGekoppeld: 'edit.hergebruikVoorwaardeAl',
};

/** HET ↻-SEGMENT van een ghost-rij. Geen silhouet, en dat is de reden dat deze
 *  optie een `label` draagt waar zijn buurman een `node` heeft: er ontstaat geen
 *  nieuw element, er wordt er één BIJGEHAALD — een gestippelde schim van een
 *  toestemming zou dat tegenspreken.
 *
 *  Staat er niets klaar, dan gaat het segment UIT MET ZIJN REDEN in plaats van
 *  weg te vallen (de afspraak van `ghost.tsx`: "een optie verdwijnt niet als er
 *  niets te schakelen valt"). Die reden wijst naar de andere helft van de
 *  hergebruik-ronde: een blanke knoop is niet aan te wijzen, geef hem eerst een
 *  naam. */
export function hergebruikSegment(opties: {
  kern: Kern;
  /** De knoop waar de koppeling aan komt te hangen — de kaart bij een
   *  sectiechip, de regel of de collectie bij een voorwaarde. Hij bepaalt de
   *  bewerkbaarheid en dus of het segment aan, gelockt of uit staat. */
  term: Term | null;
  cls: string;
  /** Hoeveel kandidaten staan er klaar? Nul = uit, met `geen` als reden. */
  aantal: number;
  /** i18n-sleutel van de tooltip als er wél iets te kiezen valt. */
  uitleg: string;
  /** i18n-sleutel van de reden als de lijst leeg is. */
  geen: string;
  schakel: () => void;
}): GhostOptie {
  const label = HERGEBRUIK_LABEL();
  // ÉÉN GEDEELDE KLASSE NAAST DE PLEK-KLASSE (deel 2 van deze lane). De
  // plek-klasse (`kaart-toestemming-hergebruik`, `voorwaarde-hergebruik`) zegt
  // WAAR de chip staat en is het adres van elke bestaande test; `ghost-hergebruik`
  // zegt WAT hij is, en draagt de vorm. Zonder die tweede klasse zou de vormtaal
  // per plek opnieuw opgeschreven moeten worden — en precies dáár liep hij uit
  // de pas: op de sectiechip was hij een zevende zo breed als zijn buurman en
  // droeg hij diens rijkleur niet.
  // DE PLEK-KLASSE EERST, en dat is geen smaak: `integratie.test.tsx` leest de
  // segmentvolgorde af aan de EERSTE klasse die op `-plus` of `-hergebruik`
  // eindigt, en `ghost-hergebruik` doet dat ook. Vooraan zou hij dus elk
  // segment "ghost-hergebruik" laten heten en het adres van de chip wegdrukken.
  const cls = `${opties.cls} ghost-hergebruik`;
  if (!opties.aantal) {
    return { label, cls, titel: tekst(opties.geen), aan: false };
  }
  const stand = bewerkStand(opties.kern, {
    mag: opties.kern.bewerkbaar(opties.term),
    titel: tekst(opties.uitleg),
    actie: opties.schakel,
    term: opties.term,
    ontgrendelbaar: true,
  });
  return { label, cls, titel: stand.titel, aan: stand.aan, actie: stand.actie };
}

/** DE KEUZERIJ die onder de ghost openklapt. Hij staat WAAR HET GEKOPPELDE
 *  ELEMENT KOMT, precies zoals de ghost erboven (regel 1 van `ghost.tsx`), en
 *  hij klapt niets om: de combobox stopt zijn eigen Enter en Escape, en de
 *  omhullende lijst is geen `<summary>`.
 *
 *  Wat de rij NIET doet is koppelen. Zij levert de gekozen IRI af bij `kies` en
 *  is verder een presentatiedingetje — de mutatie, de toets, de toast en het
 *  focusverzoek horen bij de aanroeper, want die weet wélke koppeling dit is. */
export function HergebruikRij(props: {
  opties: IriOptie[];
  /** i18n-sleutel van het aria-label én de placeholder van de combobox. */
  kiesSleutel: string;
  kies: (iri: string) => void;
  opSluiten: () => void;
  /** Extra klasse op de rij, voor de plek waar hij landt (regel of voorwaarde). */
  cls?: string;
}): JSX.Element {
  return (
    <div class={['hergebruik-rij', props.cls || ''].filter(Boolean).join(' ')}>
      <IriCombobox
        options={props.opties}
        ariaLabel={tekst(props.kiesSleutel)}
        placeholder={tekst(props.kiesSleutel)}
        onPick={(iri: string) => { if (iri) props.kies(iri); }}
      />
      <Knop
        label={tekst('edit.annuleren')}
        cls="hergebruik-annuleer"
        onClick={props.opSluiten}
      />
    </div>
  );
}

/** De opties van de modellaag omgezet naar `IriOptie`s, met de herkomst als
 *  bijschrift. Beide kanten leveren dezelfde vier velden, dus deze omzetting
 *  hoort één keer te bestaan. Het bijschrift wordt PER AANROEP samengesteld en
 *  niet meegecachet, zodat een taalwissel hem meeneemt. */
export function alsIriOpties(lijst: {
  iri: string; curie: string | null; label: string; herkomst: string[];
}[]): IriOptie[] {
  return lijst.map((r) => ({
    iri: r.iri,
    label: r.label,
    curie: r.curie || undefined,
    extra: r.herkomst.length
      ? tekst('edit.hergebruikHerkomst', { beleid: r.herkomst.join(', ') }) : undefined,
  }));
}
