// DE DRIE SLOTS VAN EEN VOORWAARDE, ZOALS ZE IN DE GRAAF STAAN.
//
// Gedragsbron: `slotObjecten`, `samengesteldeWaarde`, `slotWaarden` en
// `slotsBewerkbaar` uit het fase C-taak 6-blok van viewer-bevroren/assets/doc.js
// (r.2349-2470). PUUR: deze module leest een store en rekent; zij muteert
// niets en kent geen bewerkstand. Dat is wat haar toetsbaar maakt zonder
// corpus en zonder bewerkbron — dezelfde afspraak als `anker.ts`.
//
// DE SLOTWAARDEN KOMEN UIT DE STORE, NIET UIT DE CHIPS. Het chip-model draagt
// alleen TEKST ("Datum en tijd", "is niet later dan", "2026-12-31") — labels
// dus, en die zijn niet terug te rekenen naar de IRI's die er moeten staan.
// Vandaar dat elke waarde hieronder rechtstreeks uit de graaf komt.
import { PREFIXES } from '../../../model/parse.js';
import type { Quad, Term } from '../../../model-grens.js';
import { ODRL, termVan } from './anker.js';
import type { Leesstore } from './anker.js';

const RDF = PREFIXES.rdf as string;
const XSD = PREFIXES.xsd as string;

export const ODRL_LEFT = `${ODRL}leftOperand`;
export const ODRL_OP = `${ODRL}operator`;
export const ODRL_RIGHT = `${ODRL}rightOperand`;
export const ODRL_RIGHT_REF = `${ODRL}rightOperandReference`;
export const ODRL_PURPOSE = `${ODRL}purpose`;

/** De drie predicaten die het formulier schrijft. */
export const SLOT_PREDS = [ODRL_LEFT, ODRL_OP, ODRL_RIGHT];

/** De datatypen die in dit domein voorkomen — letterlijk de lijst van de
 *  bevroren viewer. Geen open keuzelijst: een xsd-type dat de data zelf
 *  meebrengt wordt hieronder alsnog als optie toegevoegd, zodat opslaan hem
 *  niet stilzwijgend afkapt. */
export const SLOT_DATATYPES = [`${XSD}date`, `${XSD}dateTime`, `${XSD}integer`,
  `${XSD}boolean`, `${XSD}duration`];

export interface SlotRechts {
  kind: 'literal' | 'iri';
  value: string;
  lang: string;
  datatype: string;
}

export interface SlotWaarden {
  left: string;
  operator: string;
  right: SlotRechts;
}

function slotObjecten(store: Leesstore | null, term: Term | null, pred: string): Term[] {
  if (!store || !term) return [];
  return store.getQuads(term, termVan(pred), null, null).map((q) => q.object);
}

/** IS DE RECHTERWAARDE SAMENGESTELD? Een rdf:List (BRP: veertien gemeentecodes
 *  achter odrl:isAnyOf), meerdere rightOperands, een odrl:rightOperandReference,
 *  of — algemener — ELKE blanke knoop als rechterwaarde.
 *
 *  `setConstraint` vervangt de rechterwaarde door ÉÉN waarde: op een lijst zou
 *  dat de andere dertien wissen en de lijstknopen als wezen achterlaten. Zo'n
 *  waarde blijft daarom staan zoals zij is — het waardeveld toont haar gedempt,
 *  en de save laat `right` weg (`setConstraint` raakt hem dan niet aan).
 *  Grootheid en operator blijven gewoon te wijzigen.
 *
 *  ELKE BLANKE KNOOP, niet alleen een rdf:List (review taak 6): een rightOperand
 *  mag ook een gewone anonieme structuur zijn (een geo-gebied, een samengestelde
 *  waarde uit een profiel). Zo'n knoop heeft geen tekstvorm — het veld zou zijn
 *  INTERNE id tonen en Opslaan zou dat als letterlijke tekst wegschrijven. */
export function samengesteldeWaarde(store: Leesstore | null, term: Term | null): boolean {
  const objs = slotObjecten(store, term, ODRL_RIGHT);
  if (objs.length > 1) return true;
  if (slotObjecten(store, term, ODRL_RIGHT_REF).length) return true;
  const o = objs[0];
  if (o && o.termType === 'BlankNode') return true;
  // Een BENOEMDE lijstkop is zeldzaam maar geldig RDF; ook die blijft staan.
  return !!(o && o.termType !== 'Literal' && store
    && store.getQuads(o, termVan(`${RDF}first`), null, null).length);
}

/** De drie slots zoals ze NU in de graaf staan. `curie` maakt van een
 *  IRI-rechterwaarde de korte vorm die het veld toont (en die `expandIri`
 *  terugleest); een literal komt als haar kale tekst. */
export function slotWaarden(
  store: Leesstore | null, term: Term | null, curie: (iri: string) => string | null,
): SlotWaarden {
  const iriVan = (pred: string): string => {
    const o = slotObjecten(store, term, pred)[0];
    return o && o.termType === 'NamedNode' ? (o.value || '') : '';
  };
  const r = slotObjecten(store, term, ODRL_RIGHT)[0] || null;
  const isLit = !!r && r.termType === 'Literal';
  const dt = (r as { datatype?: { value?: string } } | null)?.datatype?.value || '';
  return {
    left: iriVan(ODRL_LEFT),
    operator: iriVan(ODRL_OP),
    right: {
      kind: r && r.termType === 'NamedNode' ? 'iri' : 'literal',
      value: (r && r.termType === 'NamedNode')
        ? (curie(r.value || '') || r.value || '') : ((r && r.value) || ''),
      lang: isLit ? ((r as { language?: string }).language || '') : '',
      datatype: isLit && dt && !/#string$/.test(dt) ? dt : '',
    },
  };
}

/** ZIJN DE DRIE SLOTS TE BEWERKEN? Per slot dezelfde veld-fijne grens als de
 *  kernvelden (`veldStand` in `ui/bewerk/kaartveld.tsx`, `bewerkbaarVeld` in de
 *  bevroren viewer): bestaat het triple, dan moet het in de bewerkbron staan;
 *  bestaat het nog niet, dan volstaat dat de KNOOP daar leeft.
 *
 *  De twee toetsen komen als functies binnen en niet als store, zodat deze
 *  module de bewerkbron niet hoeft te kennen. */
export function slotsBewerkbaar(
  store: Leesstore | null, term: Term | null,
  toetsen: { quadsInBewerkbron: (q: Quad[]) => boolean; bewerkbaar: (t: Term) => boolean },
): boolean {
  if (!store || !term) return false;
  return SLOT_PREDS.every((pred) => {
    const eigen = store.getQuads(term, termVan(pred), null, null);
    return eigen.length ? toetsen.quadsInBewerkbron(eigen) : toetsen.bewerkbaar(term);
  });
}

/** WAT VOOR RIJ IS DIT, en verdient zij een slot-formulier?
 *
 *  De vier takken van `constraintItem` (doc.js r.5843-5980), in dezelfde
 *  volgorde:
 *    - `anker`  — technische borging: haar drie slots vormen SAMEN de verwijzing
 *      naar een artefact, en de dekkingsketen hangt aan precies die vorm. Een
 *      los slot wijzigen breekt die keten stilzwijgend;
 *    - `groep`  — een en/of-groep: de leden zijn eigen knopen zonder eigen rij;
 *    - `terugval` — geen slot-structuur om een formulier op te zetten;
 *    - `slots`  — de gewone voorwaarde, mét formulier. Ook een LEGE voorwaarde
 *      valt hier: `constraintSentence` levert dan `slots` met drie nullen, en
 *      juist zo'n verse voorwaarde moet in te vullen zijn. */
export type RijSoort = 'slots' | 'anker' | 'groep' | 'terugval';

export function rijSoort(c: {
  technicalMeasure?: boolean; logical?: string | null; children?: unknown[];
  slots?: unknown;
} | null): RijSoort {
  if (!c) return 'terugval';
  if (c.technicalMeasure) return 'anker';
  if (c.slots) return 'slots';
  if (c.logical && (c.children || []).length) return 'groep';
  return 'terugval';
}

/** DE KNOOP VAN DE DOELBINDING, gezocht vanaf de REGEL.
 *
 *  De doelbindingsrij is een weergave-constructie: `voorwaardeLijst`
 *  (ui/kaart/voorwaarden.tsx) stelt haar samen uit `regel.purpose` en
 *  `regel.purposeConstraint`. Dat tweede veld draagt alleen een term als de
 *  refinement een IRI heeft (`readPermission`, parse.js r.1958) — en in
 *  ODRL-AP-NL is zij vrijwel altijd een BLANKE knoop. De rij had daarmee geen
 *  adres, en dat is precies waarom zij tot nu toe als "afgeleid" gold.
 *
 *  Zij heeft wél een knoop; hij is alleen niet van buitenaf aan te wijzen, net
 *  als bij `voorwaardeAnker`. Dus zoeken we hem hier op langs dezelfde weg die
 *  `setPurpose` (model/edit.js) loopt: regel → odrl:action → odrl:refinement met
 *  odrl:leftOperand odrl:purpose. Zo wordt de doelbinding een gewone
 *  voorwaarde-rij met een gewone sloteditor (eigenaarsbesluit 8 sep 2026: het
 *  aparte "Doel"-veld vervalt). */
export function doelbindingTerm(store: Leesstore | null, regelTerm: Term | null): Term | null {
  if (!store || !regelTerm) return null;
  for (const a of store.getQuads(regelTerm, termVan(`${ODRL}action`), null, null)) {
    for (const r of store.getQuads(a.object, termVan(`${ODRL}refinement`), null, null)) {
      const links = store.getQuads(r.object, termVan(ODRL_LEFT), null, null)[0];
      if (links && links.object.value === ODRL_PURPOSE) return r.object;
    }
  }
  return null;
}
