// DE DOELOBJECTEN VAN EEN REGEL: er een weghalen, en er een bij zetten.
//
// Gedragsbron: `targetQuads`, `targetKruis` en `targetToevoegen` in
// viewer-bevroren/assets/doc.js (fase C taak 5, r.2300-2346). Deze helft van taak 5 is in
// dt3 nooit gebouwd — `addTarget` en `removeTarget` in `model/edit.js` hadden
// nul afnemers, en `target` kwam in de hele vertaaltabel niet voor (eindreview
// C-1). Dit bestand is die helft, in dezelfde vorm.
//
// TWEE PLEKKEN, TWEE COMPONENTEN, want ze horen op verschillende plaatsen in de
// leesweergave: het ✕ ín de tag van het doelobject dat het weghaalt, de
// "+ gegevensset"-combobox erachter, waar de nieuwe tag komt te staan. Dat is
// dezelfde regel als bij de ghosts: de actie staat waar zijn resultaat landt.
import { Show, createMemo } from 'solid-js';
import type { JSX } from 'solid-js';
import { targetPredicates } from '../../../model/parse.js';
import { tekst } from '../../../stores/weergave.js';
import type { Quad, Term } from '../../../model-grens.js';
import { termVan } from './anker.js';
import type { Leesstore } from './anker.js';
import { veldOpties } from '../kaartveld.jsx';
import { IriCombobox } from '../veld.jsx';
import { Knop } from '../knop.jsx';
import { bewerkStand } from './stand.jsx';
import type { Kern } from './kern.js';
import type { TargetHaakCtx } from '../../gedeeld/bewerkhaak.jsx';
import './sloteditor.css';

/** DE TRIPLES DIE ÉÉN DOELOBJECT AAN EEN REGEL HANGEN. Dat hoeft niet
 *  `odrl:target` te zijn: de graaf mag eigen `rdfs:subPropertyOf`-predicaten
 *  declareren (BRP: `brp:verzochteRubriek`), en het ✕ moet naar de triple kijken
 *  die er ÉCHT staat. `targetPredicates` leidt die lijst uit de graaf af —
 *  dezelfde afleiding die `parse.js` gebruikt om ze te lezen, dus lezen en
 *  wissen kunnen niet uit elkaar lopen. */
export function targetQuads(
  store: Leesstore | null, regelTerm: Term | null, iri: string,
): Quad[] {
  if (!store || !regelTerm || !iri) return [];
  const uit: Quad[] = [];
  for (const pred of targetPredicates(store) as string[]) {
    uit.push(...store.getQuads(regelTerm, termVan(pred), termVan(iri), null));
  }
  return uit;
}

/** HET ✕ ACHTER EEN DOELOBJECT-TAG. Alleen bij een BENOEMD doelobject
 *  (`removeTarget` werkt op een IRI, niet op een blanke knoop) en alleen als de
 *  triples die het dragen in de bewerkbron staan — anders gaat hij op slot met
 *  de route ernaartoe, net als elk ander gelockt icoon. */
export function TargetKruis(props: { kern: Kern; ctx: TargetHaakCtx }): JSX.Element {
  const regelTerm = createMemo(() => termVan(props.ctx.regel));
  const quads = createMemo(() => targetQuads(
    props.kern.graaf(), regelTerm(), props.ctx.iri || '',
  ));
  const stand = () => bewerkStand(props.kern, {
    mag: quads().length > 0 && props.kern.quadsInBewerkbron(quads()),
    titel: tekst('edit.targetVerwijderen'),
    actie: () => {
      void props.kern.voerUit(
        (f) => props.kern.edit.removeTarget(f, regelTerm(), props.ctx.iri as string),
        { groep: true },
      );
    },
    blokkade: quads(),
    // GEEN NIEUWE SLEUTEL. `edit.wegGeenKoppeling` zegt precies dit ("er is niet
    // één plek aan te wijzen waar dit vandaan gehaald kan worden") en staat er
    // al; een tweede sleutel met dezelfde zin is hoe een stringtabel scheefloopt.
    nvt: tekst('edit.wegGeenKoppeling'),
    ontgrendelbaar: true,
  });
  return (
    <Show when={props.ctx.iri && regelTerm()}>
      <span class="target-bewerk">
        <Knop
          label="✕"
          cls={`target-x${stand().aan ? '' : (stand().actie ? ' gelockt' : ' actie-uit')}`}
          titel={stand().titel}
          ariaLabel={stand().titel}
          onClick={(e) => stand().actie?.(e)}
        />
      </span>
    </Show>
  );
}

/** "+ GEGEVENSSET": één combobox uit de targets-categorie die er een doelobject
 *  bij zet.
 *
 *  Hij schrijft `odrl:target` — het generieke predicaat. Een regel die een
 *  profiel-specifiek `subPropertyOf` gebruikt, krijgt zijn nieuwe doelobjecten
 *  dus op het generieke predicaat. Dat is de veilige kant (elke lezer begrijpt
 *  `odrl:target`); een keuzelijst van target-predicaten is werk voor later —
 *  woord voor woord de afweging van de bevroren viewer. */
export function TargetGhost(props: { kern: Kern; ctx: TargetHaakCtx }): JSX.Element {
  const regelTerm = createMemo(() => termVan(props.ctx.regel));
  const opties = createMemo(() => veldOpties('targets'));
  const stand = () => bewerkStand(props.kern, {
    mag: props.kern.bewerkbaar(regelTerm()),
    titel: tekst('edit.targetToevoegen'),
    term: regelTerm(),
    ontgrendelbaar: true,
  });
  return (
    <Show when={regelTerm()}>
      <span class={`target-toevoegen${stand().aan ? '' : ' gelockt'}`}>
        <Show
          when={stand().aan}
          fallback={(
            <Knop
              label={tekst('edit.targetToevoegen')}
              cls={stand().actie ? 'gelockt' : 'actie-uit'}
              titel={stand().titel}
              onClick={(e) => stand().actie?.(e)}
            />
          )}
        >
          <IriCombobox
            options={opties()}
            placeholder={tekst('edit.targetToevoegen')}
            ariaLabel={tekst('edit.targetToevoegen')}
            onPick={(iri) => {
              if (!iri) return;
              void props.kern.voerUit(
                (f) => props.kern.edit.addTarget(f, regelTerm(), iri),
                { groep: true },
              );
            }}
          />
        </Show>
      </span>
    </Show>
  );
}
