// DE CHROME VAN DE BEWERKSTAND: undo/redo, "nu bewaren", het aanbod als er nog
// geen bewerkbron is, en de melding van de bewerklaag.
//
// Gedragsbron: `wireEditUi`, `doeUndo`/`doeRedo` en de topbalkknoppen van de
// bevroren viewer (doc.js r.9960-10018), plus `bevestigEditMode` voor het
// aanbod. Wat hier ANDERS is:
//
//  1. DEZE BALK BESTAAT ALLEEN IN DE BEWERKSTAND. In de bevroren viewer stonden
//     de knoppen altijd in de topbalk (uitgegrijsd buiten de bewerkstand); hier
//     zit de hele component in de lazy chunk, dus buiten de bewerkstand is er
//     letterlijk niets — geen DOM, geen bytes.
//  2. HET AANBOD IS EEN EIGEN VORM. Daar was "geen schrijfbron" een melding op
//     de statusregel; sinds het één-bewerkbron-addendum is de vraag "kies of
//     maak er één" de enige zinnige voortzetting, en die hoort een handeling te
//     zijn en geen zin. Het aanbod opent daarom het bronnenpaneel, waar de
//     keuzegroep en de werkbestandknop al staan (lane-bronnen-edit) — er komt
//     geen tweede bronnenkiezer naast.
//  3. "NU BEWAREN" is de UI-kant van de verzendflow. Bij een ttl-bron duwt hij
//     de autosave-debounce eruit, bij een endpoint wacht hij de lopende SPARQL
//     Update af. `flushBron` doet allebei; de knop bestaat omdat de lezer moet
//     kunnen zien dát er nog iets uitstaat en het moet kunnen afdwingen vóór
//     hij het tabblad sluit.
import { Show, createEffect, createSignal, onCleanup } from 'solid-js';
import type { JSX } from 'solid-js';
import { bronnenOpen, zetBronnenOpen } from '../app/bronnen.jsx';
import { zetBronkeuze } from './haken.jsx';
import { tekst, weergave } from '../../stores/weergave.js';
import { Editbar, Knop } from './knop.jsx';
import { kern } from './kern.js';
import { SleepLaag } from './slepen/sleeplaag.jsx';
import { Toast } from './toast.jsx';
import './bewerk.css';

/** Ctrl+Z / Ctrl+Shift+Z / Ctrl+Y (en de cmd-varianten), op het document.
 *
 *  EEN EIGEN LISTENER, niet meeliften op die van de zijnav: die vangt Escape af
 *  en heeft zijn eigen voorwaarden. Botsen kan niet — andere toetsen, en beide
 *  keren vroeg terug.
 *
 *  IN EEN TEKSTVELD IS CTRL+Z DE UNDO VAN HET VELD (de halfgetypte tekst), niet
 *  die van het document. Die van de browser afpakken zou de inline velden
 *  onbruikbaar maken: je kunt dan geen typefout meer terugnemen zonder de vorige
 *  bewerking van de kaart ongedaan te maken. */
function koppelToetsen(): () => void {
  if (typeof document === 'undefined' || !document.addEventListener) return () => {};
  const opToets = (e: KeyboardEvent) => {
    if (!weergave.editMode) return;
    if (!(e.ctrlKey || e.metaKey) || e.altKey) return;
    const a = document.activeElement as (HTMLElement | null);
    const tag = a && a.tagName ? String(a.tagName).toLowerCase() : '';
    if (tag === 'input' || tag === 'textarea' || (a && a.isContentEditable)) return;
    const k = String(e.key || '').toLowerCase();
    let actie: (() => Promise<boolean>) | null = null;
    if (k === 'z') actie = e.shiftKey ? kern().opnieuw : kern().ongedaan;
    else if (k === 'y' && !e.shiftKey) actie = kern().opnieuw;
    if (!actie) return;
    e.preventDefault();
    void actie();
  };
  document.addEventListener('keydown', opToets);
  return () => document.removeEventListener('keydown', opToets);
}

/** HET AANBOD: er is geen bewerkbron, dus de bewerkstand kan niet aan. Geen
 *  weigering maar een route — kies er een, of maak een werkbestand. Beide
 *  staan in het bronnenpaneel; deze balk zet dat open en zegt waarom.
 *
 *  DE KNOPPEN HEETTEN `-ok` EN `-nee` (opruimpunt 19, 10 sep 2026). Dat is een
 *  naamresidu van de vervallen bevestigflow: op een `role="status"`-balk lezen
 *  die twee als "bevestigen" en "afwijzen", terwijl er niets te bevestigen valt.
 *  De ene knop OPENT het bronnenpaneel, de andere SLUIT het aanbod; ze heten nu
 *  naar wat ze doen. Geen stijlblad mikte erop en geen toets noemde ze, dus de
 *  hernoeming raakt niets anders dan de leesbaarheid. */
function Aanbod(): JSX.Element {
  return (
    <div class="bewerk-aanbod" role="status">
      <span class="bewerk-aanbod-uitleg">{tekst('edit.geenSchrijfbron')}</span>
      {' '}
      <Editbar>
        <Knop
          label={tekst('edit.kiesBewerkbron')}
          cls="bewerk-aanbod-kies"
          onClick={() => { if (!bronnenOpen()) zetBronnenOpen(true); }}
        />
        <Knop
          label={tekst('edit.annuleren')}
          cls="bewerk-aanbod-sluit"
          onClick={() => kern().sluitAanbod()}
        />
      </Editbar>
    </div>
  );
}

/** De balk onder de kop. Hij staat er zodra de bewerklaag geladen is en de
 *  bewerkstand aan is (of het aanbod openstaat) — niet daarvoor: in de
 *  leesstand hoort de pagina er identiek uit te zien als vóór dit deeltraject. */
export function Chrome(): JSX.Element {
  const [bezig, zetBezig] = createSignal(false);
  onCleanup(koppelToetsen());

  // DE LEESKANT MOET WETEN DAT ER OM EEN BEWERKBRON GEVRAAGD WORDT: het
  // bronnenpaneel toont zijn KEUZEGROEP alleen in de bewerkvorm, en die stand
  // is er zonder bewerkbron juist niet. Zie `bronpaneelBewerkt` daar.
  //
  // Het paneel OPENKLAPPEN doet deze effect bewust niet — dat hoort bij de klik
  // op de bewerkknop (`schakelBewerkstand`) en niet bij de stand zelf; zie de
  // reden daar.
  createEffect(() => zetBronkeuze(kern().aanbodOpen()));
  onCleanup(() => zetBronkeuze(false));

  const bewaar = () => {
    zetBezig(true);
    void kern().flushBron().finally(() => zetBezig(false));
  };

  return (
    <Show when={weergave.editMode || kern().aanbodOpen()}>
      <div class="bewerk-balk" id="bewerk-balk">
        <Show when={weergave.editMode}>
          <Editbar>
            {/* UNDO EN REDO STAAN HIER ALS EIGEN <button> en niet als <Knop>.
                Gemeten in de GEBOUWDE app (golf B): via de `cls`-prop van
                <Knop> bleef de klasse op zijn eerste waarde staan — de knop
                wérkte (de klik draaide terug) maar zag er permanent uitgezet
                uit. `kanOngedaan()` gaf op datzelfde moment `true`; de
                render-effect van <Knop> volgde de wijziging niet over de
                chunkgrens heen. Alleen deze twee knoppen hangen aan een stand
                die tijdens het bewerken verandert, dus alleen zij hebben er
                last van; de rest van de bewerklaag geeft <Knop> statische
                waarden. Een knop die liegt over wat hij kan, is erger dan een
                extra regel JSX. */}
            <button
              type="button"
              class={kern().kanOngedaan() ? 'edit-knop bewerk-undo' : 'edit-knop bewerk-undo actie-uit'}
              title={tekst('edit.undo')}
              aria-label={tekst('edit.undo')}
              aria-disabled={kern().kanOngedaan() ? undefined : 'true'}
              on:click={(e: MouseEvent) => {
                e.preventDefault();
                e.stopPropagation();
                if (kern().kanOngedaan()) void kern().ongedaan();
              }}
            >↶</button>
            <button
              type="button"
              class={kern().kanOpnieuw() ? 'edit-knop bewerk-redo' : 'edit-knop bewerk-redo actie-uit'}
              title={tekst('edit.redo')}
              aria-label={tekst('edit.redo')}
              aria-disabled={kern().kanOpnieuw() ? undefined : 'true'}
              on:click={(e: MouseEvent) => {
                e.preventDefault();
                e.stopPropagation();
                if (kern().kanOpnieuw()) void kern().opnieuw();
              }}
            >↷</button>
            <Knop
              label={tekst('edit.bewaarNu')}
              cls="bewerk-bewaar"
              titel={tekst('edit.bewaarNuUitleg')}
              onClick={bewaar}
            />
          </Editbar>
          <Show when={bezig()}>
            <span class="bewerk-bezig muted" role="status">{tekst('edit.bewaarBezig')}</span>
          </Show>
          {/* De bewerkbron in beeld: welke bron krijgt wat ik nu typ? Dat is de
              vraag die het één-bewerkbron-model oproept, en het antwoord hoort
              in de balk te staan waar de bewerkingen beginnen. */}
          <Show when={kern().bewerkbron()}>{(b) => (
            <span class="bewerk-bron muted">
              {tekst('edit.schrijfbron')}{' '}
              <span class="bewerk-bron-naam">{b().name || b().url || b().graph}</span>
            </span>
          )}</Show>
        </Show>
        <Show when={kern().aanbodOpen()}><Aanbod /></Show>
        {/* HET ENE MONTAGEPUNT VAN HET SLEEPGEBAAR (montagestap 1 van het
            lane-slepen-report). `SleepLaag` hangt bij het monteren de vier
            luisteraars op — pointermove/up/cancel plus de Escape-laag aan het
            VENSTER — en tekent het spookje; bij het opruimen gaan ze weer weg.
            Precies één keer, en binnen de lazy bewerkchunk: in `app.tsx` zou een
            statische import de hele laag de instap in trekken.
            Hij hoort ín de bewerkstand-tak en niet erbuiten: buiten de
            bewerkstand is er geen greep, dus ook niets om te annuleren. */}
        <Show when={weergave.editMode}><SleepLaag /></Show>
        {/* DE MELDING LINKSONDER (eigenaarsbesluit 8 sep 2026): wat er zojuist
            verdween, met de ongedaan-maken-link erbij. Hij hoort in de
            bewerkstand-tak en niet erbuiten: buiten de bewerkstand is er niets
            te verwijderen en dus niets te melden. `.bewerk-toast` ligt vast in
            de viewport, dus dat hij hier in de balk gemonteerd wordt zegt niets
            over waar hij staat — alleen dat hij met de stand komt en gaat. */}
        <Show when={weergave.editMode}><Toast /></Show>
      </div>
    </Show>
  );
}
