// DE SLOTEDITOR: het formulier onder de chips van één voorwaarde.
//
// Gedragsbron: `sloteditor`, `slotCombobox`, `waardeSoortSelect`,
// `taalDatatypeSelect` en `gedeeldeVoorwaarde` in het fase C-taak 6-blok van
// viewer-bevroren/assets/doc.js (r.2455-2574). Pariteit is de norm; wat er in de
// vertaling naar Solid anders is staat hieronder met de reden erbij.
//
// WAAROM ÉÉN FORMULIER EN GEEN DRIE INLINE VELDEN. Een voorwaarde is DRIE SLOTS
// op één knoop: grootheid (odrl:leftOperand), operator (odrl:operator) en
// waarde (odrl:rightOperand). Die drie horen bij elkaar — een operator omzetten
// zonder de waarde mee te veranderen levert doorgaans onzin op — en de waarde
// draagt nog een SOORT (letterlijke waarde of verwijzing) en een taal/datatype
// naast zich. Vandaar vijf rijen en één Opslaan, en dus ook ÉÉN undo-stap: drie
// slots vervangen levert tot zes delta's op, en zonder `{ groep: true }` zou één
// undo daar een derde van terugdraaien en de voorwaarde half gewijzigd
// achterlaten.
//
// EEN LEGE VOORWAARDE IS HET NORMALE BEGIN (eigenaarsbesluit 8 sep 2026). De
// ghost maakt een voorwaarde ZONDER slots — geen gefingeerde tijdvoorwaarde meer
// — en dit formulier gaat er meteen op open, met de cursor in de grootheid. Het
// formulier hoeft daar niets extra's voor te doen: lege slots zijn lege velden.
import { For, Show, createMemo, createSignal, onMount } from 'solid-js';
import type { JSX } from 'solid-js';
import { expandIri } from '../../../model/edit.js';
import { curie } from '../../../model/parse.js';
import { geldigeIriTekst } from '../../../model/velden.js';
import { tekst, zetMelding } from '../../../stores/weergave.js';
import type { Term } from '../../../model-grens.js';
import { veldOpties } from '../kaartveld.jsx';
import { filterSuggesties, focusZonderSprong, IriCombobox, optieTekst } from '../veld.jsx';
import type { VeldHaak } from '../veld.jsx';
import { ODRL } from './anker.js';
import { Editbar, Knop } from '../knop.jsx';
import { SLOT_DATATYPES, samengesteldeWaarde, slotWaarden } from './slots.js';
import type { Kern } from './kern.js';
import './sloteditor.css';

/** De rechterwaarde zoals `setConstraint` haar wil. */
interface Rechts {
  value: string; kind: 'iri' | 'literal'; lang?: string; datatype?: string;
}

/** Eén slot-combobox. Zelfde bouwsteen als de kernvelden (`IriCombobox` met de
 *  gedeelde optielijst uit `termOptions`), maar ZONDER eigen save: dit formulier
 *  slaat in één keer op. `onPick` blijft dus leeg — de waarde wordt bij Opslaan
 *  uit de haak gelezen. */
function SlotCombobox(props: {
  categorie: string; huidig: string; label: string; hint: string;
  haak: (api: VeldHaak & { waarde: () => string }) => void;
}): JSX.Element {
  const opties = createMemo(() => veldOpties(props.categorie));
  return (
    <span class="c-editor-slot">
      <IriCombobox
        options={opties()}
        value={optieTekst(opties(), props.huidig) || props.huidig}
        ariaLabel={props.label}
        // DE HINT VAN EEN LEEG SLOT (eigenaarsbevinding 9 sep 2026, tweede
        // ronde). Een VERSE voorwaarde opent met drie lege slots, en die droegen
        // alle drie de algemene hint van de combobox ("IRI of prefix:naam") of
        // helemaal geen. Die zegt wat de VORM van de invoer is; het `aria-label`
        // ernaast zegt welk slot het is, maar dat leest alleen een schermlezer.
        // Deze hint zegt allebei, in het veld zelf.
        placeholder={props.hint}
        haak={props.haak}
      />
    </span>
  );
}

/** DE TAAL-/DATATYPEKEUZE. Dezelfde rij als in de bevroren viewer: geen
 *  markering, @nl/@en, en de vijf xsd-typen die in dit domein voorkomen — plus,
 *  als de voorwaarde iets anders draagt (@fr, xsd:gYear), die waarde zelf, zodat
 *  opslaan haar niet stilzwijgend afkapt.
 *
 *  Talen krijgen een `lang:`-voorvoegsel: zonder dat zou een tweeletterige
 *  taalcode niet van een datatype-IRI te onderscheiden zijn. */
function taalDatatypeOpties(rechts: { lang: string; datatype: string }): [string, string][] {
  const opties: [string, string][] = [
    ['', tekst('edit.geenTaalDatatype')], ['lang:nl', '@nl'], ['lang:en', '@en'],
    ...SLOT_DATATYPES.map((d) => [d, (curie(d) as string) || d] as [string, string]),
  ];
  const huidig = rechts.lang ? `lang:${rechts.lang}` : (rechts.datatype || '');
  if (huidig && !opties.some(([v]) => v === huidig)) {
    opties.push([huidig, rechts.lang ? `@${rechts.lang}`
      : ((curie(rechts.datatype) as string) || huidig)]);
  }
  return opties;
}

/** DE OPTIECATEGORIE VAN HET WAARDESLOT, afgeleid van de GROOTHEID ernaast.
 *
 *  EIGENAARSRICHTING 9 SEP 2026 (deel 1 van de lane-brief: "doelvelden bestaande
 *  doelen"). De doelbinding is in ODRL-AP-NL geen kaal veld op de regel maar een
 *  `odrl:purpose`-refinement — deze voorwaarde dus — en haar rechterwaarde is
 *  het DOEL. `termOptions` bouwde die lijst (`purposes`) al, maar er was geen
 *  enkele afnemer: het waardeslot was een kaal tekstvak, en een doel dat vijf
 *  regels delen werd vijf keer overgetypt.
 *
 *  De grootheid is het enige gegeven dat zegt WAT voor waarde hier hoort. Staat
 *  er iets anders dan `odrl:purpose`, dan is `labeled` het eerlijke antwoord —
 *  alles met een naam, precies wat de vrije IRI-velden elders ook bieden. */
function waardeCategorie(links: string): string {
  return links === `${ODRL}purpose` ? 'purposes' : 'labeled';
}

/** Elk formulier zijn eigen `<datalist>`-id, om dezelfde reden als in
 *  `veld.tsx`: een Solid-component ontstaat en verdwijnt los, en een gedeelde
 *  lijst zou aan de levensduur van de eerste hangen. */
let waardeLijstTeller = 0;

export function SlotEditor(props: {
  kern: Kern;
  /** De voorwaarde-knoop. */
  term: Term;
  /** De rij zoals de weergave haar kent — alleen voor de chip-tekst van een
   *  samengestelde waarde en voor het gedeeld-bericht. */
  c: { slots?: { right?: { texts?: string[] } | null } | null } | null;
  /** Sluit het formulier (Annuleren, of na een geslaagde save). */
  opSluiten: () => void;
  /** Welk veld de cursor krijgt bij het openen. `links` bij een verse
   *  voorwaarde (daar begint het invullen), `waarde` als de grootheid al
   *  vaststaat (de groeperingsvoorwaarde-shortcut), en anders niets — een ✎-klik
   *  hoort de bladerpositie niet te verzetten. */
  focus?: 'links' | 'waarde' | null;
  /** HET FORMULIER STAAT NU ÉCHT IN DE DOM. De toevoegfocus gebruikt hem om zijn
   *  verzoek pas dán op te ruimen — zie `VoorwaardeStrook` in `rij-bewerk.tsx`
   *  en de gemeten reden bij `neemFocusAan` in `ui/bewerk/kaartveld.tsx`. */
  opGeopend?: () => void;
}): JSX.Element {
  const graaf = () => props.kern.graaf();
  const w = createMemo(() => slotWaarden(graaf(), props.term, curie as (i: string) => string | null));
  const vast = createMemo(() => samengesteldeWaarde(graaf(), props.term));
  // IS DIT EEN BENOEMDE (en dus mogelijk GEDEELDE) bouwsteen? Een blanke knoop
  // hoort bij precies één regel; een IRI-voorwaarde kan overal gebruikt worden,
  // en dan verandert deze bewerking hem óók daar. De marker+telling die de
  // leeskant al toont (`GedeeldMarker`) zegt WAAR; deze regel zegt WAT het
  // betekent op het moment dat je gaat schrijven.
  const gedeeld = () => props.term.termType === 'NamedNode';

  let linksHaak: (VeldHaak & { waarde: () => string }) | null = null;
  let opHaak: (VeldHaak & { waarde: () => string }) | null = null;
  let waardeEl!: HTMLInputElement;
  let soortEl!: HTMLSelectElement;
  let dtEl!: HTMLSelectElement;

  // Een samengestelde waarde is niet in één veld te vangen: toon wat de chips
  // tonen, gedempt, en laat hem met rust.
  const chipTekst = () => (props.c?.slots?.right?.texts || []).join(', ');
  const [soort, zetSoort] = createSignal<'literal' | 'iri'>(w().right.kind);

  // DE SUGGESTIES VAN HET WAARDESLOT. Alleen bij een VERWIJZING: een letterlijke
  // waarde (een datum, een aantal) heeft geen kandidatenlijst, en een datalist
  // die er dan tóch hangt zou beloven dat er uit gekozen moet worden.
  //
  // GEEN `IriCombobox` maar een `<datalist>` op het bestaande veld, en dat is een
  // RULING (lane-knoophergebruik). De combobox draagt een RESOLUTIE — een exacte
  // labelmatch wint van `expandIri` — en dit veld heeft die niet: `opslaan`
  // hieronder leest `waardeEl.value` en gooit hem door `expandIri`. Zou de
  // datalist hier het LABEL invullen zoals bij de combobox, dan werd "Bijhouden
  // BRP" als `<Bijhouden BRP>` weggeschreven — precies de onparseerbare bron waar
  // `geldigeIriTekst` tegen bestaat. Vandaar de omgekeerde vorm: de CURIE (of de
  // volle IRI) als `value`, het label als `label`-attribuut ernaast. Kiezen zet
  // dus een curie in het veld, en die round-trip't wél.
  //
  // KOST BIJ ONGELIJK: het waardeslot toont curies waar de kernvelden labels
  // tonen. Het alternatief — dit veld ook een `IriCombobox` maken — raakt de
  // literal-tak, de `vast()`-tak en de taal/datatype-koppeling, en dat is een
  // herbouw van het formulier voor één suggestielijst.
  const [getypteWaarde, zetGetypteWaarde] = createSignal('');
  const waardeOpties = createMemo(() => (soort() === 'iri'
    ? filterSuggesties(veldOpties(waardeCategorie(w().left)), getypteWaarde())
    : []));
  waardeLijstTeller += 1;
  const waardeLijstId = `slot-waarde-dl-${waardeLijstTeller}`;

  // DE SELECTS KRIJGEN HUN WAARDE PAS NÁ HET VULLEN. Een <select> neemt alleen
  // een waarde aan die er al als <option> in staat; zetten we hem als attribuut,
  // dan hangt het van de volgorde van de compiler af of de opties er al zijn.
  // Dezelfde noot staat in de bevroren viewer bij `doelOperatorSelect`.
  onMount(() => {
    soortEl.value = w().right.kind;
    dtEl.value = w().right.lang ? `lang:${w().right.lang}` : (w().right.datatype || '');
    // BEIDE TAKKEN ZONDER SPRONG (punt 4 van de testronde, 9 sep 2026). De
    // waarde-tak deed het al met de hand; de grootheid-tak liep over
    // `openBewerk` van de combobox, en díe deed een kale `focus()` — de gemeten
    // 427px-sprong. De helper zit nu in `veld.tsx`, waar beide velden wonen.
    if (props.focus === 'links') linksHaak?.openBewerk();
    else if (props.focus === 'waarde') focusZonderSprong(waardeEl);
    props.opGeopend?.();
  });

  const opslaan = (): void => {
    const links = linksHaak ? linksHaak.waarde() : '';
    const operator = opHaak ? opHaak.waarde() : '';
    for (const iri of [links, operator]) {
      if (iri && !geldigeIriTekst(iri)) {
        zetMelding('edit.ongeldigeIri', { invoer: iri });
        return;
      }
    }
    let rechts: Rechts | undefined;
    if (!vast()) {
      if (soortEl.value === 'iri') {
        const iri = expandIri(String(waardeEl.value || '').trim()) as string;
        if (iri && !geldigeIriTekst(iri)) {
          zetMelding('edit.ongeldigeIri', { invoer: waardeEl.value });
          return;
        }
        rechts = { value: iri, kind: 'iri' };
      } else {
        const keuze = String(dtEl.value || '');
        rechts = {
          value: waardeEl.value,
          kind: 'literal',
          lang: keuze.startsWith('lang:') ? keuze.slice(5) : undefined,
          datatype: keuze && !keuze.startsWith('lang:') ? keuze : undefined,
        };
      }
    }
    // ÉÉN GROEP: drie slots vervangen levert tot zes delta's op (oude waarde
    // eruit, nieuwe erin, drie keer). Zonder groep zou één undo daar een derde
    // van terugdraaien en de voorwaarde half gewijzigd achterlaten.
    void props.kern.voerUit(
      (f) => props.kern.edit.setConstraint(f, props.term, { left: links, operator, right: rechts }),
      { groep: true },
    ).then((ok) => { if (ok) props.opSluiten(); }).catch(() => {});
  };

  return (
    <div class="c-editor">
      <Show when={gedeeld()}>
        <p class="c-editor-waarschuwing">
          {tekst('edit.gedeeldeBouwsteen', {
            term: (curie(props.term.value) as string) || props.term.value,
          })}
        </p>
      </Show>
      <div class="c-editor-form">
        <label class="c-editor-label">{tekst('edit.slotLinks')}</label>
        <SlotCombobox
          categorie="leftOperands" huidig={w().left} label={tekst('edit.slotLinks')}
          hint={tekst('edit.hintGrootheid')}
          haak={(api) => { linksHaak = api; }}
        />
        <label class="c-editor-label">{tekst('edit.slotOperator')}</label>
        <SlotCombobox
          categorie="operators" huidig={w().operator} label={tekst('edit.slotOperator')}
          hint={tekst('edit.hintOperator')}
          haak={(api) => { opHaak = api; }}
        />
        <label class="c-editor-label">{tekst('edit.slotSoort')}</label>
        <select
          ref={(n) => { soortEl = n; }}
          class="edit-input c-editor-soort"
          aria-label={tekst('edit.slotSoort')}
          disabled={vast()}
          on:change={(e) => zetSoort((e.currentTarget as HTMLSelectElement).value as 'iri')}
        >
          <option value="literal">{tekst('edit.waardeLiteral')}</option>
          <option value="iri">{tekst('edit.waardeIri')}</option>
        </select>
        <label class="c-editor-label">{tekst('edit.slotWaarde')}</label>
        <input
          ref={(n) => { waardeEl = n; }}
          type="text"
          class="edit-input c-editor-waarde"
          aria-label={tekst('edit.slotWaarde')}
          // Het WAARDESLOT droeg als enige van de drie helemaal geen hint: een
          // leeg kaal tekstvak naast twee comboboxen. Zelfde ronde, zelfde
          // reden — een leeg veld hoort te zeggen wat erin komt.
          placeholder={vast() ? undefined : tekst('edit.hintWaarde')}
          disabled={vast()}
          list={waardeLijstId}
          on:input={(e) => zetGetypteWaarde((e.currentTarget as HTMLInputElement).value)}
          value={vast() ? chipTekst() : w().right.value}
          // ENTER SLAAT OP, ESCAPE SLUIT — dezelfde twee toetsen als in elk
          // ander veld van deze app (`InlineVeld`), en om dezelfde reden met
          // `on:`: Solid delegeert keydown naar het document, en de
          // Escape-listeners die daar hangen (invulling-paneel, sectiefilter,
          // zijnav) zijn dan niet meer tegen te houden.
          on:keydown={(e: KeyboardEvent) => {
            if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); opslaan(); }
            if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); props.opSluiten(); }
          }}
        />
        {/* DE KANDIDATENLIJST VAN HET WAARDESLOT — zie `waardeOpties` hierboven
            voor waarom hier een curie in de `value` staat en geen label. */}
        <datalist id={waardeLijstId}>
          <For each={waardeOpties()}>{(o) => (
            <option value={o.curie || o.iri} label={o.label !== o.curie ? o.label : undefined} />
          )}</For>
        </datalist>
        <label class="c-editor-label">{tekst('edit.slotTaalDatatype')}</label>
        <select
          ref={(n) => { dtEl = n; }}
          class="edit-input c-editor-dt"
          aria-label={tekst('edit.slotTaalDatatype')}
          // ALLEEN BIJ EEN LETTERLIJKE WAARDE. Een verwijzing (IRI) draagt geen
          // taal en geen datatype; het veld laten staan zou een keuze suggereren
          // die de save toch weggooit.
          disabled={vast() || soort() === 'iri'}
        >
          <For each={taalDatatypeOpties(w().right)}>{([v, label]) => (
            <option value={v}>{label}</option>
          )}</For>
        </select>
      </div>
      <Show when={vast()}>
        <p class="c-editor-vast muted">{tekst('edit.waardeVast')}</p>
      </Show>
      <Editbar>
        <Knop label={tekst('edit.opslaan')} cls="c-editor-opslaan" onClick={opslaan} />
        {/* Annuleren = het formulier sluiten; er is nog niets gemuteerd. */}
        <Knop label={tekst('edit.annuleren')} cls="c-editor-annuleren" onClick={props.opSluiten} />
      </Editbar>
    </div>
  );
}
