// DE MUTATIEKERN, zoals de bewerklaag hem gebruikt.
//
// `stores/bewerk.ts` mag door niets STATISCH geïmporteerd worden: hij trekt
// `model/edit.js` en de hele serialisatielaag mee, en een statische importeur
// zet die in de chunk van wie hem importeert. `stores/lazy-grens.test.ts`
// bewaakt die regel over heel `src/`, en terecht — de eerste keer dat iemand
// hem vergeet, groeit de leeschunk met 20 kB zonder dat iemand het merkt.
//
// Vandaar deze module: de kern komt via ÉÉN dynamische import binnen en wordt
// hier vastgehouden, zodat de rest van de bewerklaag hem als gewone functies
// kan aanroepen. De import gebeurt in `koppelKern()`, die `laag.tsx` aanroept
// vóór hij zijn haken registreert — dus vóór er ook maar één bewerkbaar veld op
// het scherm kan staan.
//
// WAAROM GEEN TOP-LEVEL AWAIT: dat zou hetzelfde bereiken in één regel, maar
// het zet een await-grens op elke chunk die deze module importeert en maakt de
// laadvolgorde afhankelijk van de buildtarget. Een expliciete `koppelKern()` is
// zichtbaar in de aanroepketen en in een test te sturen.

/** De vorm van de mutatiekern. Type-positie, dus deze regel haalt geen byte
 *  binnen — hij verdwijnt bij het compileren. */
export type Kern = typeof import('../../stores/bewerk.js');

let vastgehouden: Kern | null = null;

/** Haal de mutatiekern binnen (idempotent). */
export async function koppelKern(): Promise<Kern> {
  if (!vastgehouden) vastgehouden = await import('../../stores/bewerk.js');
  return vastgehouden;
}

/** De kern, of een luide fout. Aanroepen vóór `koppelKern()` is een
 *  programmeerfout in de laadvolgorde en geen toestand om op te vangen: een
 *  stille no-op zou een bewerking laten verdwijnen. */
export function kern(): Kern {
  if (!vastgehouden) throw new Error('bewerklaag: de mutatiekern is niet gekoppeld');
  return vastgehouden;
}

/** Testhaak: de kern rechtstreeks inhangen (of loskoppelen met `null`). */
export function _zetKernVoorTest(k: Kern | null): void { vastgehouden = k; }
