// DE MELDING LINKSONDER: wat er zojuist verdween, met de weg terug ernaast.
//
// EIGENAARSBESLUIT 8 SEP 2026. Het ✕ vroeg eerst om bevestiging ("Dit onderdeel
// verwijderen? Het wordt nergens anders gebruikt en verdwijnt daarmee uit het
// bestand.") — overgenomen uit de bevroren viewer, waar `bevestig()` een
// `window.confirm` was (doc.js r.2788/3334/3549). Met undo/redo slaat die vraag
// nergens op: hij kost bij ELKE verwijdering een handeling om een vergissing te
// voorkomen die met één klik achteraf is opgelost, en hij onderbreekt de flow
// met een systeemdialoog waar de rest van de bewerkstand inline werkt.
//
// Wat ervoor in de plaats komt is de omgekeerde volgorde: eerst doen, dan
// melden, met de ongedaan-maken-link erbij. Die link is een GEMAK en geen tweede
// mechanisme — hij roept dezelfde `ongedaan()` aan als de ↶ in de balk en als
// Ctrl+Z.
//
// DRIE EIGENSCHAPPEN die deze melding moet hebben, en waarom:
//
//  1. GEEN FOCUS-STEAL. De cursor staat na een bewerking waar de lezer hem
//     zette (en na een TOEVOEGING zelfs bewust in het nieuwe titelveld, zie het
//     focusverzoek in `ui/gedeeld/bewerkhaak.tsx`). Een melding die de focus
//     grijpt zou dat afpakken. Vandaar `aria-live="polite"`: hulpmiddelen lezen
//     hem voor zonder dat er iets verspringt.
//  2. HIJ VERDWIJNT VANZELF. Een melding over iets wat al gebeurd is, hoort geen
//     afhandeling te vragen; blijft hij staan, dan is hij binnen een minuut een
//     stuk chrome dat niemand meer leest. De ↶ in de balk blijft daarna gewoon
//     de weg terug — de link is alleen de kortste.
//  3. HIJ LIGT LINKSONDER EN NIET IN DE FLOW. Rechtsonder zit het
//     invulling-paneel, bovenin de bewerkbalk; linksonder is de enige hoek die
//     in de bewerkstand vrij is, en een vaste plek is wat een vluchtige melding
//     vindbaar maakt.
import { Show, createEffect, createSignal, on, onCleanup } from 'solid-js';
import type { JSX } from 'solid-js';
import { tekst } from '../../stores/weergave.js';
import { kern } from './kern.js';
import './bewerk.css';

/** Hoe lang de melding blijft staan. Lang genoeg om te lezen en de link te
 *  raken, kort genoeg om niet in de weg te gaan liggen. */
export const TOAST_MS = 6000;

/** De lopende melding: de i18n-sleutel plus een teken dat elke nieuwe melding
 *  uniek maakt (twee keer dezelfde sleutel achter elkaar moet de timer opnieuw
 *  starten en de melding opnieuw laten voorlezen). */
const [melding, zetMelding] = createSignal<{ sleutel: string; teken: number } | null>(null);
let teller = 0;

export { melding as toastMelding };

/** Meld wat er zojuist gebeurd is. `sleutel` is een i18n-sleutel. */
export function toonToast(sleutel: string): void {
  if (!sleutel) return;
  teller += 1;
  zetMelding({ sleutel, teken: teller });
}

/** De melding weghalen (na de timer, na een klik, en in tests). */
export function wisToast(): void { zetMelding(null); }

export function Toast(): JSX.Element {
  let tik: ReturnType<typeof setTimeout> | null = null;
  const stop = () => { if (tik) { clearTimeout(tik); tik = null; } };
  onCleanup(stop);
  // DE TIMER HOORT IN EEN EFFECT EN NIET IN DE JSX. Dat was hier eerst wél zo, en
  // de unittest ving het: het functie-kind van `<Show>` draait ÉÉN keer zolang de
  // voorwaarde waar blijft, dus een tweede verwijdering verving wel de tekst maar
  // niet de klok — de nieuwe melding verdween dan op de timer van de vorige, soms
  // binnen een tiende seconde. Het effect volgt het signaal (inclusief `teken`,
  // dat twee keer dezelfde sleutel onderscheidbaar maakt) en zet de klok telkens
  // opnieuw.
  createEffect(on(melding, (m) => {
    stop();
    if (!m) return;
    tik = setTimeout(() => { tik = null; wisToast(); }, TOAST_MS);
  }));
  return (
    <Show when={melding()}>{(m) => (
        <div class="bewerk-toast" role="status" aria-live="polite">
          <span class="bewerk-toast-tekst">{tekst(m().sleutel)}</span>
          {/* Een echte <button> en geen <a>: er wordt niet genavigeerd. De
              klasse heet `bewerk-toast-undo` zodat een toets hem kan aanwijzen
              zonder de ↶ in de balk te raken. */}
          <button
            type="button"
            class="bewerk-toast-undo"
            on:click={(e: MouseEvent) => {
              e.preventDefault();
              e.stopPropagation();
              wisToast();
              void kern().ongedaan();
            }}
          >{tekst('edit.undo')}</button>
          <button
            type="button"
            class="bewerk-toast-sluit"
            title={tekst('edit.toastSluiten')}
            aria-label={tekst('edit.toastSluiten')}
            on:click={(e: MouseEvent) => { e.preventDefault(); e.stopPropagation(); wisToast(); }}
          >×</button>
        </div>
    )}</Show>
  );
}
