// WAAR HANGT DEZE KNOOP AAN, EN WAT KOST HET OM HEM LOS TE MAKEN?
//
// Gedragsbron: `knoopAnker`, `voorwaardeAnker`, `blijftInGebruik` en
// `losmaakQuads` in viewer-bevroren/assets/doc.js (fase C taken 6/7/8). PUUR: deze
// module leest een store en rekent; zij muteert niets en kent geen bewerkstand.
// Dat is wat haar toetsbaar maakt zonder corpus en zonder bewerkbron.
//
// WAAROM DE UI DIT ZELF UITREKENT terwijl `removeAttached` (edit.js) het óók
// doet: de strook moet VOORAF weten of het ✕ "verwijderen" of "losmaken" heet,
// welke bevestigingsvraag erbij hoort, en of alles wat eraan gaat wel in de
// bewerkbron staat. Eén bron van waarheid blijft het uitgangspunt — de lijst
// die `losmaakQuads` oplevert is exact wat `removeAttached` gaat wissen.
import { PREFIXES } from '../../../model/parse.js';
import { termVan as termVanJs } from '../../../model/term.js';
import type { Quad, Term } from '../../../model-grens.js';

export const ODRL = PREFIXES.odrl as string;
const PROV = PREFIXES.prov as string;

/** De predicaten waarmee een REGEL of PLICHT ergens aan hangt. Gelijk aan
 *  `AANHECHT_PREDS` in `model/edit.js`; hier herhaald omdat deze module ook
 *  bruikbaar moet zijn zonder de mutatielaag in te laden. */
export const KNOOP_PREDS = [
  `${ODRL}permission`, `${ODRL}prohibition`, `${ODRL}obligation`,
  `${ODRL}duty`, `${ODRL}consequence`,
];

/** De predicaten waarmee een VOORWAARDE aan een regel of aan haar actie-knoop
 *  hangt (doc.js r.2373). */
export const VOORWAARDE_PREDS = [`${ODRL}constraint`, `${ODRL}refinement`];

const REALISATIE = `${PROV}wasDerivedFrom`;

/** De minimale store die deze module nodig heeft. */
export interface Leesstore {
  getQuads(s: Term | null, p: Term | null, o: Term | null, g: Term | null): Quad[];
}

export interface Anker { parent: Term; pred: string }

/** Maak van een IRI-string of een knoop uit het model een term voor de store.
 *  `null` als er niets aanwijsbaars is (een weergave-constructie).
 *
 *  DE WORKER-HANDLE IS GEEN RANDGEVAL MAAR DE GEWONE VORM: het model wordt in
 *  de worker gebouwd en met structured clone teruggestuurd, en dat verliest het
 *  PROTOTYPE van elke N3-term. Deze module droeg daarvoor een EIGEN decoder
 *  (`uitId` + een tweede `termVan`), die op vijf van zes ingangen een ander
 *  antwoord gaf dan de kopie in `model/velden.js` (eindreview I-1). Beide zijn
 *  opgegaan in `model/term.js`; wat hier staat is de GETYPEERDE GRENS naar die
 *  JavaScript-module — één cast in plaats van een cast per aanroepplek, dezelfde
 *  afspraak als in `model-grens.ts` en `slepen/sleepgebaar.ts`.
 *
 *  EÉN GEDRAGSVERSCHIL is bewust: `termVan({ id: '"lit"' })` levert nu de
 *  literal in plaats van `null`. Dat `null` was het oordeel "er hangt geen regel
 *  aan een literal" — een oordeel van de AANROEPER, niet van de decoder. Het
 *  raakt de ankerfuncties hieronder niet: een literal komt nooit als subject uit
 *  `getQuads` terug, dus `knoopAnker` valt op precies dezelfde tak terug. */
export const termVan = termVanJs as (x: unknown) => Term | null;

function gelijk(a: Term, b: Term): boolean {
  return a.termType === b.termType && a.value === b.value;
}

/** WAAR HANGT DEZE KNOOP AAN? Eerst de koppeling van de kaart/rij die we NÚ
 *  tekenen (`voorkeur`), dan — als er maar ÉÉN koppeling bestaat — die ene.
 *  Blijft er twijfel (een gedeelde plicht, getekend zonder ouder), dan geen
 *  anker en dus geen losmaakknop: liever geen knop dan een knop die de
 *  verkeerde koppeling verbreekt. */
export function knoopAnker(
  store: Leesstore | null, t0: Term | null, preds: string[], voorkeur?: unknown,
): Anker | null {
  if (!store || !t0) return null;
  const kandidaten: Quad[] = [];
  for (const pred of preds) {
    kandidaten.push(...store.getQuads(null, termVan(pred), t0, null));
  }
  if (!kandidaten.length) return null;
  const v = termVan(voorkeur);
  const eigen = (v && kandidaten.find((q) => gelijk(q.subject, v)))
    || (kandidaten.length === 1 ? kandidaten[0] : null);
  return eigen ? { parent: eigen.subject, pred: eigen.predicate.value || '' } : null;
}

/** HET ANKER VAN EEN VOORWAARDE. Eén tak méér dan `knoopAnker`: een voorwaarde
 *  mag als `odrl:refinement` onder de ACTIE-knoop van de regel hangen, en die
 *  knoop is blank — de aanroeper kent hem niet. Daarom zoeken we hem hier op,
 *  vanaf de regel. */
export function voorwaardeAnker(
  store: Leesstore | null, cTerm: Term | null, regelTerm: Term | null,
): Anker | null {
  if (!store || !cTerm) return null;
  const kandidaten: Quad[] = [];
  for (const pred of VOORWAARDE_PREDS) {
    kandidaten.push(...store.getQuads(null, termVan(pred), cTerm, null));
  }
  if (!kandidaten.length) return null;
  const acties = new Set<string>();
  if (regelTerm) {
    for (const q of store.getQuads(regelTerm, termVan(`${ODRL}action`), null, null)) {
      if (q.object.value) acties.add(q.object.value);
    }
  }
  const eigen = (regelTerm && kandidaten.find((q) => gelijk(q.subject, regelTerm)))
    || kandidaten.find((q) => acties.has(q.subject.value || ''))
    || (kandidaten.length === 1 ? kandidaten[0] : null);
  return eigen ? { parent: eigen.subject, pred: eigen.predicate.value || '' } : null;
}

/** BLIJFT DEZE KNOOP NA HET LOSMAKEN IN GEBRUIK? Precies de toets die
 *  `removeAttached` zelf doet: zelfverwijzingen (odrl:uid naar zichzelf) en
 *  REALISATIELINKS (prov:wasDerivedFrom vanaf een dekkingsanker) tellen niet
 *  als gebruiker. Dit bepaalt of het ✕ "losmaken" of "verwijderen" heet. */
export function blijftInGebruik(
  store: Leesstore | null, anker: Anker | null, t0: Term | null,
): boolean {
  if (!store || !anker || !t0) return false;
  const ouder = anker.parent;
  if (!ouder || !ouder.value) return false;
  return store.getQuads(null, null, t0, null).some((q) => !(
    q.subject.value === ouder.value && q.predicate.value === anker.pred)
    && !gelijk(q.subject, t0)
    && q.predicate.value !== REALISATIE);
}

/** WAT RAAKT HET LOSMAKEN? Exact de quads die `removeAttached` gaat wissen:
 *  altijd de KOPPELING; blijft de knoop in gebruik, dan is dat alles; anders
 *  óók de inkomende realisatielinks en de hele SLUITING.
 *
 *  `sluiting` is `closureQuads` uit de mutatielaag — als parameter, zodat deze
 *  module `model/edit.js` niet hoeft binnen te halen om te kunnen rekenen.
 *  Lege lijst = er valt hier niets los te maken. */
export function losmaakQuads(
  store: Leesstore | null, anker: Anker | null, t0: Term | null,
  sluiting: (store: Leesstore, term: Term) => Quad[],
): Quad[] {
  if (!store || !anker || !t0) return [];
  const koppel = store.getQuads(anker.parent, termVan(anker.pred), t0, null);
  if (!koppel.length) return [];
  if (blijftInGebruik(store, anker, t0)) return koppel;
  return [
    ...koppel,
    ...store.getQuads(null, termVan(REALISATIE), t0, null),
    ...sluiting(store, t0),
  ];
}
