// DE WORTEL VAN DE BEWERKCHUNK — het doel van de ene dynamische import.
//
// Alles wat bewerkt hangt hieronder: de mutatiekern (via `kern.ts`), de
// veldcomponenten, de chrome. Er is precies één weg hierheen — `laadBewerklaag`
// in `ui/app/bewerkstand.tsx` — en dat is wat de lazy-grens een grens maakt.
//
// `laad()` is EXPLICIET en niet een neveneffect van de import, om twee redenen:
// de kern komt zelf via een `await import()` binnen (zie kern.ts, en de reden
// waarom er geen top-level await staat), en de aanroeper moet kunnen weten
// WANNEER de laag klaar is — anders zet hij de bewerkstand aan vóór de haken er
// staan en blijft het scherm één tik lang leeg van affordances.
//
// MOUNTPUNT VOOR DE ANDERE GOLF B-LANES. Wie een bewerkaffordance toevoegt
// (ghosts en stroken op de regels, formulierrijen, de sleepgrepen) registreert
// zijn haak hier, in `zetKaarthaken`, en breidt `Kaarthaken` in `haken.tsx` uit.
// Dat is de enige plek waar de leeskant en de bewerkkant elkaar raken; een
// tweede dynamische import ernaast zou een tweede chunk opleveren en de meting
// van de lazy-grens onbruikbaar maken.
import type { JSX } from 'solid-js';
import { zetKaarthaken } from './haken.jsx';
import type { VeldSpec } from './haken.jsx';
import { koppelKern } from './kern.js';
import { koppelIntegratie as koppelGhosthaken } from './integratie/mount.js';
import { KaartVeld } from './kaartveld.jsx';
import { Chrome } from './chrome.jsx';

export interface GeladenLaag {
  Chrome: () => JSX.Element;
  zetEditMode: (aan: boolean, opties?: { bevestig?: boolean }) => boolean;
  bevestigEditMode: (opties?: { stil?: boolean }) => void;
}

let geladen: GeladenLaag | null = null;

/** Haal de mutatiekern binnen en hang de haken op. Idempotent: een tweede
 *  aanroep levert dezelfde laag terug zonder iets opnieuw te registreren. */
export async function laad(): Promise<GeladenLaag> {
  if (geladen) return geladen;
  const k = await koppelKern();
  zetKaarthaken({
    veld: (spec: VeldSpec, lees: () => JSX.Element) => KaartVeld({ spec, lees }),
  });
  // ÉÉN WORTEL VOOR BEIDE HAKENSETS (verzoening door de fold, 7 sep 2026).
  //
  // Golf B leverde twee mountpunten op: dit (`ui/bewerk/haken.tsx`, de velden)
  // en dat van lane-ghost-integratie (`ui/gedeeld/bewerkhaak.tsx`, de zeven
  // ghost-/strookplekken). Allebei goed ontworpen en allebei leeschunk-veilig,
  // maar samen hadden ze TWEE dynamische importwortels — en dus twee chunkbomen,
  // precies de preload-keten waar deze lane voor waarschuwt.
  //
  // Ze zijn nu één systeem in de zin die telt: één lader (de bevestigflow in
  // `ui/app/bewerkstand.tsx`) en één importwortel (deze module). De integratie
  // van de andere lane wordt hiervandaan opgehaald in plaats van door een eigen
  // effect. De twee signaalmodules blijven bestaan — samenvoegen zou zeven
  // aanroepplekken herschrijven zonder dat er een byte mee verschuift.
  await koppelGhosthaken();
  geladen = {
    Chrome,
    zetEditMode: k.zetEditMode,
    bevestigEditMode: k.bevestigEditMode,
  };
  return geladen;
}

/** Testhaak: de registratie terugdraaien, zodat een volgende test weer met een
 *  kale leesstand begint. */
export function _ontkoppelVoorTest(): void {
  geladen = null;
  zetKaarthaken(null);
}
