// DE INHANGPLEK: hier komt de bewerklaag binnen en vult zij de plekken die de
// leescomponenten openhouden.
//
// Dit is het ENIGE bestand van deze lane dat de mutatiekern en de mutatielaag
// aanraakt, en het doet dat met DYNAMISCHE imports. Die vorm is geen stijl maar
// de lazy-grens zelf (spec §1): deze module wordt op haar beurt dynamisch
// geladen door `ui/gedeeld/bewerkhaak.tsx`, en alles wat zij binnenhaalt komt
// daarmee in de bewerkchunk terecht in plaats van in de instap.
//
// Wat hier verder gebeurt is het bouwen van de `Kern` — de vier randen die de
// componenten nodig hebben en die de mutatiekern niet levert: de ONTGRENDEL-
// route (die kent de bronnenlaag), het BEVESTIGEN, het SPRINGEN en de kale
// graaf om ankers in te zoeken.
import { bronRijen, bewerkbron as huidigeBron, maakBewerkbaar, opfsAan } from '../../../stores/bronbeheer.js';
import { graaf } from '../../../stores/corpus.js';
import { spring } from '../../../stores/weergave.js';
import { koppelBewerkhaken } from '../../gedeeld/bewerkhaak.jsx';
import type { Quad, Term } from '../../../model-grens.js';
import type { Leesstore } from './anker.js';
import type { EditApi, Kern, Ontgrendeldoel } from './kern.js';
import {
  GroepRegelGhost, KaartkopStrook, KaartRegelGhost, NieuwBeleidGhost, OvereenkomstGhost,
} from './kaart-bewerk.jsx';
import {
  CollectieAfbakeningGhost, RegelPlichtGhost, RegelStrook, VoorwaardeGhost, VoorwaardeStrook,
} from './rij-bewerk.jsx';
import { TargetGhost, TargetKruis } from './target-bewerk.jsx';

/** WELKE BRON MOET DE BEWERKBRON WORDEN om dit te kunnen bewerken?
 *
 *  DE MEERDERHEIDSBRON, en NIET "de grootste van de andere" (review I-4). Die
 *  tweede lezing stond hier, en zij komt uit op dezelfde gelockte stand: sinds
 *  het één-bewerkbron-addendum is `bewerkbaar()` een EVERY-toets — álle quads van
 *  de knoop moeten in dé bewerkbron staan. Voor de gewone gelockte kaart (40
 *  quads in de bewerkbron, 2 in een labelbundel) luidde het aanbod dus: maak de
 *  labelbundel de bewerkbron. Daarna staan er 40 quads buiten in plaats van 2,
 *  het icoon is nóg steeds gelockt, en de lezer is zijn schrijfrecht op de
 *  policybron kwijt — mét de opmaakverlies-waarschuwing erbij.
 *
 *  De juiste vraag is: welke bron DRAAGT deze knoop? Draagt de huidige bewerkbron
 *  er al de meeste van, dan is er niets nuttigs aan te bieden en is `null` het
 *  eerlijke antwoord — het icoon gaat dan uit met zijn reden in plaats van een
 *  route te beloven die op hetzelfde slotje uitkomt. De bevroren viewer kende die
 *  wisselsemantiek niet en filterde in `ontgrendelbareBronVoor` (doc.js
 *  r.2927-2937) op de niet-bewerkbare quads.
 *
 *  PUUR EN APART, zodat de keuze los te toetsen is van OPFS, bronbeheer en de
 *  graaf — dat die drie eromheen zaten is de reden dat deze fout zo lang kon
 *  blijven staan (`ontgrendeldoel.test.ts`). */
export function kiesOntgrendelGraph(
  quads: Quad[], huidigeGraph?: string | null,
): string | null {
  const telling = new Map<string, number>();
  for (const q of quads) {
    const naam = q.graph && q.graph.value;
    if (!naam) continue;
    telling.set(naam, (telling.get(naam) || 0) + 1);
  }
  const opGrootte = [...telling.entries()].sort((a, b) => b[1] - a[1]);
  if (!opGrootte.length) return null;
  const [winnaar] = opGrootte[0];
  if (huidigeGraph && winnaar === huidigeGraph) return null;
  return winnaar;
}

/** DE BRON ACHTER EEN GELOCKTE KNOP, als aanbod: naam, waarschuwing en de
 *  handeling die hem de bewerkbron maakt.
 *
 *  `null` zodra ontgrendelen geen optie is: zonder OPFS bestaat de lokale kopie
 *  niet, en een endpoint heeft zijn eigen slotje (met een update-URL) in het
 *  bronnenpaneel dat hier niet na te bootsen valt. */
function ontgrendeldoel(term: Term | null, blokkade?: Quad[] | null): Ontgrendeldoel | null {
  if (!opfsAan()) return null;
  const g = graaf() as unknown as Leesstore | null;
  const quads = (blokkade && blokkade.length)
    ? blokkade
    : (g && term ? g.getQuads(term, null, null, null) : []);
  if (!quads.length) return null;
  const huidig = huidigeBron();
  const winnaar = kiesOntgrendelGraph(quads, huidig ? huidig.graph : null);
  if (!winnaar) return null;
  // Alleen een LOKAAL TE KOPIËREN ttl-bron is aan te bieden; een endpoint heeft
  // zijn eigen slotje in het bronnenpaneel.
  const bron = bronRijen()
    .find((r) => r.graph === winnaar && r.soort === 'ttl' && !r.fromSparql);
  if (!bron) return null;
  return {
    naam: bron.name || bron.url || winnaar,
    huidige: huidig ? (huidig.name || huidig.url || undefined) : undefined,
    // WAARSCHUWEN ZODRA ER EEN KOPIE GESCHREVEN MOET WORDEN, niet "één keer per
    // sessie" (eigenaarsbesluit 9 sep 2026). Die telling bestond omdat de
    // waarschuwing ONDERBRAK — een dialoog met "Doorgaan"/"Annuleren" — en een
    // onderbreking per bron zou onwerkbaar zijn. Sinds de zin in de tooltip van
    // het gelockte icoon staat kost herhaling niets, en is de eerlijke toets
    // gewoon: schrijft deze klik een kopie? Een bron die er al een heeft,
    // verliest niets.
    waarschuw: !bron.opfs,
    maak: () => maakBewerkbaar(bron),
  };
}

/** Haal de kern binnen en hang de plekken in. Idempotent aan de
 *  aanroepkant (`laadBewerklaag` bewaart de promise). */
export async function koppelIntegratie(): Promise<void> {
  const [kernModule, editModule] = await Promise.all([
    import('../../../stores/bewerk.js'),
    import('../../../model/edit.js'),
  ]);
  const kern: Kern = {
    graaf: () => graaf() as unknown as Leesstore | null,
    voerUit: (fn, opties) => kernModule.voerUit(fn as never, opties),
    bewerkbaar: (term) => kernModule.bewerkbaar(term as never),
    quadsInBewerkbron: (quads) => kernModule.quadsInBewerkbron(quads),
    heeftBewerkbron: () => !!huidigeBron(),
    edit: editModule as unknown as EditApi,
    // GEEN `bevestig` MEER (eigenaarsbesluit 8 sep 2026). Hier stond de
    // voorlopige vorm van de bevestigflow: een `window.confirm`, met als
    // motivering "stil verwijderen zou erger zijn dan een systeemdialoog". Dat
    // klopte, maar de derde optie is beter dan allebei: verwijderen en het
    // MELDEN, met de ongedaan-maken-link erbij (`ui/bewerk/toast.tsx`). Stil is
    // het dus niet geworden.
    //
    // EN ER BLIJFT ER GEEN (nagelopen 9 sep 2026). Hier stond dat het VERLATEN
    // van de bewerkstand nog een eigen bevestiging had, "want die gaat over
    // onbewaard werk". Dat klopte niet en klopte nooit: `schakelBewerkstand(false)`
    // in `ui/app/bewerkstand.tsx` zet de stand meteen uit, en onbewaard werk is
    // er niet — `stopBewerken()` in `stores/bronbeheer.ts` duwt eerst de
    // autosave-flush eruit, net als de downloadknop en `beforeunload`. Er valt
    // dus niets te verliezen en dus ook niets te bevestigen. Sinds het
    // eigenaarsbesluit van 9 sep ("make editable doesn't need a confirmation
    // button") is ook de ontgrendel-dialoog weg; deze laag kent geen enkele
    // ja/nee-stap meer. Wat blijft is de WEIGERING met reden: een icoon zonder
    // route gaat uit en zegt waarom.
    spring: (ref) => { void spring(ref); },
    ontgrendeldoel,
  };
  koppelBewerkhaken({
    kaartkop: (ctx) => KaartkopStrook({ kern, ctx }),
    kaartGhost: (ctx) => KaartRegelGhost({ kern, ctx }),
    overeenkomstGhost: (ctx) => OvereenkomstGhost({ kern, ctx }),
    regelStrook: (ctx) => RegelStrook({ kern, ctx }),
    plichtGhost: (ctx) => RegelPlichtGhost({ kern, ctx }),
    groepGhost: (ctx) => GroepRegelGhost({ kern, ctx }),
    targetKruis: (ctx) => TargetKruis({ kern, ctx }),
    targetGhost: (ctx) => TargetGhost({ kern, ctx }),
    voorwaardeStrook: (ctx) => VoorwaardeStrook({ kern, ctx }),
    voorwaardeGhost: (ctx) => VoorwaardeGhost({ kern, ctx }),
    collectieGhost: (ctx) => CollectieAfbakeningGhost({ kern, ctx }),
    nieuwBeleid: (ctx) => NieuwBeleidGhost({ kern, ctx }),
  });
}
