// DE ✎-ROUTE OP EEN KAARTVELD: van de leesnode naar een bewerkbaar veld en
// terug, met de mutatie ertussen.
//
// Gedragsbron: `veldOfTekst`, `titelVeld`, `toelichtVeld` en `iriVeldOfTekst`
// uit het fase C-taak 5-blok van viewer-bevroren/assets/doc.js. De `patroonPoort` uit het
// formulierblok (r.8965) stond hier ook en is bij de fixronde van golf B naar
// zijn levende kopie in `ui/kaart/formulier-bewerk.tsx` teruggebracht — zie de
// noot bij "De bewerkbare vormen" hieronder. De drie regels die in de
// gedragsbron bovenaan staan gelden hier onverkort:
//
//  1. EEN VELD KIJKT NAAR DE GRAPH VAN HET TRIPLE dat het bewerkt, niet naar de
//     hele knoop. Een policy die in de bewerkbron staat maar zijn rdfs:label uit
//     een alleen-lezen labelbundel haalt, is voor zijn dct:title gewoon
//     bewerkbaar en voor dat label niet.
//  2. ELKE SAVE LOOPT VIA `voerUit(..., { groep: true })`: één `zetLiteral`
//     levert al twee delta's (oude waarde eruit, nieuwe erin), en zonder groep
//     zou één undo maar de helft terugdraaien.
//  3. OPSLAAN GEBEURT BIJ ENTER OF BLUR, nooit per toetsaanslag — elke mutatie
//     herbouwt (een deel van) het model. En een save die niets verandert wordt
//     overgeslagen: anders levert het aanklikken van een veld al een undo-stap
//     en een herbouw op.
//
// WAT IN DE VERTALING NAAR SOLID ANDERS IS. De bevroren viewer bouwde per
// render een verse DOM en kon dus alles in closures vangen; hier is de weergave
// reactief en moet elke afgeleide waarde een getter zijn — anders bevriest een
// veld op de bron van het moment waarop het gebouwd werd, en dat is precies het
// geval dat na een bronwissel stil naar de verkeerde graph schrijft.
//
// ÉÉN BEWERKBRON (spec-addendum 6 sep). "Gelockt" heeft daarmee één betekenis —
// dit leeft niet in DE bewerkbron — en één antwoord: hiervan de bewerkbron
// maken. Dat aanbod hangt aan het gedimde ✎ zelf; een veld dat niets te bieden
// heeft (geen bewerkbron, of een knoop die in geen enkele bron leeft) staat er
// gedimd bij met de reden in zijn tooltip. NIETS WORDT VERBORGEN.
import { Show, createEffect, createMemo, createSignal, on } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  addPartyCollection, benoemKnoop, benoemToets, expandIri, hernoemKnoop, hernoemQuads,
  hernoemToets, isPartyCollection, knoopPosities, naamSuggestie, setAction, setIri, termOptions,
} from '../../model/edit.js';
import { curie } from '../../model/parse.js';
import {
  DATUM_STANDAARD, dragendPred, geldigeIriTekst, termVan, zetLiteral,
} from '../../model/velden.js';
import type { Quad, Term } from '../../model-grens.js';
import { graaf, graafVersie } from '../../stores/corpus.js';
import {
  bewerkbron as bronbeheerBewerkbron, bronRijen, maakBewerkbaar,
} from '../../stores/bronbeheer.js';
import type { BronBewerk } from '../../stores/bronbeheer.js';
import { huidigeTaal, tekst, weergave, zetMelding } from '../../stores/weergave.js';
import { bewerkFocus, focusAdres, vraagBewerkFocus, wisFocusVoor } from '../gedeeld/bewerkhaak.jsx';
import type { VeldSpec } from './haken.jsx';
import { kern } from './kern.js';
import { Knop } from './knop.jsx';
import { InlineVeld, IriCombobox, optieTekst } from './veld.jsx';
import type { IriOptie, VeldHaak } from './veld.jsx';
import { ontgrendelUitleg, SlotIcoon } from './strook.jsx';
import { toonToast } from './toast.jsx';
import './bewerk.css';

interface LeesStore {
  getQuads(s: Term | null, p: Term | null, o: Term | null, g: Term | null): Quad[];
}

// DE TERM VAN EEN KNOOP, uit welke vorm de weergave hem ook aanlevert. Zie
// `model/term.js` voor waarom dat meer is dan een cast: een term die uit de
// WORKER komt, is structured-cloned en draagt alleen nog zijn `id`. Een cast
// maakt daar een object van dat er getypeerd goed uitziet en waarop `getQuads`
// stil nul quads teruggeeft — en precies zo'n cast (`nn`) stond hier, in een
// tweede exemplaar in `ui/kaart/formulier-bewerk.tsx` (eindreview I-2). Wat
// blijft is de GETYPEERDE GRENS naar de JavaScript-modellaag, één keer.
const alsTerm = (t: unknown): Term | null => termVan(t) as Term | null;

// DE OPTIELIJSTEN VAN DE COMBOBOXEN. `termOptions` bouwt bij elke aanroep
// nieuwe arrays en scant de hele graaf; op registerschaal is dat per veld
// onbetaalbaar. Eén cache op (graaf, graafversie) betekent: één scan per
// mutatie, gedeeld door alle velden — dezelfde afweging als `veldOptieCache` in
// de bevroren viewer, alleen met de versie als vervaldatum in plaats van de
// render. Lui: buiten de bewerkstand wordt hij nooit aangeraakt.
let optieCache: { g: unknown; v: number; opties: Record<string, IriOptie[]> } | null = null;

/** GEDEELD MET DE SLOTEDITOR (`integratie/sloteditor.tsx`). Hij bouwt dezelfde
 *  comboboxen uit dezelfde categorieën, en een tweede cache ernaast zou de graaf
 *  per mutatie twee keer scannen — precies de dubbeling die de eindreview op
 *  `optieTekst` en `termVan` aanwees. Eén cache, twee afnemers. */
export function veldOpties(categorie: string): IriOptie[] {
  const g = graaf();
  const v = graafVersie();
  if (!g) return [];
  if (!optieCache || optieCache.g !== g || optieCache.v !== v) {
    optieCache = { g, v, opties: termOptions(g) as Record<string, IriOptie[]> };
  }
  return optieCache.opties[categorie] || [];
}

// --- De grens van één veld ---------------------------------------------------

type Stand =
  | { soort: 'aan' }
  /** Niet in de bewerkbron, maar er is een route: deze bron de bewerkbron
   *  maken. `bron` is de bron die het veld bezit. */
  | { soort: 'gelockt'; bron: BronBewerk }
  /** Niets te schakelen. `reden` zegt wat er aan de hand is. */
  | { soort: 'uit'; reden: string };

/** De bron waar deze graph bij hoort, als die in de bronnenlijst staat. */
function bronVanGraph(graph: string): BronBewerk | null {
  if (!graph) return null;
  return bronRijen().find((b) => b.graph === graph && !b.fromSparql) || null;
}

/** DE GRENS VAN ÉÉN VELD, in de vorm van fase C maar met één bewerkbron:
 *
 *   - het veld BESTAAT: álle triples (subject, pred) moeten in de bewerkbron
 *     staan. Staat er één elders, dan zou een wijziging die waarde laten staan
 *     en er een tweede naast zetten;
 *   - het veld bestaat NIET (het add-geval): bewerkbaar zodra de KNOOP in de
 *     bewerkbron leeft. Bewust niet "zodra er een bewerkbron is": dan zou een
 *     kaart die volledig uit een andere bron komt alsnog ✎'s krijgen voor al
 *     haar lege velden, en zou de eerste save die knoop over twee bronnen
 *     verdelen. */
export function veldStand(term: unknown, pred: string): Stand {
  const bron = kern().bewerkbron();
  if (!bron) return { soort: 'uit', reden: tekst('edit.geenBewerkbron') };
  const g = graaf() as unknown as LeesStore | null;
  const t = alsTerm(term);
  if (!g || !t || !pred) return { soort: 'uit', reden: tekst('edit.veldGeenPad') };
  const eigen = g.getQuads(t, alsTerm(pred), null, null);
  if (eigen.length) {
    if (kern().quadsInBewerkbron(eigen)) return { soort: 'aan' };
    const anders = bronVanGraph(((eigen[0].graph || {}) as { value?: string }).value || '');
    return anders ? { soort: 'gelockt', bron: anders }
      : { soort: 'uit', reden: tekst('edit.geenBewerkbron') };
  }
  // Het ADD-geval: leeft deze knoop in de bewerkbron?
  const knoop = g.getQuads(t, null, null, null);
  if (!knoop.length) return { soort: 'uit', reden: tekst('edit.kaartAfgeleid') };
  const inBron = knoop.some((q) => ((q.graph || {}) as { value?: string }).value === bron.graph);
  if (inBron) return { soort: 'aan' };
  const anders = bronVanGraph(((knoop[0].graph || {}) as { value?: string }).value || '');
  return anders ? { soort: 'gelockt', bron: anders }
    : { soort: 'uit', reden: tekst('edit.geenBewerkbron') };
}

// --- De gedimde vorm ---------------------------------------------------------

/** Het GEDIMDE ✎ naast een veld dat hier niet te bewerken is. Twee vormen, met
 *  precies het onderscheid dat `actieStand` in de strook maakt: een gelockt
 *  veld doet nog iets (het biedt de route naar de bewerkbron aan) en krijgt dus
 *  géén `aria-disabled` — een hulpmiddel dat "uitgeschakeld" voorleest houdt de
 *  gebruiker weg van de enige route die er is. Een veld dat niets te bieden
 *  heeft is wél disabled, met zijn reden in de tooltip. */
function GedimdVeld(props: {
  stand: Stand; lees: () => JSX.Element; zonderPotlood?: boolean;
}): JSX.Element {
  const gelockt = () => (props.stand.soort === 'gelockt' ? props.stand.bron : null);
  const huidig = () => {
    const b = bronbeheerBewerkbron();
    return b ? (b.name || b.url || '') : '';
  };
  // ÉÉN KLIK, MET DE UITLEG ERVOOR (eigenaarsbesluit 9 sep 2026: "make editable
  // doesn't need a confirmation button"). Tot die datum opende dit ✎ een
  // ontgrendel-doos met "Maak dit de bewerkbron" / "Annuleren"; nu ontgrendelt de
  // klik meteen, en de drie zinnen die in die doos stonden staan in de tooltip —
  // zie `ontgrendelUitleg` in `strook.tsx`. Wat er ná de klik gebeurt meldt de
  // bronnenlaag zelf op de statusregel (`src.lokaalGemaakt`).
  const titel = () => {
    const b = gelockt();
    if (!b) return (props.stand as { reden: string }).reden;
    return [tekst('edit.nietBewerkbron'), ontgrendelUitleg({
      naam: b.name || b.url || b.graph,
      huidige: huidig() || undefined,
      waarschuw: !b.opfs,
    })].join(' ');
  };
  const ontgrendel = () => {
    const b = gelockt();
    if (b) void maakBewerkbaar(b).catch(() => {});
  };
  return (
    <span class="inline-veld inline-veld-gelockt">
      {props.lees()}
      <Show when={!props.zonderPotlood}>
        <span
          class={gelockt() ? 'edit-knop inline-veld-edit gelockt' : 'edit-knop inline-veld-edit actie-uit'}
          role="button"
          tabindex="0"
          title={titel()}
          aria-label={titel()}
          aria-disabled={gelockt() ? undefined : 'true'}
          on:click={(e: MouseEvent) => {
            if (!gelockt()) return;
            e.preventDefault();
            e.stopPropagation();
            ontgrendel();
          }}
          on:keydown={(e: KeyboardEvent) => {
            if (!gelockt() || (e.key !== 'Enter' && e.key !== ' ')) return;
            e.preventDefault();
            e.stopPropagation();
            ontgrendel();
          }}
        >
          ✎
          <SlotIcoon />
        </span>
      </Show>
    </span>
  );
}

// --- De bewerkbare vormen ----------------------------------------------------

// GEEN PATROONPOORT MEER IN DIT BESTAND (review I-5). Hier stonden een eigen
// `patroonPoort` en twee takken die hem aanriepen, gebouwd uit hetzelfde
// doc.js-blok (r.8940-8970) als de poort in `ui/kaart/formulier-bewerk.tsx`.
// Twee implementaties van één SHACL-regel is de vorm die over een half jaar uit
// elkaar loopt, en deze was bovendien de dode helft: NIEMAND vult ooit
// `VeldSpec.patroon` — beide takken waren onbereikbaar en er stond geen enkele
// test op. De levende, in beide takken getoetste vorm is die van
// lane-formulieren (`formulier-bewerk.test.tsx`, "sh:pattern toetst OOK de
// IRI-tak"); zij deelt sinds deze ronde `voldoetAanPatroon` met de modellaag.
//
// Komt er ooit een kaartrij MET een shape-patroon, dan is dit terug te zetten
// met wat het altijd al had moeten zijn: `patroonPoort` uit formulier-bewerk,
// een producent voor het veld, en een test per tak.

/** HET FOCUSVERZOEK VAN EEN NIEUW ELEMENT, ingelost door het veld dat zich op dat
 *  adres herkent. Eén helper voor beide veldsoorten: het verzoek zegt WELKE knoop
 *  de cursor krijgt, niet welke widget eromheen staat.
 *
 *  `on(...)` en geen kale effect: een effect dat zijn eigen bron schrijft zou
 *  zichzelf blijven wekken. `on` volgt alleen het signaal.
 *
 *  WIE WIST HET VERZOEK, EN WANNEER — bijgesteld op 9 sep 2026, gemeten in de
 *  gebouwde app op de nieuwe "+ groep"-route.
 *
 *  Hier stond: "het verzoek wordt gewist ZODRA een veld het aanneemt — ook als
 *  het openen niets oplevert", met als reden dat een blijvend verzoek bij de
 *  volgende herbouw een veld heropent dat de lezer net had gesloten. Die reden
 *  klopt; de UITVOERING liep stuk op een geval dat de bestaande routes niet
 *  hebben. Na een mint wordt de kaartrij NIET één keer maar VIER keer opnieuw
 *  opgebouwd (model-herbouw, graafversie, bron-sync, melding); gemeten op de
 *  verse groep: vier `TekstVeld`-instanties op hetzelfde adres. Het verzoek werd
 *  aangenomen door instantie 2, die daarna werd weggegooid — `setOpen(true)`
 *  landde op een component die nooit in de DOM kwam (gemeten: `open` ging naar
 *  `true`, `.inline-veld-invoer` bleef 0), en de instantie die WÉL bleef staan
 *  vond een leeg verzoek.
 *
 *  Daarom wist niet de AANNAME het verzoek maar het OPENEN: `onOpen` van
 *  `InlineVeld` vuurt vanuit `onMount` van het invoerveld, dus precies wanneer de
 *  cursor er echt in staat. Elke instantie op dat adres opent zichzelf; degene
 *  die het overleeft ruimt het verzoek op. Dat is strikt beter dan de oude vorm:
 *  ook daar verdween het verzoek na de eerste échte opening, en de heropen-val
 *  die de oude noot beschrijft blijft daarmee dicht.
 *
 *  DE IRI-TAK LIEP HIER TOT 10 SEP 2026 LANGS EEN EIGEN WISPOLICY (`wisMeteen`):
 *  een combobox staat altijd al open, dus "zij heeft geen mount-moment om op te
 *  wachten — daar is de aanname het enige aangrijpingspunt". Dat tweede was
 *  onwaar. Een combobox heeft wél een aangrijpingspunt, alleen geen mount: de
 *  vraag of haar invoerveld ná het focussen ook echt de cursor draagt. Wissen
 *  bij de AANNAME is precies de fout die deze noot hierboven beschrijft, één
 *  laag hoger — en zij faalt stil. Zie `wisFocusVoor` in `ui/gedeeld/
 *  bewerkhaak.tsx`: er is nog één wispolicy, en dit is hem. */
function neemFocusAan(spec: VeldSpec, api: () => VeldHaak | null): void {
  createEffect(on(bewerkFocus, (adres) => {
    if (!adres || !spec.focusSleutel || adres !== spec.focusSleutel) return;
    api()?.openBewerk();
  }));
}

/** Het verzoek is ingelost: dit veld staat écht open, en de cursor staat erin. */
function meldGeopend(spec: VeldSpec): void {
  if (spec.focusSleutel) wisFocusVoor(spec.focusSleutel);
}

/** DRAAGT DE GRAAF ZELF EEN WAARDE OP (term, pred)? Dezelfde vraag die
 *  `veldStand` hierboven stelt om het add-geval te herkennen — hier voor een
 *  ander doel, en daarom apart: `veldStand` beslist of het veld BEWERKBAAR is,
 *  deze functie wat er ALS STARTWAARDE in staat. */
function draagtWaarde(term: unknown, pred: string): boolean {
  const g = graaf() as unknown as LeesStore | null;
  const t = alsTerm(term);
  if (!g || !t || !pred) return false;
  return g.getQuads(t, alsTerm(pred), null, null).length > 0;
}

function TekstVeld(props: {
  spec: VeldSpec; pred: () => string; lees: () => JSX.Element;
}): JSX.Element {
  // DE STARTWAARDE VAN EEN VELD MET EEN HINT IS WAT DE GRAAF DRAAGT — niet wat
  // de weergave toont (eigenaarsbevinding 9 sep 2026, tweede ronde).
  //
  // `spec.waarde` is met opzet de GETOONDE naam: een regel heet naar haar actie
  // ("Toestemming"), een naamloze kaart naar haar localName ("aanbod"), een
  // collectie naar haar curie. Dat is prettig lezen, maar het is een AFLEIDING,
  // en als startwaarde van een invoerveld is zij precies de fout die de
  // eigenaar tweemaal meldde: er staat tekst in het veld die niemand typte, en
  // een `placeholder` is onzichtbaar zolang er een waarde staat.
  //
  // De poort staat op `spec.hint` en niet op alle velden, en dat is een keuze:
  // een veld dat zijn hint kent, kan een leeg veld ook UITLEGGEN. Velden zonder
  // hint (de naam-tag van een doelobject, een collectie) houden hun oude gedrag
  // — daar zou een leeg veld zonder uitleg alleen maar minder zeggen.
  //
  // `graafVersie()` meelezen houdt hem reactief: na een save draagt de graaf de
  // waarde wél, en dan moet de gesloten stand hem tonen.
  const eigen = () => {
    void graafVersie();
    return draagtWaarde(props.spec.term, props.pred());
  };
  const oud = () => (props.spec.hint && !eigen() ? '' : (props.spec.waarde ?? ''));
  // WAT DE GESLOTEN STAND TOONT als het veld leeg is: de LEESVORM als de
  // weergave een afgeleide naam heeft ("Toestemming", "aanbod"), en anders
  // niets — dan valt `InlineVeld` terug op zijn gedempte hint.
  const leeg = () => (props.spec.waarde ? props.lees : undefined);
  let haak: VeldHaak | null = null;
  neemFocusAan(props.spec, () => haak);
  // De STANDAARDVORM van een veld dat er nog niet is: een datum krijgt
  // xsd:date, tekst krijgt de taal waarin de gebruiker op dit moment zit te
  // typen. Staat er al een waarde, dan wint haar vorm (zie zetLiteral).
  const standaard = () => (props.spec.soort === 'datum'
    ? DATUM_STANDAARD : { lang: huidigeTaal() });
  const bewaar = (v: string) => {
    // Niets veranderd = niets doen. Een blur op een veld dat de lezer alleen
    // maar aanklikte zou anders een herbouw én een undo-stap opleveren — en bij
    // een AFGELEIDE waarde (een titel die de weergave zelf samenstelt) zelfs
    // een triple materialiseren die er niet stond.
    if (String(v) === oud()) return;
    void kern().voerUit(
      // TWEE KEER `f`: de canonieke `zetLiteral` (model/edit.js) neemt de
      // leesgraaf apart, omdat een schrijf-facade niet vanzelfsprekend
      // doorleest. De onze doet dat wel — `bewerkStore` leest ongefilterd naar
      // de graaf door — dus lezen en schrijven gaan langs dezelfde ingang. De
      // knoop wordt daar genormaliseerd (worker-handles, zie `nn()` in edit.js).
      (f) => zetLiteral(f, f, props.spec.term, props.pred(), v, standaard()),
      { groep: true },
    );
  };
  return (
    <InlineVeld
      waarde={oud()}
      meerregelig={props.spec.meerregelig}
      type={props.spec.soort === 'datum' ? 'date' : 'text'}
      hint={props.spec.hint}
      leeg={leeg()}
      zonderPotlood={props.spec.zonderPotlood}
      onSave={bewaar}
      // HET VERZOEK IS PAS INGELOST ALS HET INVOERVELD ER ÉCHT STAAT — zie
      // `neemFocusAan` hierboven voor de vier instanties die dat aantoonden.
      onOpen={() => meldGeopend(props.spec)}
      haak={(api) => { haak = api; }}
    />
  );
}

/** DE KNOOP DIE DIT VELD OP DIT MOMENT AANWIJST, uit de GRAAF en niet uit de
 *  weergave.
 *
 *  `spec.iri` is wat de leeskant van de waarde weet, en dat is niet altijd een
 *  IRI: voor een anonieme partij vult het model daar de blank-node-naam in
 *  (`n3-2`). Als string ziet dat er uit als een IRI, en `nn()` maakt er dus een
 *  NamedNode van — een knoop die in de graaf niet bestaat. Elke vraag die je op
 *  `spec.iri` stelt, valt bij een blanke waarde dus stil naar "nee".
 *
 *  Het object van (subject, predicaat) heeft dat probleem niet: het IS de knoop,
 *  in de vorm die de graaf zelf draagt. Alleen bij precies één waarde — bij meer
 *  is er geen "de" waarde — en anders alsnog `spec.iri`, want een veld dat zijn
 *  eigen triple niet in de graaf vindt (de add-stand) heeft niets beters. */
function waardeKnoop(spec: VeldSpec, pred: string): Term | string | null {
  const g = graaf() as unknown as LeesStore | null;
  const t = alsTerm(spec.term);
  const eigen = (g && t && pred) ? g.getQuads(t, alsTerm(pred), null, null) : [];
  if (eigen.length === 1) return eigen[0].object as Term;
  return spec.iri || null;
}

/** IS DE HUIDIGE WAARDE VAN DIT PARTIJVELD AL EEN GROEP? Twee plekken lezen het
 *  antwoord — het veld (om de kaart van die groep te blijven tonen) en de knop
 *  (om uit te gaan met zijn reden) — dus staat het één keer.
 *
 *  DE VRAAG STAAT OP DE KNOOP EN NIET MEER OP `spec.iri` (opruimpunt 18, 10 sep
 *  2026). `partijVeld` wikkelt de hele `<Ref>` — bij een collectie is dat een
 *  KAART met haar soortchip, haar leden en haar sectie "Afbakening" — als
 *  leesnode in een IRI-veld, en `KaartVeld` geeft die leesnode alleen door aan de
 *  tak hieronder. Stond de toets op `spec.iri`, dan viel een BLANKE
 *  partij-collectie erbuiten: `isPartyCollection(graaf(), null)` is `false`, dus
 *  de kaart van die groep verdween achter de combobox en haar afbakening was
 *  onbereikbaar. Blank is geen randgeval — `addPartyCollection` mint een blanke
 *  groep zodra het subject zelf geen IRI heeft, en een bron mag er gewoon een
 *  bevatten (`odrl:assignee [ a odrl:PartyCollection ; odrl:refinement … ]`).
 *
 *  De graafversie meelezen houdt hem reactief: ná de mint IS deze partij een
 *  groep, en beide plekken horen dat meteen te weten. */
function isGroepWaarde(spec: VeldSpec, pred: string): boolean {
  void graafVersie();
  return !!spec.nieuweGroep && !!isPartyCollection(graaf(), waardeKnoop(spec, pred));
}

function IriVeld(props: {
  spec: VeldSpec; pred: () => string; lees: () => JSX.Element;
}): JSX.Element {
  const opties = createMemo(() => veldOpties(props.spec.categorie || 'labeled'));
  let haak: VeldHaak | null = null;
  neemFocusAan(props.spec, () => haak);
  // DE STARTWAARDE VAN EEN IRI-VELD WAARVAN DE WEERGAVE ALLEEN HET LABEL KENT.
  //
  // Het gewone geval is `spec.iri`. Maar niet elke leesvorm draagt de IRI: de
  // ACTIE van een verplichting komt uit `readDuty` als kaal label — daar staat
  // `action: 'Informeren'` en geen `{iri, label}` zoals bij een toestemming. Met
  // alleen `spec.iri` zou dat veld dan LEEG opengaan naast een rij die "Informeren"
  // zegt, en dat is precies het "niet editable" van de melding: een veld dat de
  // waarde niet toont, kan hem ook niet houden.
  //
  // Het label is een geldige startwaarde omdat de RESOLUTIE hem terugleest: een
  // exacte labelmatch wint in `IriCombobox` (dat is ook wat er in het veld staat
  // na een keuze uit de datalist). `beginIri` doet diezelfde resolutie hier, zodat
  // een ongewijzigde waarde geen mutatie en dus geen undo-stap oplevert.
  const beginTekst = () => optieTekst(opties(), props.spec.iri) || (props.spec.waarde ?? '');
  const beginIri = (): string => {
    if (props.spec.iri) return props.spec.iri;
    const l = props.spec.waarde ?? '';
    const o = l ? opties().find((x) => x.label === l) : null;
    return o ? o.iri : '';
  };
  let vorige = beginIri();
  const kiesIri = (iri: string) => {
    // Een LEEG veld is een geldige bewerking (de eigenschap weghalen); alles
    // wat er wél staat moet een bruikbare IRI opleveren. Zo niet: melden en de
    // invoer laten staan zoals de gebruiker hem typte — niets gemuteerd.
    if (iri && !geldigeIriTekst(iri)) {
      zetMelding('edit.ongeldigeIri', { invoer: iri });
      return;
    }
    // ONGEWIJZIGD komt er altijd doorheen: een waarde die er al stond mag geen
    // klacht opleveren omdat de gebruiker het veld even aanraakte.
    if (iri === vorige) return;
    vorige = iri;
    // GENORMALISEERD, om dezelfde reden als bij `zetLiteral`: `setIri` in
    // edit.js maakt met `nn()` alleen van een string een term, en de knoop kan
    // als worker-handle binnenkomen.
    const doel = alsTerm(props.spec.term);
    // DE ACTIE VAN EEN REGEL IS GEEN KALE (term, pred)-waarde (eis 3 van het
    // eigenaarsbesluit 8 sep 2026). In de ODRL-AP-NL-vorm hangt zij als
    // `[ rdf:value <actie> ]` aan de regel, mét de doelbindings-refinement en de
    // andere parameters aan diezelfde blanke knoop. `setIri` zou dat hele
    // knoopje vervangen door een directe IRI en die refinements laten vallen;
    // `setAction` schrijft in de bestaande structuur. Zie `VeldSpec.vorm`.
    void kern().voerUit(
      (f) => (props.spec.vorm === 'actie'
        ? setAction(f, doel, iri) : setIri(f, doel, props.pred(), iri)),
      { groep: true },
    );
  };
  return (
    <>
      <IriCombobox
        options={opties()}
        value={beginTekst()}
        // DE HINT VAN EEN LEEG VELD staat in het `placeholder`-attribuut en niet
        // in de data (eigenaarsbevinding 9 sep 2026). Draagt de spec er geen, dan
        // valt de combobox terug op haar eigen algemene hint.
        placeholder={props.spec.hint || undefined}
        onPick={kiesIri}
        // HET VERZOEK IS PAS INGELOST ALS DE CURSOR ER ÉCHT IN STAAT — dezelfde
        // regel als bij `TekstVeld`, en sinds opruimpunt 22 dezelfde policy.
        onOpen={() => meldGeopend(props.spec)}
        haak={(api) => { haak = api; }}
      />
      <Show when={props.spec.nieuweGroep}>
        <NieuweGroepKnop spec={props.spec} pred={props.pred} />
      </Show>
      {/* EEN GROEP IS MEER DAN EEN IRI, en daarom houdt zij haar LEESVORM naast
          het veld dat haar aanwijst.
          Een IRI-veld vervangt in de bewerkstand de leesnode: er staat één
          waarde, en de combobox toont hem al. Voor een gewone partij klopt dat.
          Voor een `odrl:PartyCollection` niet — haar leesvorm is een KAART (de
          soortchip, haar naam, haar leden en de sectie "Afbakening"), en precies
          daar zit alles wat de eigenaar zocht: "een PartyCollection met
          refinements". Zonder deze regel mint de knop hierboven een groep die
          daarna nergens te zien is, en dus ook niet af te bakenen.
          ALLEEN BIJ EEN GROEP, niet bij elke partij: de kaart van een gewone
          partij is één naam, en die twee keer tonen (in het veld én eronder) is
          ruis. */}
      <Show when={isGroepWaarde(props.spec, props.pred())}>{props.lees()}</Show>
    </>
  );
}

/** "+ groep" NAAST DE IRI-INVOER: de tweede route van een partijveld.
 *
 *  EIGENAARSBEVINDING 9 SEP 2026, letterlijk: "Als hij er wel een heeft is een
 *  PartyCollection met refinements ook niet aan te maken." Een afnemer hoeft
 *  geen enkele partij te zijn — het profielspoor staat een `odrl:PartyCollection`
 *  met een afbakening toe, de leeskant toont die groep al met haar
 *  "Afbakening"-sectie, en de collectiekaart is bewerkbaar. Wat ontbrak was de
 *  stap ervóór: zo'n groep kon alleen ontstaan door hem in de bron te typen.
 *
 *  DRIE DINGEN IN ÉÉN KLIK, in één mutatiegroep en dus één undo-stap
 *  (`addPartyCollection` in model/edit.js doet ze samen): de groep ontstaat, hij
 *  wordt hier gekoppeld, en een partij die er al stond wordt zijn eerste lid. Dat
 *  laatste is de tweede helft van de bevinding: de knop UITZETTEN zodra er een
 *  afnemer staat zou precies het genoemde geval onopgelost laten, en hem
 *  stilzwijgend vervangen zou een uitspraak weggooien die iemand deed.
 *
 *  EN DAARNA DE CURSOR IN DE NIEUWE GROEP. Hetzelfde focusverzoek als bij elke
 *  andere toevoeging (`vraagFocusOp` in de integratielaag, eis 2 van het
 *  eigenaarsbesluit 8 sep 2026): het adres van de verse knoop gaat het signaal
 *  in, en het naamveld van de collectiekaart herkent zich erin en opent zich —
 *  zonder sprong, want de kaart staat al in beeld. De afbakening staat er dan
 *  onder, met haar eigen ghost.
 *
 *  IS DE PARTIJ AL EEN GROEP, dan gaat de knop UIT met zijn reden en verdwijnt
 *  hij niet: een groep om een groep heen is geen antwoord op "ik wil deze
 *  afnemer afbakenen" — die afbakening hoort aan de bestaande groep, en die
 *  route staat twee regels lager op de kaart zelf. Dezelfde regel als in de
 *  actiestrook: niets wordt verborgen, een affordance draagt zijn reden. */
function NieuweGroepKnop(props: { spec: VeldSpec; pred: () => string }): JSX.Element {
  const alGroep = () => isGroepWaarde(props.spec, props.pred());
  const titel = () => tekst(alGroep() ? 'edit.groepAlGroep' : 'edit.groepToevoegen');
  const maak = () => {
    if (alGroep()) return;
    let nieuw: unknown = null;
    void kern().voerUit(
      (f) => { nieuw = addPartyCollection(f, alsTerm(props.spec.term), props.pred()); },
      { groep: true },
    )
      .then((ok) => {
        if (!ok) return;
        toonToast('edit.groepGemaakt');
        vraagBewerkFocus(focusAdres(nieuw));
      })
      .catch(() => {});
  };
  return (
    <Knop
      label={tekst('edit.groepKnop')}
      cls={alGroep() ? 'groep-knop actie-uit' : 'groep-knop'}
      titel={titel()}
      ariaLabel={titel()}
      onClick={maak}
    />
  );
}

// --- De IRI van de knoop zelf ------------------------------------------------

/** DE STAND VAN EEN HERNOEMING. Anders dan bij een gewoon veld gaat het niet om
 *  één (subject, predicaat)-paar maar om ÁLLE triples waarin de knoop voorkomt —
 *  als subject én als verwijzing van buiten. Staat er één van buiten de
 *  bewerkbron, dan is de hernoeming niet uit te voeren zonder een dangling
 *  verwijzing achter te laten, en dan gaat het veld op slot met díe bron als
 *  ontgrendelroute. Dezelfde vorm als het ✕ van de kaartstrook, dat om precies
 *  dezelfde reden op `policyWisQuads` toetst. */
export function knoopIriStand(term: unknown): Stand {
  const bron = kern().bewerkbron();
  if (!bron) return { soort: 'uit', reden: tekst('edit.geenBewerkbron') };
  const g = graaf() as unknown as LeesStore | null;
  const t = alsTerm(term);
  // EEN BLANKE KNOOP HOORT ER SINDS 9 SEP 2026 BIJ (eigenaarsrichting: "En hoe
  // we bestaande nodes kunnen 'namen' natuurlijk"). Hier stond dat hij geen IRI
  // HEEFT en het veld dus uit ging met die reden — waar en onbruikbaar tegelijk:
  // de enige route naar een herbruikbare knoop is hem een naam GEVEN, en dat
  // veld stond juist uit. De stand is verder identiek: het gaat om álle posities
  // van de knoop, en die moeten allemaal in de bewerkbron staan. Wat overblijft
  // voor `edit.iriGeenKnoop` is het geval zonder aanwijsbare knoop (een literal,
  // een weergave-constructie zonder term).
  if (!g || !t || (t.termType !== 'NamedNode' && t.termType !== 'BlankNode')) {
    return { soort: 'uit', reden: tekst('edit.iriGeenKnoop') };
  }
  const raakt = t.termType === 'NamedNode'
    ? hernoemQuads(g, t.value) : knoopPosities(g, t);
  if (!raakt.length) return { soort: 'uit', reden: tekst('edit.kaartAfgeleid') };
  if (kern().quadsInBewerkbron(raakt as never)) return { soort: 'aan' };
  const anders = bronVanGraph(((raakt[0].graph || {}) as { value?: string }).value || '');
  return anders ? { soort: 'gelockt', bron: anders }
    : { soort: 'uit', reden: tekst('edit.geenBewerkbron') };
}

/** HET IRI-VELD VAN DE KNOOP: de node-id als gewone inline bewerking.
 *
 *  WAT ER GETOOND WORDT is de CURIE als die terugleest naar dezelfde IRI, en
 *  anders de volle IRI. Dat is geen cosmetica maar een eerlijkheidsregel: een
 *  veld dat `ex:aanbod` toont terwijl `expandIri('ex:aanbod')` iets anders
 *  oplevert, zou bij een ongewijzigde save de knoop stilzwijgend verplaatsen.
 *
 *  DE SAVE weigert drie dingen met een eigen melding — een ongeldige IRI, een
 *  botsing met een bestaande knoop, en een knoop die de graaf niet kent — en dat
 *  zijn precies de drie redenen die `hernoemKnoop` teruggeeft. Slaagt hij, dan
 *  meldt de toast hoeveel triples er zijn meeverhuisd; dat getal is het bewijs
 *  dat er niet half hernoemd is.
 *
 *  DE GELOCKTE STAND HOORT ERBIJ, en dat is de fixronde-correctie (review 9 sep
 *  2026). De gedimde vorm liep hier langs de gewone `KaartVeld`-terugval, en die
 *  rendert `props.lees()` — dat is bij dit veld een LEEG kind, want de kaartkop
 *  draagt in de leesstand met opzet geen IRI. Uitkomst: een kale ✎ zonder tekst
 *  en zonder de `.kaart-iri`-schil, terwijl elk ander gelockt veld zijn WAARDE
 *  toont met het slotje ernaast. Dat is precies de ongelijkheid die de
 *  strookregel ("niets wordt verborgen, een icoon draagt zijn reden") wil
 *  vermijden — en erger: de lezer zag dan niet eens welke node-id op slot stond.
 *
 *  Daarom bouwt deze component BEIDE standen, met dezelfde schil eromheen: de
 *  IRI staat er altijd, en alleen de bewerkroute verschilt. */
function KnoopIriVeld(props: { spec: VeldSpec; stand: Stand }): JSX.Element {
  const huidig = () => String(props.spec.iri || '');
  const toon = () => {
    const c = curie(huidig()) as string | null;
    return c && expandIri(c) === huidig() ? c : huidig();
  };
  // IS DIT EEN BLANKE KNOOP — de PROMOTIE-tak (eigenaarsrichting 9 sep 2026)?
  // De vraag staat op de TERM en niet op "is `spec.iri` leeg": een kaart zonder
  // IRI die ook geen term draagt is een weergave-constructie, en die krijgt via
  // `knoopIriStand` de uit-stand met haar eigen reden.
  const blank = () => {
    void graafVersie();
    return alsTerm(props.spec.term)?.termType === 'BlankNode';
  };
  // HET VOORSTEL VOOR DE NAAM, afgeleid van het omliggende beleid
  // (`naamSuggestie` in model/edit.js — dezelfde IRI-hiërarchie die `groepBasis`
  // gebruikt). Hij staat in het OPEN veld als startwaarde en NIET in de gesloten
  // stand: de gesloten stand toont "Geef een naam (IRI)", want in de data staat
  // niets. Dat onderscheid is de eigenaarsregel van 9 sep ("subtle hints die
  // verdwijnen als je begint te typen") — met één afwijking die er bewust is:
  // wie op deze affordance klikt, VRAAGT om een naam, en dan is een ingevuld
  // voorstel het antwoord op die klik en geen tekst die niemand typte. Er wordt
  // pas iets geschreven bij Enter of blur, en dat is één undo-stap.
  const voorstel = () => {
    void graafVersie();
    return (naamSuggestie(graaf(), props.spec.term) as string) || '';
  };
  const bewaar = (v: string) => {
    const nieuw = expandIri(String(v || '').trim()) as string;
    if (!nieuw || nieuw === huidig()) return;
    // EERST HET OORDEEL, OP DE LEESGRAAF. Zonder deze toets vooraf zou elke
    // afgewezen poging alsnog een (lege) mutatiegroep openen, en dus een ↶ die
    // niets terugdraait. `hernoemToets`/`benoemToets` raken geen quad aan.
    const isBlank = blank();
    const oordeel = (isBlank
      ? benoemToets(graaf(), props.spec.term, nieuw)
      : hernoemToets(graaf(), huidig(), nieuw)) as { ok: boolean; reden?: string };
    if (!oordeel.ok) {
      zetMelding(oordeel.reden === 'bezet' ? 'edit.iriBezet' : 'edit.ongeldigeIri',
        { invoer: v });
      return;
    }
    void kern().voerUit((f) => (isBlank
      ? benoemKnoop(f, props.spec.term, nieuw)
      : hernoemKnoop(f, huidig(), nieuw)), { groep: true })
      .then((ok) => { if (ok) toonToast(isBlank ? 'edit.knoopBenoemd' : 'edit.knoopHernoemd'); })
      .catch(() => {});
  };
  // DE LEESVORM VAN DE NODE-ID, gedeeld door beide standen. Hij draagt dezelfde
  // klasse als de waarde van een gewoon inline veld, zodat een gelockte node-id
  // er precies zo uitziet als een gelockte titel. Een BLANKE knoop heeft geen
  // waarde om te tonen; daar staat de uitnodiging, gedempt zoals elke hint.
  const leesvorm = () => (blank()
    ? <span class="inline-veld-hint">{tekst('edit.iriGeefNaam')}</span>
    : <span class="inline-veld-waarde">{toon()}</span>);
  return (
    <span
      class={blank() ? 'kaart-iri kaart-iri-blank' : 'kaart-iri mono'}
      title={blank() ? tekst('edit.iriGeefNaamUitleg') : undefined}
    >
      <Show
        when={props.stand.soort === 'aan'}
        fallback={<GedimdVeld stand={props.stand} lees={leesvorm} />}
      >
        <InlineVeld
          waarde={blank() ? '' : toon()}
          hint={blank() ? tekst('edit.iriGeefNaam') : undefined}
          startWaarde={blank() ? voorstel() : undefined}
          onSave={bewaar}
        />
      </Show>
    </span>
  );
}

/** DE HAAK die `ui/bewerk/haken.tsx` aan de leeskant aanbiedt. In de kijkstand
 *  levert hij letterlijk de leesnode: de weergave van deeltraject 2 blijft
 *  ongemoeid zolang de bewerkstand uit staat. */
export function KaartVeld(props: { spec: VeldSpec; lees: () => JSX.Element }): JSX.Element {
  const pred = () => dragendPred(graaf(), props.spec.term, [...props.spec.preds]);
  const knoopIri = () => props.spec.vorm === 'knoopIri';
  const stand = (): Stand => {
    // De aanroeper weet het al: deze rij is niet als één waarde te bewerken.
    if (props.spec.nvt) return { soort: 'uit', reden: props.spec.nvt };
    // De graafversie meelezen houdt de stand reactief: een mutatie of een
    // bronwissel kan een veld van gelockt naar bewerkbaar brengen.
    void graafVersie();
    return knoopIri() ? knoopIriStand(props.spec.term) : veldStand(props.spec.term, pred());
  };
  return (
    <Show when={weergave.editMode} fallback={props.lees()}>
      {/* DE NODE-ID TAKT HIER AF, VÓÓR de stand-poort (fixronde 9 sep 2026).
          Hij bouwt zijn gedimde vorm ZELF, want de gedeelde terugval hieronder
          rendert `props.lees()` — bij dit veld een leeg kind, want de kaartkop
          draagt in de leesstand met opzet geen IRI. Daar kwam de gelockte
          node-id als een kale ✎ zonder tekst en zonder schil uit. Zie de kop van
          `KnoopIriVeld`. */}
      <Show
        when={knoopIri()}
        fallback={(
          <Show
            when={stand().soort === 'aan'}
            fallback={(
              <GedimdVeld
                stand={stand()}
                lees={props.lees}
                zonderPotlood={props.spec.zonderPotlood}
              />
            )}
          >
            <Show
              when={props.spec.soort === 'iri'}
              fallback={<TekstVeld spec={props.spec} pred={pred} lees={props.lees} />}
            >
              <IriVeld spec={props.spec} pred={pred} lees={props.lees} />
            </Show>
          </Show>
        )}
      >
        <KnoopIriVeld spec={props.spec} stand={stand()} />
      </Show>
    </Show>
  );
}
