// DE SLEEPLAAG: het spookje op het scherm, en de luisteraars eronder.
//
// ÉÉN MONTAGEPUNT VOOR HET HELE GEBAAR. Deze component hoort precies één keer
// in de bewerkchrome te staan (zie het report van deze lane). Zij doet twee
// dingen en verder niets:
//   1. `koppelSleeplagen()` bij het monteren — pointermove/up/cancel en de
//      Escape-laag aan het VENSTER, en weer los bij het opruimen. Dat is meteen
//      de reden dat ze een component is en geen module-scope-aanroep: de
//      bewerklaag wordt lazy geladen en kan weer losgelaten worden, en dan
//      horen die vier luisteraars mee te verdwijnen.
//   2. het spookje uittekenen zolang er een sleep loopt.
//
// De VORM van het spookje komt uit ../sleep.tsx (golf A); hier staat alleen
// wanneer hij er is en waar hij hangt.
import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { onCleanup, onMount } from 'solid-js';
import { SleepSpook } from '../sleep.jsx';
import { koppelSleeplagen, sleepItem, sleepPositie } from './sleepgebaar.js';

export function SleepLaag(): JSX.Element {
  onMount(() => {
    const los = koppelSleeplagen();
    onCleanup(los);
  });
  return (
    <Show when={sleepItem()}>{(item) => (
      <SleepSpook
        naam={item().label}
        x={sleepPositie().x}
        y={sleepPositie().y}
      />
    )}</Show>
  );
}
