// HET SLEEPGEBAAR: grepen, drop-doelen, de Alt-kopie en de annulering.
//
// Gedragsbron: het sleep-blok van viewer-bevroren/assets/doc.js (fase C taak 8,
// r.10890-11124) en de ledger-rulings daarbij — de mutaties lopen via
// `moveAttached` / `linkAttached` / `verplaatsConstraint` uit de modellaag,
// altijd door `voerUit` heen zodat één sleep één undo-stap is.
//
// DE ARBEIDSDELING IN DEZE MAP:
//   ../sleep.tsx        de VORMEN (spookje, actie-zone, klassenamen) — golf A;
//   sleepgebaar.ts      dit bestand: de STAND van één gebaar en zijn mutatie;
//   sleeplaag.tsx       het spookje op het scherm + de document-luisteraars.
//
// PUUR GENOEG OM TE TOETSEN, NIET PUURDER. Deze module raakt de DOM (klassen op
// drop-doelen, een klasse op <body>) omdat het gebaar dáár leeft; wat zij niet
// doet is renderen. Het spookje is een signaal (`sleepItem`/`sleepPositie`) dat
// `SleepLaag` uittekent — in de bevroren viewer was dat een losse div die de
// module zelf aan <body> hing, en die vorm zou in Solid buiten de boom vallen.
import { createSignal, onCleanup } from 'solid-js';
import {
  DROPDOEL as DROPDOEL_JS, SLEEPITEM as SLEEPITEM_JS,
  geldigeDropDoelen as geldigeDropDoelenJs, linkAttached as linkAttachedJs,
  moveAttached as moveAttachedJs, termSleutel as termSleutelJs,
  verplaatsConstraint as verplaatsConstraintJs,
} from '../../../model/edit.js';
import type { Term } from '../../../model-grens.js';
import { graafVersie, model } from '../../../stores/corpus.js';
import { bewerkbaar, bewerkbron, voerUit } from '../../../stores/bewerk.js';
import type { Schrijfstore } from '../../../stores/bewerk.js';
import { tekst } from '../../../stores/weergave.js';
import { termVan } from '../integratie/anker.js';
import { DROP_DOEL, DROP_DOEL_ACTIEF } from '../sleep.jsx';
import { actieStand } from '../strook.jsx';
import type { IcoonStand } from '../strook.jsx';

// --- De grens naar de (JavaScript-)modellaag ---------------------------------
// Zelfde afspraak als model-grens.ts: één cast op de grens in plaats van een
// cast per aanroepplek. De SOORT-namen zijn een contract tussen de pure functie
// en deze module (edit.js r.759-765) en worden daarom doorgegeven, niet
// nagebouwd.
export const DROPDOEL = DROPDOEL_JS as { KAART: string; REGEL: string; ACTIE: string };
export const SLEEPITEM = SLEEPITEM_JS as { KNOOP: string; VOORWAARDE: string };

/** Wat er gesleept wordt. `ouder`+`pred` zijn de KOPPELING waaraan het hangt:
 *  bij een knoop de echte (ouder, predicaat)-triple, bij een voorwaarde de
 *  REGEL plus `'constraint'`/`'refinement'` — verplaatsConstraint zoekt de
 *  actie-knoop zelf op, dus de aanroeper hoeft die blank node nooit te kennen. */
export interface SleepItem {
  soort: string;
  term: Term;
  ouder?: Term | null;
  pred?: string;
  label?: string;
}

/** Eén geldig doel: waar het item mag landen en onder welk predicaat. */
export interface SleepDoel { soort: string; term: Term; pred: string }

type Mag = (term: Term, soort: string, pred: string) => boolean;

const geldigeDropDoelen = geldigeDropDoelenJs as unknown as
  (m: unknown, item: SleepItem, opts?: { mag?: Mag }) => SleepDoel[];
const termSleutel = termSleutelJs as unknown as (term: Term | null | undefined) => string;
const moveAttached = moveAttachedJs as unknown as (store: Schrijfstore, fromParent: unknown,
  fromPred: unknown, term: unknown, toParent: unknown, toPred: unknown) => void;
const linkAttached = linkAttachedJs as unknown as
  (store: Schrijfstore, toParent: unknown, toPred: unknown, term: unknown) => void;
const verplaatsConstraint = verplaatsConstraintJs as unknown as (store: Schrijfstore,
  from: { parent: unknown; pred: string }, cTerm: unknown,
  to: { parent: unknown; pred: string }, opts?: { kopie?: boolean }) => void;

// --- De registry van drop-zones ----------------------------------------------
// GEEN LIVE DOM-QUERY (doc.js r.10897): elke kaartkop, regelrij en actie-zone
// meldt zich bij het TEKENEN aan en weer af bij het opruimen. Een querySelectorAll
// bij elke sleep zou bij honderden kaarten de hele pagina aflopen, en — belangrijker
// — de UI zou dan een tweede adresseringsweg naast `data-ref` hebben.

interface Zone { node: HTMLElement; soort: string; term: Term }
let zones: Zone[] = [];

const sleutel = (soort: string, term: Term): string => `${soort}|${termSleutel(term)}`;

/** DE BODY-KLASSE VAN EEN LOPENDE SLEEP. Zij staat aan twee kanten — hier en in
 *  bewerk.css (`body.sleept-voorwaarde .actie-drop-zone`) — en golf A heeft die
 *  kant al als CONSTANTE vastgelegd (`SLEEPT_VOORWAARDE` in ../sleep.tsx) juist
 *  om losse tekenreeksen te vermijden. Deze functie bouwt hem uit de soort, en
 *  een test legt de uitkomst naast die constante (review M-2): zo blijft de
 *  vorm generiek voor beide sleepsoorten zonder dat de twee kanten kunnen
 *  verlopen. */
export const bodyKlasse = (soort: string): string => `sleept-${soort}`;

/** Meld één drop-zone aan; de teruggegeven functie meldt hem weer af.
 *
 *  DE HOVER-AFHANDELING ZIT HIER, bij de registratie, en niet bij het starten
 *  van een sleep: zo hoeft er per gebaar geen listener bijgeplakt en weer
 *  losgehaald te worden, en werkt de guard (`if (!stand)`) een toevallige hover
 *  buiten een sleep vanzelf weg.
 *
 *  DROP-DOELEN NESTELEN — de actie-zone ligt IN de regelbalk, die zelf ook een
 *  doel is. `pointerenter`/`pointerleave` zijn daarop gebouwd, maar dan moet de
 *  hover als een STAPEL bijgehouden worden: wie de zone verlaat hangt nog altijd
 *  boven de balk. Eén enkel `laatsteDoel` zou daar op null vallen en de drop in
 *  het niets laten landen. */
export function meldDropZone(node: HTMLElement, soort: string, term: Term): () => void {
  if (!node || !term || typeof node.addEventListener !== 'function') return () => {};
  const zone: Zone = { node, soort, term };
  zones.push(zone);
  const binnen = (): void => {
    if (!stand) return;
    const pred = stand.doelen.get(sleutel(soort, term));
    if (pred === undefined) return;
    zetHover([...hover(), { soort, term, pred }]);
    node.classList.add(DROP_DOEL_ACTIEF);
  };
  const buiten = (): void => {
    if (!stand) return;
    zetHover(hover().filter((d) => termSleutel(d.term) !== termSleutel(term) || d.soort !== soort));
    node.classList.remove(DROP_DOEL_ACTIEF);
  };
  node.addEventListener('pointerenter', binnen);
  node.addEventListener('pointerleave', buiten);
  return () => {
    node.removeEventListener('pointerenter', binnen);
    node.removeEventListener('pointerleave', buiten);
    node.classList.remove(DROP_DOEL, DROP_DOEL_ACTIEF);
    zones = zones.filter((z) => z !== zone);
  };
}

/** De vorm voor een component: `ref={(el) => dropDoel(el, DROPDOEL.KAART, term)}`.
 *  Meldt af bij het opruimen van de component waarin hij wordt aangeroepen. */
export function dropDoel(node: HTMLElement | null, soort: string, term: Term | null): void {
  if (!node || !term) return;
  const los = meldDropZone(node, soort, term);
  onCleanup(los);
}

// --- De stand van één gebaar --------------------------------------------------

interface Stand {
  item: SleepItem;
  /** sleutel(soort, term) -> predicaat waaronder het item daar zou landen. */
  doelen: Map<string, string>;
  pointerId: number | undefined;
}

let stand: Stand | null = null;
const [sleepItem, zetSleepItem] = createSignal<SleepItem | null>(null);
const [sleepPositie, zetPositie] = createSignal<{ x: number; y: number }>({ x: 0, y: 0 });
const [hover, zetHover] = createSignal<SleepDoel[]>([]);

export { sleepItem, sleepPositie };

/** Waar het loslaten NU op zou landen: de bovenste (diepst genestelde) van de
 *  hover-stapel. */
export function huidigDoel(): SleepDoel | null {
  const h = hover();
  return h.length ? h[h.length - 1] : null;
}

// MAG ER OP DIT DOEL GEDROPT WORDEN? Het bewerkbaarheidsfilter dat
// geldigeDropDoelen per kandidaat aanroept.
//
// EEN VEREENVOUDIGING T.O.V. DE BEVROREN VIEWER, en niet er één van gemak. Daar
// waren het twee toetsen: `knoopInSchrijfbron` voor 'kaart'/'regel' (er komt
// alleen een koppeling BIJ) en de veld-fijne `bewerkbaarVeld(term, odrl:action)`
// voor 'actie' (verplaatsConstraint kan de bestaande odrl:action herwikkelen).
// Die tweedeling bestond omdat er MEER schrijfbronnen naast elkaar konden staan
// en een knoop dus over twee bronnen verdeeld kon raken. Sinds het
// één-bewerkbron-besluit (spec dt3, 6 sep) is de grens knoop-grof en valt hij
// voor beide gevallen samen met `bewerkbaar()`. De SOORT blijft in de signatuur
// staan: hij is het contract van de pure functie, en wie de grens ooit weer
// veld-fijn maakt heeft hem hier nodig zonder de aanroepketen te verbouwen.
const magDroppen: Mag = (term) => magBewerken(term);

// --- DE CACHE, EN WAAROM ZIJ ER MOET ZIJN (review I-5) -----------------------
//
// `sleepGreep` draait PER RIJ, PER RENDERGANG: elke greep wil weten of zij aan
// mag staan, en dat antwoord hangt aan de volledige kandidatenlijst. Een
// voorwaarderij vraagt twee kandidaten per regel-achtige knoop, en elke
// kandidaat kost een `getQuads`. Bij R regels en V voorwaarderijen is dat
// 2·R·V store-lookups per gang. Gemeten in jsdom (alleen de aanroepen, geen
// DOM): 20 kaarten/300 rijen 81 ms, 40/960 1.028 ms, 60/1.920 3.866 ms — en
// `voerUit` triggert een volle herrender na élke mutatie.
//
// De bevroren viewer had die kosten niet: die rekende de doelen pas uit in
// `startKnoopSleep`. Het is de prijs van de (goede) ruling "uit mét reden" —
// een greep die zegt waarom zij niet kan, moet dat vooraf weten. De prijs is
// echter alleen de EERSTE keer terecht: binnen één generatie van (graaf,
// bewerkbron, model) is het antwoord per knoop en per item constant.
//
// DE GENERATIE, niet de tijd. `graafVersie()` telt elke invalidatie mee (ook de
// gerichte, corpus.ts r.888), de bewerkbron bepaalt wat bewerkbaar is, en het
// modelobject verandert bij elke herbouw. Verandert één van de drie, dan valt
// de hele cache weg — er is dus geen weg waarlangs een verouderd antwoord
// blijft staan. Reactief gelezen, zodat een greep na een mutatie vanzelf
// herrekent.
let cacheStempel = '';
let cacheModel: unknown = null;
const doelCache = new Map<string, SleepDoel[]>();
const magCache = new Map<string, boolean>();

/** Cachesleutel voor een term; verdraagt een kale IRI én de WORKER-HANDLE. */
const sleutelVanTerm = (t: Term | string | null | undefined): string =>
  (typeof t === 'string' ? t : termSleutel(t as Term));

/** EEN ECHTE TERM UIT WAT HET MODEL LEVERT.
 *
 *  Het model komt via structured clone uit de worker: `termType` en `value` zijn
 *  prototype-getters en overleven dat niet, dus wat `p.term` oplevert is `{ id }`.
 *  Alles ONDER deze module verwacht een echte term — `bewerkbaar()` zoekt ermee
 *  in de N3-store, en `moveAttached`/`linkAttached` schrijven ermee. Geef je de
 *  kale handle door, dan gooit N3 letterlijk `Unexpected termType: undefined`, en
 *  dat sloopt de rendering van de kaart eromheen.
 *
 *  Gemeten in de GEBOUWDE app vóór deze hydratatie: één `PAGEERROR: Unexpected
 *  termType: undefined`, nul regelrijen, nul grepen — terwijl alle jsdom-tests
 *  groen stonden (daar wordt het model in dezelfde draad gebouwd en zijn de
 *  termen echt). Dit is dezelfde valstrik die de ghost-lane als "de vondst" in
 *  haar report zette; `termVan` is de huisdecoder ervoor. */
const echteTerm = (t: Term | null | undefined): Term | null => termVan(t);

function versGeneratie(m: unknown): void {
  const bron = bewerkbron();
  const stempel = `${graafVersie()}|${bron ? bron.graph : ''}`;
  if (stempel === cacheStempel && m === cacheModel) return;
  cacheStempel = stempel;
  cacheModel = m;
  doelCache.clear();
  magCache.clear();
}

/** Is deze knoop bewerkbaar? Gecachet binnen de generatie: dit is de lookup die
 *  in de meting hierboven het werk deed. */
function magBewerken(term: Term | string | null | undefined): boolean {
  versGeneratie(model());
  const k = sleutelVanTerm(term);
  let v = magCache.get(k);
  if (v === undefined) {
    // Gehydrateerd: `bewerkbaar` zoekt in de N3-store, en die weigert een kale
    // worker-handle met een uitzondering. Zie `echteTerm` hierboven.
    v = bewerkbaar(typeof term === 'string' ? term : echteTerm(term));
    magCache.set(k, v);
  }
  return v;
}

/** De geldige doelen voor dit item, bewerkbaarheid inbegrepen. */
export function geldigeDoelen(item: SleepItem): SleepDoel[] {
  const m = model();
  if (!m || !item || !item.term) return [];
  versGeneratie(m);
  const k = `${item.soort}|${sleutelVanTerm(item.term)}|${sleutelVanTerm(item.ouder)}|${item.pred || ''}`;
  const bekend = doelCache.get(k);
  if (bekend) return bekend;
  // DE DOELEN KOMEN UIT HET MODEL en dragen dus worker-handles; ze gaan hierna
  // naar de zone-registry (als sleutel) en naar `moveAttached`/`linkAttached`
  // (als schrijfterm). Hydrateren op precies deze grens: één plek, en daaronder
  // ziet niemand de handle meer.
  const doelen = geldigeDropDoelen(m, item, { mag: magDroppen })
    .map((d) => ({ ...d, term: echteTerm(d.term) || d.term }));
  doelCache.set(k, doelen);
  return doelen;
}

/** Hoort dit pointer-event bij de LOPENDE sleep? Eén gebaar tegelijk: met twee
 *  vingers op een aanraakscherm lopen er anders twee pointers door elkaar en
 *  zou de pointerup van vinger 1 de drop van vinger 2 uitvoeren — op de
 *  coördinaten van vinger 1. Alleen weigeren als positief vaststaat dat het een
 *  ANDERE pointer is: een event zonder pointerId (synthetisch, een teststub)
 *  mag de sleep nog gewoon beëindigen, anders blijft er een spook staan dat door
 *  niets meer op te ruimen is. */
function andereVinger(e: { pointerId?: number } | null): boolean {
  return !!stand && stand.pointerId !== undefined && !!e && e.pointerId !== undefined
    && e.pointerId !== stand.pointerId;
}

type Gebaar = MouseEvent & { pointerId?: number };

/** Start een sleep. `false` = er begint niets, en dan hoort er ook geen spook te
 *  verschijnen: een greep die nergens kan landen (één kaart, geen andere regels)
 *  zou anders een gebaar beloven dat niet bestaat. */
export function startSleep(e: Gebaar, item: SleepItem): boolean {
  if (e && e.button) return false;
  // EERST de lopende sleep afbreken. Een tweede pointerdown op een greep — een
  // tweede vinger, een dubbelklik — betekent dat het vorige gebaar is opgegeven.
  // Zonder dit overschrijft de stand zichzelf en blijven het eerste spook, zijn
  // oplicht-klassen en zijn body-klasse voorgoed staan.
  if (stand) annuleerSleep();
  if (!item || !item.term) return false;
  const doelen = geldigeDoelen(item);
  if (!doelen.length) return false;
  if (e && typeof e.preventDefault === 'function') e.preventDefault();
  losImplicieteCapture(e);
  stand = {
    item,
    doelen: new Map(doelen.map((d) => [sleutel(d.soort, d.term), d.pred])),
    pointerId: e ? e.pointerId : undefined,
  };
  zetSleepItem(() => item);
  zetHover([]);
  zetPositie({ x: e ? e.clientX : 0, y: e ? e.clientY : 0 });
  for (const z of zones) {
    if (stand.doelen.has(sleutel(z.soort, z.term))) z.node.classList.add(DROP_DOEL);
  }
  // De actie-refinement-zones staan ALLEEN tijdens een voorwaarde-sleep in beeld
  // (bewerk.css, `body.sleept-voorwaarde`): bij elke andere sleep zijn ze geen
  // doel, en daarbuiten zouden ze op elke regelrij een los "↳ Actie" achterlaten.
  document.body?.classList.add(bodyKlasse(item.soort));
  return true;
}

// Bij aanraking en pen zet de browser IMPLICIETE pointer-capture op de greep:
// alle verdere pointer-events gaan dan naar de greep en de drop-zones zien nooit
// een pointerenter. Loslaten dus, anders werkt de sleep alleen met de muis.
function losImplicieteCapture(e: Gebaar): void {
  const greep = (e && (e.currentTarget || e.target)) as HTMLElement | null;
  if (!greep || e.pointerId === undefined) return;
  if (typeof greep.releasePointerCapture !== 'function'
    || typeof greep.hasPointerCapture !== 'function') return;
  if (greep.hasPointerCapture(e.pointerId)) greep.releasePointerCapture(e.pointerId);
}

function opruim(): void {
  if (!stand) return;
  for (const z of zones) z.node.classList.remove(DROP_DOEL, DROP_DOEL_ACTIEF);
  document.body?.classList.remove(bodyKlasse(stand.item.soort));
  stand = null;
  zetSleepItem(null);
  zetHover([]);
}

/** Afbreken zonder te droppen. ONVOORWAARDELIJK — Escape, een nieuwe render, een
 *  tweede sleep die begint — en dus zonder pointerId-toets: wachten op de juiste
 *  vinger zou hier een spook laten staan. */
export function annuleerSleep(): void {
  opruim();
}

/** Voer de gedropte mutatie uit. Alt = HERGEBRUIKEN (linkAttached /
 *  verplaatsConstraint met `{ kopie: true }`) in plaats van verplaatsen: de
 *  bron-koppeling blijft dan staan. `groep: true` maakt er één undo-stap van. */
function voerDropUit(item: SleepItem, doel: SleepDoel, alt: boolean): Promise<boolean> {
  if (item.soort === SLEEPITEM.VOORWAARDE) {
    const van = { parent: item.ouder, pred: item.pred as string };
    const naar = { parent: doel.term, pred: doel.pred };
    return voerUit((f) => verplaatsConstraint(f, van, item.term, naar, alt ? { kopie: true } : {}),
      { groep: true });
  }
  if (alt) {
    return voerUit((f) => linkAttached(f, doel.term, doel.pred, item.term), { groep: true });
  }
  return voerUit(
    (f) => moveAttached(f, item.ouder, item.pred, item.term, doel.term, doel.pred),
    { groep: true },
  );
}

function beweeg(e: Gebaar): void {
  if (!stand || andereVinger(e)) return;
  zetPositie({ x: e.clientX, y: e.clientY });
}

function eindig(e: Gebaar): void {
  if (!stand || andereVinger(e)) return;
  const { item } = stand;
  const doel = huidigDoel();
  const alt = !!(e && e.altKey);
  opruim();
  if (doel) void voerDropUit(item, doel, alt);
}

/** De gebeurtenis-ingang van het afbreken (pointercancel): negeert een vreemde
 *  vinger, net als move en up. */
function annuleerVanPointer(e: Gebaar): void {
  if (!stand || andereVinger(e)) return;
  annuleerSleep();
}

// --- De lagen aan het venster -------------------------------------------------

/** Hang de vier luisteraars op; de teruggegeven functie haalt ze weer weg.
 *
 *  AAN HET VENSTER EN NIET AAN HET DOCUMENT, en dat is een AFWIJKING van de
 *  bevroren viewer met een reden. Daar hingen paneel, sectiefilter en zijnav
 *  allemaal in de BUBBELFASE, en volstond capture-op-document om er als eerste
 *  bij te zijn. In de nieuwe app hangt het invulling-paneel zélf in de
 *  capture-fase aan het document (invulling.tsx r.1037) — en tussen twee
 *  capture-luisteraars op HETZELFDE knooppunt beslist de registratievolgorde.
 *  Het paneel zit in de leeschunk en staat er dus altijd eerder dan deze lazy
 *  bewerklaag; capture-op-document zou de sleep als TWEEDE laag opleveren, en
 *  dan sluit één Escape tijdens een sleep het paneel in plaats van het gebaar
 *  af te breken. Het venster ligt in het pad vóór het document, dus daar is
 *  "eerst" geen kwestie van volgorde meer.
 *
 *  DE LAAGORDE IS HET CONTRACT: sleep → veld → paneel → zijnav. Het veld stopt
 *  zijn Escape in de TARGET-fase (veld.tsx), het paneel in capture op het
 *  document, de zijnav in de bubbel. De guard (`!stand`) houdt deze laag smal:
 *  buiten een lopende sleep raakt zij geen enkele Escape aan. */
export function koppelSleeplagen(): () => void {
  if (typeof window === 'undefined' || !window.addEventListener) return () => {};
  const opToets = (e: KeyboardEvent): void => {
    if (e.key !== 'Escape' || !stand) return;
    e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else e.stopPropagation();
    annuleerSleep();
  };
  window.addEventListener('pointermove', beweeg as EventListener);
  window.addEventListener('pointerup', eindig as EventListener);
  window.addEventListener('pointercancel', annuleerVanPointer as EventListener);
  window.addEventListener('keydown', opToets, true);
  return () => {
    window.removeEventListener('pointermove', beweeg as EventListener);
    window.removeEventListener('pointerup', eindig as EventListener);
    window.removeEventListener('pointercancel', annuleerVanPointer as EventListener);
    window.removeEventListener('keydown', opToets, true);
    annuleerSleep();
  };
}

// --- De greep -----------------------------------------------------------------

/** Kan dit item gesleept worden? Twee voorwaarden, en beide zijn ook de reden
 *  die de greep draagt als het niet kan:
 *   - er is een AANWIJSBARE KOPPELING (ouder + predicaat) die in de bewerkbron
 *     leeft — slepen verhuist precies dat ene triple;
 *   - en er is minstens één geldig DOEL.
 *
 *  De bevroren viewer toetste hier `magLosmaken` (taak 6): álle quads die een
 *  ✕ zou weghalen moeten bewerkbaar zijn, sluiting inbegrepen. Dat is voor een
 *  SLEEP te streng — `moveAttached` raakt alleen de koppel-triple en laat de
 *  knoop staan waar hij staat — dus de toets is hier de knoop-grove
 *  bewerkbaarheid van de OUDER, die die koppeling bezit. */
export type Sleepbaarheid = 'kan' | 'geenKoppeling' | 'gelockt' | 'geenDoel';

/** DE DRIE TOETSEN, OP ÉÉN PLEK (review M-3). `kanSlepen` en `sleepGreep`
 *  stelden dezelfde vragen in twee vormen, en niets hield die twee gelijk. Nu
 *  is er één beslisser en zijn de andere twee er de lezingen van: een boolean
 *  voor wie alleen wil weten óf het kan, en een tekst voor de greep die moet
 *  zeggen waarom niet. */
export function sleepbaarheid(item: SleepItem): Sleepbaarheid {
  if (!item || !item.term || !item.ouder || !item.pred) return 'geenKoppeling';
  if (!magBewerken(item.ouder)) return 'gelockt';
  if (!geldigeDoelen(item).length) return 'geenDoel';
  return 'kan';
}

export function kanSlepen(item: SleepItem): boolean {
  return sleepbaarheid(item) === 'kan';
}

/** De ⠿-stand voor `ActieStrook`. Niets verborgen: kan het niet, dan blijft de
 *  greep staan met de reden erin — dezelfde drie redenen als in de bevroren
 *  viewer, plus de vierde die daar alleen als stille `return` bestond ("er is
 *  geen andere plek"). */
const REDEN: Record<Exclude<Sleepbaarheid, 'kan'>, string> = {
  geenKoppeling: 'edit.sleepGeenKoppeling',
  gelockt: 'edit.sleepGelockt',
  geenDoel: 'edit.sleepGeenDoel',
};

export function sleepGreep(item: SleepItem, titel?: string): IcoonStand {
  const uitleg = titel || tekst('edit.sleepGreep');
  const stand = sleepbaarheid(item);
  if (stand !== 'kan') {
    return actieStand({ mag: false, titel: uitleg, nvt: tekst(REDEN[stand]) });
  }
  return { aan: true, titel: uitleg, opPointerDown: (e) => { startSleep(e as Gebaar, item); } };
}
